#include "common.h"
#include <strings.h>

void fail(void) { exit(1); }

void* xmalloc(size_t n) { void* p = malloc(n ? n : 1); if (!p) { fputs("Out of memory\n", stderr); exit(1); } return p; }
void* xcalloc(size_t n, size_t sz) { void* p = calloc(n ? n : 1, sz ? sz : 1); if (!p) { fputs("Out of memory\n", stderr); exit(1); } return p; }
void* xrealloc(void* p, size_t n) { void* q = realloc(p, n ? n : 1); if (!q) { fputs("Out of memory\n", stderr); exit(1); } return q; }
char* xstrdup(const char* s) { char* r = strdup(s ? s : ""); if (!r) exit(1); return r; }
char* xstrndup(const char* s, size_t n) { char* r = strndup(s ? s : "", n); if (!r) exit(1); return r; }
int xsnprintf(char* buf, size_t len, const char* fmt, ...) {
   va_list ap; va_start(ap, fmt); int n = vsnprintf(buf, len, fmt, ap); va_end(ap);
   if (n < 0) n = 0; if ((size_t)n >= len) n = (int)len - 1; return n;
}
char* xasprintf(const char* fmt, ...) {
   va_list ap; va_start(ap, fmt); char* r = NULL; if (vasprintf(&r, fmt, ap) < 0) exit(1); va_end(ap); return r;
}
bool string_startsWith(const char* s, const char* prefix) { return strncmp(s, prefix, strlen(prefix)) == 0; }
char* string_trim(const char* s) {
   while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
   size_t n = strlen(s);
   while (n > 0 && (s[n-1] == ' ' || s[n-1] == '\t' || s[n-1] == '\n' || s[n-1] == '\r')) n--;
   return xstrndup(s, n);
}
char** string_split(const char* s, char sep, size_t* n) {
   size_t cap = 8, cnt = 0;
   char** out = xmalloc(cap * sizeof(char*));
   const char* p = s;
   for (;;) {
      const char* q = strchr(p, sep);
      size_t len = q ? (size_t)(q - p) : strlen(p);
      if (cnt + 2 > cap) { cap *= 2; out = xrealloc(out, cap * sizeof(char*)); }
      out[cnt++] = xstrndup(p, len);
      if (!q) break;
      p = q + 1;
   }
   out[cnt] = NULL;
   if (n) *n = cnt;
   return out;
}
void string_freeArray(char** a) { if (!a) return; for (size_t i = 0; a[i]; i++) free(a[i]); free(a); }

/* case-insensitive search; if multi, match is a '|' separated list of terms */
bool string_containsI(const char* s, const char* match, bool multi) {
   if (!multi) return strcasestr(s, match) != NULL;
   const char* p = match;
   for (;;) {
      const char* q = strchr(p, '|');
      size_t len = q ? (size_t)(q - p) : strlen(p);
      char* term = xstrndup(p, len);
      bool found = strcasestr(s, term) != NULL;
      free(term);
      if (found) return true;
      if (!q) return false;
      p = q + 1;
   }
}

Vector* Vector_new(void (*freeFn)(void*)) { Vector* v = xcalloc(1, sizeof(Vector)); v->cap = 16; v->items = xcalloc(v->cap, sizeof(void*)); v->freeFn = freeFn; return v; }
void Vector_prune(Vector* v) { if (v->freeFn) for (int i = 0; i < v->size; i++) if (v->items[i]) v->freeFn(v->items[i]); v->size = 0; }
void Vector_delete(Vector* v) { if (!v) return; Vector_prune(v); free(v->items); free(v); }
static void Vector_grow(Vector* v) { if (v->size >= v->cap) { v->cap *= 2; v->items = xrealloc(v->items, v->cap * sizeof(void*)); } }
void Vector_add(Vector* v, void* item) { Vector_grow(v); v->items[v->size++] = item; }
void Vector_insert(Vector* v, int idx, void* item) {
   if (idx < 0) idx = 0; if (idx > v->size) idx = v->size;
   Vector_grow(v);
   memmove(&v->items[idx + 1], &v->items[idx], (v->size - idx) * sizeof(void*));
   v->items[idx] = item; v->size++;
}
void* Vector_remove(Vector* v, int idx) {
   if (idx < 0 || idx >= v->size) return NULL;
   void* it = v->items[idx];
   memmove(&v->items[idx], &v->items[idx + 1], (v->size - idx - 1) * sizeof(void*));
   v->size--;
   return it;
}
void* Vector_get(const Vector* v, int idx) { if (idx < 0 || idx >= v->size) return NULL; return v->items[idx]; }
void Vector_set(Vector* v, int idx, void* item) {
   if (idx < 0) return;
   while (idx >= v->size) { Vector_grow(v); v->items[v->size++] = NULL; }
   if (v->items[idx] && v->freeFn && v->items[idx] != item) v->freeFn(v->items[idx]);
   v->items[idx] = item;
}
int Vector_size(const Vector* v) { return v ? v->size : 0; }
void Vector_moveUp(Vector* v, int idx) { if (idx <= 0 || idx >= v->size) return; void* t = v->items[idx]; v->items[idx] = v->items[idx-1]; v->items[idx-1] = t; }
void Vector_moveDown(Vector* v, int idx) { if (idx < 0 || idx >= v->size - 1) return; void* t = v->items[idx]; v->items[idx] = v->items[idx+1]; v->items[idx+1] = t; }
void Vector_sort(Vector* v, int (*cmp)(const void*, const void*)) { if (v->size > 1) qsort(v->items, v->size, sizeof(void*), cmp); }
void Vector_insertionSort(Vector* v, int (*cmp)(const void*, const void*)) {
   for (int i = 1; i < v->size; i++) {
      void* t = v->items[i]; int j = i - 1;
      while (j >= 0 && cmp(&v->items[j], &t) > 0) { v->items[j+1] = v->items[j]; j--; }
      v->items[j+1] = t;
   }
}
EOF
echo ok"}

