#include "richstring.h"
#include "crt.h"

void RichString_begin(RichString* this) {
   memset(this, 0, sizeof(RichString));
   this->chptr = this->chstr;
   this->chcap = RICHSTRING_MAXLEN;
}

void RichString_delete(RichString* this) {
   if (this->chptr != this->chstr) { free(this->chptr); }
   this->chptr = this->chstr; this->chlen = 0; this->chcap = RICHSTRING_MAXLEN;
}

static void RichString_extend(RichString* this, int len) {
   if (len <= this->chcap) return;
   int newcap = MAXIMUM(len, this->chcap * 2);
   if (this->chptr == this->chstr) {
      this->chptr = xmalloc((newcap + 1) * sizeof(cchar_t));
      memcpy(this->chptr, this->chstr, (this->chlen + 1) * sizeof(cchar_t));
   } else {
      this->chptr = xrealloc(this->chptr, (newcap + 1) * sizeof(cchar_t));
   }
   this->chcap = newcap;
}

static void RichString_setLen(RichString* this, int len) {
   RichString_extend(this, len);
   this->chlen = len;
   memset(&this->chptr[len], 0, sizeof(cchar_t));
}

void RichString_rewind(RichString* this, int count) {
   RichString_setLen(this, MAXIMUM(0, this->chlen - count));
}
void RichString_prune(RichString* this) { RichString_setLen(this, 0); }
void RichString_prunen(RichString* this, int len) { if (len < this->chlen) RichString_setLen(this, len); }

void RichString_setAttrn(RichString* this, int attrs, int start, int charcount) {
   int end = MINIMUM(this->chlen, start + charcount);
   for (int i = start; i < end; i++) this->chptr[i].attr = attrs;
}
void RichString_setAttr(RichString* this, int attrs) { RichString_setAttrn(this, attrs, 0, this->chlen); }

void RichString_appendChr(RichString* this, int attrs, char c, int count) {
   int oldlen = this->chlen;
   RichString_setLen(this, oldlen + count);
   for (int i = oldlen; i < oldlen + count; i++) {
      this->chptr[i].attr = attrs;
      this->chptr[i].chars[0] = (unsigned char)c;
      this->chptr[i].chars[1] = 0;
   }
}

int RichString_appendnAscii(RichString* this, int attrs, const char* data, int len) {
   int oldlen = this->chlen;
   RichString_setLen(this, oldlen + len);
   for (int i = 0; i < len; i++) {
      this->chptr[oldlen + i].attr = attrs;
      this->chptr[oldlen + i].chars[0] = (unsigned char)data[i];
      this->chptr[oldlen + i].chars[1] = 0;
   }
   return len;
}
int RichString_appendAscii(RichString* this, int attrs, const char* data) { return RichString_appendnAscii(this, attrs, data, strlen(data)); }
int RichString_writeAscii(RichString* this, int attrs, const char* data) { RichString_prune(this); return RichString_appendAscii(this, attrs, data); }

static inline int wcwidth_safe(wchar_t c) { int w = wcwidth(c); return w < 0 ? 1 : w; }

int RichString_appendnWideColumns(RichString* this, int attrs, const char* data, int len, int* columns) {
   int oldlen = this->chlen;
   if (!CRT_utf8) {
      int n = RichString_appendnAscii(this, attrs, data, len);
      if (columns) *columns = n;
      return n;
   }
   /* decode utf-8 */
   wchar_t* wbuf = xmalloc((len + 1) * sizeof(wchar_t));
   mbstate_t st; memset(&st, 0, sizeof(st));
   int n = 0; size_t pos = 0;
   while (pos < (size_t)len) {
      wchar_t wc;
      size_t r = mbrtowc(&wc, data + pos, len - pos, &st);
      if (r == (size_t)-1 || r == (size_t)-2) { wc = L'?'; r = 1; memset(&st, 0, sizeof(st)); }
      else if (r == 0) { break; }
      if (wc == 0) { wc = L' '; }
      wbuf[n++] = wc;
      pos += r;
   }
   int cols = 0;
   int maxcols = columns ? *columns : -1;
   int used = 0;
   for (int i = 0; i < n; i++) {
      int w = wcwidth_safe(wbuf[i]);
      if (maxcols >= 0 && cols + w > maxcols) break;
      cols += w; used++;
   }
   RichString_setLen(this, oldlen + used);
   for (int i = 0; i < used; i++) {
      this->chptr[oldlen + i].attr = attrs;
      this->chptr[oldlen + i].chars[0] = wbuf[i];
      this->chptr[oldlen + i].chars[1] = 0;
   }
   free(wbuf);
   if (columns) *columns = cols;
   return used;
}

int RichString_appendnWide(RichString* this, int attrs, const char* data, int len) {
   return RichString_appendnWideColumns(this, attrs, data, len, NULL);
}
int RichString_appendWide(RichString* this, int attrs, const char* data) { return RichString_appendnWide(this, attrs, data, strlen(data)); }
int RichString_writeWide(RichString* this, int attrs, const char* data) { RichString_prune(this); return RichString_appendWide(this, attrs, data); }

int RichString_findChar(const RichString* this, char c, int start) {
   for (int i = start; i < this->chlen; i++) if (this->chptr[i].chars[0] == (wchar_t)(unsigned char)c) return i;
   return -1;
}
char RichString_getCharVal(const RichString* this, int i) { if (i < 0 || i >= this->chlen) return 0; return (char)this->chptr[i].chars[0]; }

void RichString_printoffnVal(RichString* this, int y, int x, int off, int n) {
   if (off < 0) off = 0;
   if (off >= this->chlen) return;
   if (n > this->chlen - off) n = this->chlen - off;
   if (n <= 0) return;
   mvadd_wchnstr(y, x, &this->chptr[off], n);
}
void RichString_printVal(RichString* this, int y, int x) { RichString_printoffnVal(this, y, x, 0, this->chlen); }

int RichString_strwidth(const char* s) {
   if (!CRT_utf8) return (int)strlen(s);
   int w = 0; mbstate_t st; memset(&st, 0, sizeof(st));
   size_t len = strlen(s), pos = 0;
   while (pos < len) {
      wchar_t wc; size_t r = mbrtowc(&wc, s + pos, len - pos, &st);
      if (r == (size_t)-1 || r == (size_t)-2) { w++; pos++; memset(&st, 0, sizeof(st)); continue; }
      if (r == 0) break;
      w += wcwidth_safe(wc); pos += r;
   }
   return w;
}
