/* ---- Screen settings ---- */

void ScreenSettings_delete(ScreenSettings* ss) {
   if (!ss) return;
   free(ss->heading); free(ss->dynamic); free(ss->fields); free(ss);
}

int ScreenSettings_getActiveSortKey(const ScreenSettings* ss) {
   return ss->treeView ? (ss->treeViewAlwaysByPID ? PID : ss->treeSortKey) : ss->sortKey;
}
int ScreenSettings_getActiveDirection(const ScreenSettings* ss) {
   return ss->treeView ? ss->treeDirection : ss->direction;
}

void ScreenSettings_setSortKey(ScreenSettings* ss, int sortKey) {
   if (ss->treeViewAlwaysByPID || !ss->treeView) {
      ss->sortKey = sortKey;
      ss->direction = Process_fields[sortKey].defaultSortDesc ? -1 : 1;
      ss->treeView = false;
   } else {
      ss->treeSortKey = sortKey;
      ss->treeDirection = Process_fields[sortKey].defaultSortDesc ? -1 : 1;
   }
}

void ScreenSettings_invertSortOrder(ScreenSettings* ss) {
   int* attr = (ss->treeView && !ss->treeViewAlwaysByPID) ? &ss->treeDirection : &ss->direction;
   *attr = (*attr == 1) ? -1 : 1;
}

void ScreenSettings_readFields(ScreenSettings* ss, const char* line) {
   size_t n;
   char** ids = string_split(line, ' ', &n);
   int* fields = xcalloc(LAST_PROCESSFIELD + 1, sizeof(int));
   unsigned int j = 0;
   for (size_t i = 0; ids[i] && j < LAST_PROCESSFIELD; i++) {
      if (!ids[i][0]) continue;
      int f = 0;
      if (isdigit((unsigned char)ids[i][0])) {
         f = Fields_fromWrittenId(atoi(ids[i]));
      } else {
         f = Fields_fromName(ids[i]);
      }
      if (f) fields[j++] = f;
   }
   fields[j] = 0;
   string_freeArray(ids);
   free(ss->fields);
   ss->fields = fields;
   ss->flags = 0;
   for (unsigned int i = 0; fields[i]; i++) ss->flags |= Process_fields[fields[i]].flags;
}

static ScreenSettings* ScreenSettings_newBlank(const char* name) {
   ScreenSettings* ss = xcalloc(1, sizeof(ScreenSettings));
   ss->heading = xstrdup(name);
   ss->fields = xcalloc(LAST_PROCESSFIELD + 1, sizeof(int));
   ss->direction = 1;
   ss->treeDirection = 1;
   ss->sortKey = PID;
   ss->treeSortKey = PID;
   return ss;
}

ScreenSettings* Settings_newScreen(Settings* this, const char* name, const char* columns) {
   ScreenSettings* ss = ScreenSettings_newBlank(name);
   ScreenSettings_readFields(ss, columns);
   this->screens = xrealloc(this->screens, sizeof(ScreenSettings*) * (this->nScreens + 2));
   this->screens[this->nScreens] = ss;
   this->nScreens++;
   this->screens[this->nScreens] = NULL;
   return ss;
}

void Settings_deleteScreen(Settings* this, unsigned int idx) {
   if (idx >= this->nScreens) return;
   ScreenSettings_delete(this->screens[idx]);
   for (unsigned int i = idx; i < this->nScreens; i++) this->screens[i] = this->screens[i + 1];
   this->nScreens--;
}

ScreenSettings* Settings_defaultScreens(Settings* this) {
   if (this->nScreens) return this->screens[0];
   ScreenSettings* ss = Settings_newScreen(this, "Main", "PID USER PRIORITY NICE M_VIRT M_RESIDENT M_SHARE STATE PERCENT_CPU PERCENT_MEM TIME Command");
   ss->sortKey = PERCENT_CPU; ss->direction = -1; ss->treeSortKey = PID; ss->treeDirection = 1;
   ScreenSettings* io = Settings_newScreen(this, "I/O", "PID USER IO_PRIORITY IO_RATE IO_READ_RATE IO_WRITE_RATE Command");
   io->sortKey = IO_RATE; io->direction = -1; io->treeSortKey = PID; io->treeDirection = 1;
   return ss;
}

