static void MeterColumnSettings_clear(MeterColumnSettings* c) {
   string_freeArray(c->names); free(c->modes); c->names = NULL; c->modes = NULL; c->len = 0;
}

static void Settings_defaultMeters(Settings* this, unsigned int initialCpuCount) {
   int sizes[] = { 3, 3 };
   if (initialCpuCount > 4 && initialCpuCount <= 128) { sizes[1]++; }
   /* layout: two_50_50 */
   this->hLayout = HF_TWO_50_50;
   this->hColumns = xcalloc(4, sizeof(MeterColumnSettings));
   for (int i = 0; i < 2; i++) {
      this->hColumns[i].names = xcalloc(sizes[i] + 1, sizeof(char*));
      this->hColumns[i].modes = xcalloc(sizes[i] + 1, sizeof(int));
      this->hColumns[i].len = sizes[i];
   }
   int r = 0;
   if (initialCpuCount > 128) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs8"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs8"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 32) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs8"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs8"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 16) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs4"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs4"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 8) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs2"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs2"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 4) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs"); this->hColumns[1].modes[r++] = 1;
   } else {
      this->hColumns[0].names[0] = xstrdup("AllCPUs"); this->hColumns[0].modes[0] = 1;
   }
   this->hColumns[0].names[1] = xstrdup("Memory"); this->hColumns[0].modes[1] = 1;
   this->hColumns[0].names[2] = xstrdup("Swap"); this->hColumns[0].modes[2] = 1;
   this->hColumns[1].names[r] = xstrdup("Tasks"); this->hColumns[1].modes[r++] = 2;
   this->hColumns[1].names[r] = xstrdup("LoadAverage"); this->hColumns[1].modes[r++] = 2;
   this->hColumns[1].names[r] = xstrdup("Uptime"); this->hColumns[1].modes[r++] = 2;
}

static void readMeters(Settings* this, const char* line, unsigned int column) {
   if (column >= 4) return;
   MeterColumnSettings* c = &this->hColumns[column];
   string_freeArray(c->names);
   size_t n;
   c->names = string_split(line, ' ', &n);
   /* remove empty */
   size_t j = 0;
   for (size_t i = 0; i < n; i++) { if (c->names[i][0]) c->names[j++] = c->names[i]; else free(c->names[i]); }
   c->names[j] = NULL;
   c->len = j;
}

static void readMeterModes(Settings* this, const char* line, unsigned int column) {
   if (column >= 4) return;
   MeterColumnSettings* c = &this->hColumns[column];
   size_t n;
   char** modes = string_split(line, ' ', &n);
   free(c->modes);
   c->modes = xcalloc(n + 1, sizeof(int));
   size_t j = 0;
   for (size_t i = 0; i < n; i++) { if (modes[i][0]) c->modes[j++] = atoi(modes[i]); }
   string_freeArray(modes);
   /* the number of meters is governed by names */
}

void Settings_setHeaderLayout(Settings* this, HeaderLayout hLayout) {
   unsigned int oldColumns = HeaderLayout_layouts[this->hLayout].columns;
   unsigned int newColumns = HeaderLayout_layouts[hLayout].columns;
   if (newColumns < oldColumns) {
      /* move meters of removed columns into last remaining column */
      MeterColumnSettings* last = &this->hColumns[newColumns - 1];
      for (unsigned int i = newColumns; i < oldColumns; i++) {
         MeterColumnSettings* c = &this->hColumns[i];
         for (size_t k = 0; k < c->len; k++) {
            last->names = xrealloc(last->names, sizeof(char*) * (last->len + 2));
            last->modes = xrealloc(last->modes, sizeof(int) * (last->len + 2));
            last->names[last->len] = c->names[k]; c->names[k] = NULL;
            last->modes[last->len] = c->modes ? c->modes[k] : 1;
            last->len++;
            last->names[last->len] = NULL;
         }
         MeterColumnSettings_clear(c);
      }
   }
   this->hLayout = hLayout;
   this->changed = true;
}

