};

static bool readonly = false;
void Settings_enableReadonly(void) { readonly = true; }
bool Settings_isReadonly(void) { return readonly; }

/* ---- Screen settings ---- */

void ScreenSettings_delete(ScreenSettings* ss) {
   if (!ss) return;
   free(ss->heading); free(ss->dynamic); free(ss->fields); free(ss);
}

int ScreenSettings_getActiveSortKey(const ScreenSettings* ss) {
   return ss->treeView ? (ss->treeViewAlwaysByPID ? PID : ss->treeSortKey) : ss->sortKey;
}
int ScreenSettings_getActiveDirection(const ScreenSettings* ss) {
   return ss->treeView ? ss->treeDirection : ss->direction;
}

void ScreenSettings_setSortKey(ScreenSettings* ss, int sortKey) {
   if (ss->treeViewAlwaysByPID || !ss->treeView) {
      ss->sortKey = sortKey;
      ss->direction = Process_fields[sortKey].defaultSortDesc ? -1 : 1;
      ss->treeView = false;
   } else {
      ss->treeSortKey = sortKey;
      ss->treeDirection = Process_fields[sortKey].defaultSortDesc ? -1 : 1;
   }
}

void ScreenSettings_invertSortOrder(ScreenSettings* ss) {
   int* attr = (ss->treeView && !ss->treeViewAlwaysByPID) ? &ss->treeDirection : &ss->direction;
   *attr = (*attr == 1) ? -1 : 1;
}

void ScreenSettings_readFields(ScreenSettings* ss, const char* line) {
   size_t n;
   char** ids = string_split(line, ' ', &n);
   int* fields = xcalloc(LAST_PROCESSFIELD + 1, sizeof(int));
   unsigned int j = 0;
   for (size_t i = 0; ids[i] && j < LAST_PROCESSFIELD; i++) {
      if (!ids[i][0]) continue;
      int f = 0;
      if (isdigit((unsigned char)ids[i][0])) {
         f = Fields_fromWrittenId(atoi(ids[i]));
      } else {
         f = Fields_fromName(ids[i]);
      }
      if (f) fields[j++] = f;
   }
   fields[j] = 0;
   string_freeArray(ids);
   free(ss->fields);
   ss->fields = fields;
   ss->flags = 0;
   for (unsigned int i = 0; fields[i]; i++) ss->flags |= Process_fields[fields[i]].flags;
}

static ScreenSettings* ScreenSettings_newBlank(const char* name) {
   ScreenSettings* ss = xcalloc(1, sizeof(ScreenSettings));
   ss->heading = xstrdup(name);
   ss->fields = xcalloc(LAST_PROCESSFIELD + 1, sizeof(int));
   ss->direction = 1;
   ss->treeDirection = 1;
   ss->sortKey = PID;
   ss->treeSortKey = PID;
   return ss;
}

ScreenSettings* Settings_newScreen(Settings* this, const char* name, const char* columns) {
   ScreenSettings* ss = ScreenSettings_newBlank(name);
   ScreenSettings_readFields(ss, columns);
   this->screens = xrealloc(this->screens, sizeof(ScreenSettings*) * (this->nScreens + 2));
   this->screens[this->nScreens] = ss;
   this->nScreens++;
   this->screens[this->nScreens] = NULL;
   return ss;
}

void Settings_deleteScreen(Settings* this, unsigned int idx) {
   if (idx >= this->nScreens) return;
   ScreenSettings_delete(this->screens[idx]);
   for (unsigned int i = idx; i < this->nScreens; i++) this->screens[i] = this->screens[i + 1];
   this->nScreens--;
}

ScreenSettings* Settings_defaultScreens(Settings* this) {
   if (this->nScreens) return this->screens[0];
   ScreenSettings* ss = Settings_newScreen(this, "Main", "PID USER PRIORITY NICE M_VIRT M_RESIDENT M_SHARE STATE PERCENT_CPU PERCENT_MEM TIME Command");
   ss->sortKey = PERCENT_CPU; ss->direction = -1; ss->treeSortKey = PID; ss->treeDirection = 1;
   ScreenSettings* io = Settings_newScreen(this, "I/O", "PID USER IO_PRIORITY IO_RATE IO_READ_RATE IO_WRITE_RATE Command");
   io->sortKey = IO_RATE; io->direction = -1; io->treeSortKey = PID; io->treeDirection = 1;
   return ss;
}

/* ---- Meter columns ---- */

static void MeterColumnSettings_clear(MeterColumnSettings* c) {
   string_freeArray(c->names); free(c->modes); c->names = NULL; c->modes = NULL; c->len = 0;
}

static void Settings_defaultMeters(Settings* this, unsigned int initialCpuCount) {
   int sizes[] = { 3, 3 };
   if (initialCpuCount > 4 && initialCpuCount <= 128) { sizes[1]++; }
   /* layout: two_50_50 */
   this->hLayout = HF_TWO_50_50;
   this->hColumns = xcalloc(4, sizeof(MeterColumnSettings));
   for (int i = 0; i < 2; i++) {
      this->hColumns[i].names = xcalloc(sizes[i] + 1, sizeof(char*));
      this->hColumns[i].modes = xcalloc(sizes[i] + 1, sizeof(int));
      this->hColumns[i].len = sizes[i];
   }
   int r = 0;
   if (initialCpuCount > 128) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs8"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs8"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 32) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs8"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs8"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 16) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs4"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs4"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 8) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs2"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs2"); this->hColumns[1].modes[r++] = 1;
   } else if (initialCpuCount > 4) {
      this->hColumns[0].names[0] = xstrdup("LeftCPUs"); this->hColumns[0].modes[0] = 1;
      this->hColumns[1].names[r] = xstrdup("RightCPUs"); this->hColumns[1].modes[r++] = 1;
   } else {
      this->hColumns[0].names[0] = xstrdup("AllCPUs"); this->hColumns[0].modes[0] = 1;
   }
   this->hColumns[0].names[1] = xstrdup("Memory"); this->hColumns[0].modes[1] = 1;
   this->hColumns[0].names[2] = xstrdup("Swap"); this->hColumns[0].modes[2] = 1;
   this->hColumns[1].names[r] = xstrdup("Tasks"); this->hColumns[1].modes[r++] = 2;
   this->hColumns[1].names[r] = xstrdup("LoadAverage"); this->hColumns[1].modes[r++] = 2;
   this->hColumns[1].names[r] = xstrdup("Uptime"); this->hColumns[1].modes[r++] = 2;
}

static void readMeters(Settings* this, const char* line, unsigned int column) {
   if (column >= 4) return;
   MeterColumnSettings* c = &this->hColumns[column];
   string_freeArray(c->names);
   size_t n;
   c->names = string_split(line, ' ', &n);
   /* remove empty */
   size_t j = 0;
   for (size_t i = 0; i < n; i++) { if (c->names[i][0]) c->names[j++] = c->names[i]; else free(c->names[i]); }
   c->names[j] = NULL;
   c->len = j;
}

static void readMeterModes(Settings* this, const char* line, unsigned int column) {
   if (column >= 4) return;
   MeterColumnSettings* c = &this->hColumns[column];
   size_t n;
   char** modes = string_split(line, ' ', &n);
   free(c->modes);
   c->modes = xcalloc(n + 1, sizeof(int));
   size_t j = 0;
   for (size_t i = 0; i < n; i++) { if (modes[i][0]) c->modes[j++] = atoi(modes[i]); }
   string_freeArray(modes);
   /* the number of meters is governed by names */
}

void Settings_setHeaderLayout(Settings* this, HeaderLayout hLayout) {
   unsigned int oldColumns = HeaderLayout_layouts[this->hLayout].columns;
   unsigned int newColumns = HeaderLayout_layouts[hLayout].columns;
   if (newColumns < oldColumns) {
      /* move meters of removed columns into last remaining column */
      MeterColumnSettings* last = &this->hColumns[newColumns - 1];
      for (unsigned int i = newColumns; i < oldColumns; i++) {
         MeterColumnSettings* c = &this->hColumns[i];
         for (size_t k = 0; k < c->len; k++) {
            last->names = xrealloc(last->names, sizeof(char*) * (last->len + 2));
            last->modes = xrealloc(last->modes, sizeof(int) * (last->len + 2));
            last->names[last->len] = c->names[k]; c->names[k] = NULL;
            last->modes[last->len] = c->modes ? c->modes[k] : 1;
            last->len++;
            last->names[last->len] = NULL;
         }
         MeterColumnSettings_clear(c);
      }
   }
   this->hLayout = hLayout;
   this->changed = true;
}

/* ---- Settings ---- */

static void Settings_defaults(Settings* this) {
   this->hideKernelThreads = true;
   this->hideUserlandThreads = false;
   this->hideRunningInContainer = false;
   this->shadowOtherUsers = false;
   this->showThreadNames = false;
   this->showProgramPath = true;
   this->highlightBaseName = false;
   this->highlightDeletedExe = true;
   this->shadowDistPathPrefix = false;
   this->highlightMegabytes = true;
   this->highlightThreads = true;
   this->highlightChanges = false;
   this->highlightDelaySecs = 5;
   this->findCommInCmdline = true;
   this->stripExeFromCmdline = true;
   this->showMergedCommand = false;
   this->headerMargin = true;
   this->screenTabs = true;
   this->detailedCPUTime = false;
   this->countCPUsFromOne = false;
   this->showCPUUsage = true;
   this->showCPUFrequency = false;
   this->showCachedMemory = true;
