}

static bool Settings_read(Settings* this, const char* fileName, unsigned int initialCpuCount) {
   FILE* fd = fopen(fileName, "r");
   if (!fd) return false;
   bool didReadMeters = false;
   bool didReadAny = false;
   bool legacyFields = false;
   int legacySortKey = -1, legacyTreeSortKey = -1, legacyDirection = 0, legacyTreeDirection = 0;
   int legacyTreeView = -1, legacyTreeAlwaysByPid = -1, legacyAllCollapsed = -1;
   char* legacyFieldsLine = NULL;
   ScreenSettings* screen = NULL;
   char line[4096];
   while (fgets(line, sizeof(line), fd)) {
      size_t len = strlen(line);
      while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = 0;
      if (!len || line[0] == '#') continue;
      char* eq = strchr(line, '=');
      if (!eq) continue;
      *eq = 0;
      const char* key = line;
      const char* value = eq + 1;
      didReadAny = true;
      if (strcmp(key, "htop_version") == 0 || strcmp(key, "config_reader_min_version") == 0) {
         continue;
      } else if (strcmp(key, "fields") == 0) {
         free(legacyFieldsLine); legacyFieldsLine = xstrdup(value); legacyFields = true;
      } else if (strcmp(key, "sort_key") == 0) {
         legacySortKey = Fields_fromWrittenId(atoi(value));
      } else if (strcmp(key, "tree_sort_key") == 0) {
         legacyTreeSortKey = Fields_fromWrittenId(atoi(value));
      } else if (strcmp(key, "sort_direction") == 0) {
         legacyDirection = atoi(value);
      } else if (strcmp(key, "tree_sort_direction") == 0) {
         legacyTreeDirection = atoi(value);
      } else if (strcmp(key, "tree_view") == 0) {
         legacyTreeView = atoi(value) != 0;
      } else if (strcmp(key, "tree_view_always_by_pid") == 0) {
         legacyTreeAlwaysByPid = atoi(value) != 0;
      } else if (strcmp(key, "all_branches_collapsed") == 0) {
         legacyAllCollapsed = atoi(value) != 0;
      } else if (strcmp(key, "hide_kernel_threads") == 0) this->hideKernelThreads = atoi(value) != 0;
      else if (strcmp(key, "hide_userland_threads") == 0) this->hideUserlandThreads = atoi(value) != 0;
      else if (strcmp(key, "hide_running_in_container") == 0) this->hideRunningInContainer = atoi(value) != 0;
      else if (strcmp(key, "shadow_other_users") == 0) this->shadowOtherUsers = atoi(value) != 0;
      else if (strcmp(key, "show_thread_names") == 0) this->showThreadNames = atoi(value) != 0;
      else if (strcmp(key, "show_program_path") == 0) this->showProgramPath = atoi(value) != 0;
      else if (strcmp(key, "highlight_base_name") == 0) this->highlightBaseName = atoi(value) != 0;
      else if (strcmp(key, "highlight_deleted_exe") == 0) this->highlightDeletedExe = atoi(value) != 0;
      else if (strcmp(key, "shadow_distribution_path_prefix") == 0) this->shadowDistPathPrefix = atoi(value) != 0;
      else if (strcmp(key, "highlight_megabytes") == 0) this->highlightMegabytes = atoi(value) != 0;
      else if (strcmp(key, "highlight_threads") == 0) this->highlightThreads = atoi(value) != 0;
      else if (strcmp(key, "highlight_changes") == 0) this->highlightChanges = atoi(value) != 0;
      else if (strcmp(key, "highlight_changes_delay_secs") == 0) { this->highlightDelaySecs = CLAMP(atoi(value), 1, 24 * 60 * 60); }
      else if (strcmp(key, "find_comm_in_cmdline") == 0) this->findCommInCmdline = atoi(value) != 0;
      else if (strcmp(key, "strip_exe_from_cmdline") == 0) this->stripExeFromCmdline = atoi(value) != 0;
