      }
      else if (strcmp(key, "show_cpu_usage") == 0) this->showCPUUsage = atoi(value) != 0;
      else if (strcmp(key, "show_cpu_frequency") == 0) this->showCPUFrequency = atoi(value) != 0;
      else if (strcmp(key, "show_cached_memory") == 0) this->showCachedMemory = atoi(value) != 0;
      else if (strcmp(key, "update_process_names") == 0) this->updateProcessNames = atoi(value) != 0;
      else if (strcmp(key, "account_guest_in_cpu_meter") == 0) this->accountGuestInCPUMeter = atoi(value) != 0;
      else if (strcmp(key, "delay") == 0) this->delay = CLAMP(atoi(value), 1, 255);
      else if (strcmp(key, "color_scheme") == 0) { this->colorScheme = atoi(value); if (this->colorScheme < 0 || this->colorScheme >= LAST_COLORSCHEME) this->colorScheme = 0; }
      else if (strcmp(key, "enable_mouse") == 0) this->enableMouse = atoi(value) != 0;
      else if (strcmp(key, "hide_function_bar") == 0) this->hideFunctionBar = CLAMP(atoi(value), 0, 2);
      else if (strcmp(key, "header_layout") == 0) {
         for (int i = 0; i < LAST_HEADER_LAYOUT; i++) if (strcmp(value, HeaderLayout_layouts[i].name) == 0) { this->hLayout = i; break; }
      }
      else if (strcmp(key, "left_meters") == 0) { readMeters(this, value, 0); didReadMeters = true; }
      else if (strcmp(key, "right_meters") == 0) { readMeters(this, value, 1); didReadMeters = true; }
      else if (strcmp(key, "left_meter_modes") == 0) { readMeterModes(this, value, 0); didReadMeters = true; }
      else if (strcmp(key, "right_meter_modes") == 0) { readMeterModes(this, value, 1); didReadMeters = true; }
      else if (string_startsWith(key, "column_meters_")) {
         unsigned int col = atoi(key + strlen("column_meters_"));
         readMeters(this, value, col); didReadMeters = true;
      } else if (string_startsWith(key, "column_meter_modes_")) {
         unsigned int col = atoi(key + strlen("column_meter_modes_"));
         readMeterModes(this, value, col); didReadMeters = true;
      } else if (string_startsWith(key, "screen:")) {
         screen = Settings_newScreen(this, key + strlen("screen:"), value);
      } else if (strcmp(key, ".sort_key") == 0) {
         if (screen) { int f = Fields_fromName(value); if (f) screen->sortKey = f; }
      } else if (strcmp(key, ".tree_sort_key") == 0) {
         if (screen) { int f = Fields_fromName(value); if (f) screen->treeSortKey = f; }
      } else if (strcmp(key, ".sort_direction") == 0) {
         if (screen) screen->direction = atoi(value);
      } else if (strcmp(key, ".tree_sort_direction") == 0) {
         if (screen) screen->treeDirection = atoi(value);
      } else if (strcmp(key, ".tree_view") == 0) {
         if (screen) screen->treeView = atoi(value) != 0;
      } else if (strcmp(key, ".tree_view_always_by_pid") == 0) {
         if (screen) screen->treeViewAlwaysByPID = atoi(value) != 0;
      } else if (strcmp(key, ".all_branches_collapsed") == 0) {
         if (screen) screen->allBranchesCollapsed = atoi(value) != 0;
      } else if (strcmp(key, ".dynamic") == 0) {
         if (screen) { free(screen->dynamic); screen->dynamic = xstrdup(value); }
      }
   }
   fclose(fd);
   if (!didReadMeters) {
      /* keep defaults */
   } else {
      /* fix up modes arrays */
      for (int i = 0; i < 4; i++) {
         MeterColumnSettings* c = &this->hColumns[i];
         if (!c->names) { c->names = xcalloc(1, sizeof(char*)); c->len = 0; }
         int* modes = xcalloc(c->len + 1, sizeof(int));
         for (size_t k = 0; k < c->len; k++) modes[k] = (c->modes && c->modes[k] > 0) ? c->modes[k] : 1;
         free(c->modes); c->modes = modes;
      }
   }
   if (this->nScreens == 0) {
      /* build screens from legacy settings */
      Settings_defaultScreens(this);
      ScreenSettings* ss = this->screens[0];
      if (legacyFields && legacyFieldsLine) ScreenSettings_readFields(ss, legacyFieldsLine);
      if (legacySortKey > 0) ss->sortKey = legacySortKey;
      if (legacyTreeSortKey > 0) ss->treeSortKey = legacyTreeSortKey;
      if (legacyDirection) ss->direction = legacyDirection;
      if (legacyTreeDirection) ss->treeDirection = legacyTreeDirection;
      if (legacyTreeView >= 0) ss->treeView = legacyTreeView;
      if (legacyTreeAlwaysByPid >= 0) ss->treeViewAlwaysByPID = legacyTreeAlwaysByPid;
      if (legacyAllCollapsed >= 0) ss->allBranchesCollapsed = legacyAllCollapsed;
   }
   free(legacyFieldsLine);
   (void)initialCpuCount;
   return didReadAny;
}

static void writeFields(FILE* fd, const int* fields, bool byName, char separator) {
   const char* sep = "";
   for (unsigned int i = 0; fields[i]; i++) {
      if (byName) fprintf(fd, "%s%s", sep, Process_fields[fields[i]].name);
      else fprintf(fd, "%s%d", sep, fields[i] - 1);
      sep = " ";
   }
   fputc(separator, fd);
}

static void writeMeters(const Settings* this, FILE* fd, char separator, unsigned int column) {
   const MeterColumnSettings* c = &this->hColumns[column];
   const char* sep = "";
   for (size_t i = 0; i < c->len; i++) { fprintf(fd, "%s%s", sep, c->names[i]); sep = " "; }
   fputc(separator, fd);
}
static void writeMeterModes(const Settings* this, FILE* fd, char separator, unsigned int column) {
   const MeterColumnSettings* c = &this->hColumns[column];
   const char* sep = "";
   for (size_t i = 0; i < c->len; i++) { fprintf(fd, "%s%d", sep, c->modes[i]); sep = " "; }
   fputc(separator, fd);
}

int Settings_write(const Settings* this, bool onCrash) {
   FILE* fd;
   char separator;
   char* tmpFilename = NULL;
   if (onCrash) {
      fd = stderr;
      separator = ';';
   } else {
      tmpFilename = xasprintf("%s.tmp.XXXXXX", this->filename);
      int fdtmp = mkstemp(tmpFilename);
      if (fdtmp == -1) { free(tmpFilename); return -errno; }
      fd = fdopen(fdtmp, "w");
      if (!fd) { close(fdtmp); unlink(tmpFilename); free(tmpFilename); return -errno; }
      separator = '\n';
   }
#define printSettingInteger(setting_, value_) fprintf(fd, setting_ "=%d%c", (int)(value_), separator)
#define printSettingString(setting_, value_) fprintf(fd, setting_ "=%s%c", value_, separator)
   if (!onCrash) {
      fprintf(fd, "# Beware! This file is rewritten by htop when settings are changed in the interface.\n");
      fprintf(fd, "# The parser is also very primitive, and not human-friendly.\n");
   }
   printSettingString("htop_version", PROGRAM_VERSION);
   printSettingInteger("config_reader_min_version", CONFIG_READER_MIN_VERSION);
   fprintf(fd, "fields=");
   writeFields(fd, this->screens[0]->fields, false, separator);
   printSettingInteger("hide_kernel_threads", this->hideKernelThreads);
   printSettingInteger("hide_userland_threads", this->hideUserlandThreads);
   printSettingInteger("hide_running_in_container", this->hideRunningInContainer);
   printSettingInteger("shadow_other_users", this->shadowOtherUsers);
   printSettingInteger("show_thread_names", this->showThreadNames);
   printSettingInteger("show_program_path", this->showProgramPath);
   printSettingInteger("highlight_base_name", this->highlightBaseName);
   printSettingInteger("highlight_deleted_exe", this->highlightDeletedExe);
   printSettingInteger("shadow_distribution_path_prefix", this->shadowDistPathPrefix);
   printSettingInteger("highlight_megabytes", this->highlightMegabytes);
   printSettingInteger("highlight_threads", this->highlightThreads);
   printSettingInteger("highlight_changes", this->highlightChanges);
   printSettingInteger("highlight_changes_delay_secs", this->highlightDelaySecs);
   printSettingInteger("find_comm_in_cmdline", this->findCommInCmdline);
   printSettingInteger("strip_exe_from_cmdline", this->stripExeFromCmdline);
   printSettingInteger("show_merged_command", this->showMergedCommand);
   printSettingInteger("header_margin", this->headerMargin);
   printSettingInteger("screen_tabs", this->screenTabs);
   printSettingInteger("detailed_cpu_time", this->detailedCPUTime);
   printSettingInteger("cpu_count_from_one", this->countCPUsFromOne);
   printSettingInteger("show_cpu_usage", this->showCPUUsage);
   printSettingInteger("show_cpu_frequency", this->showCPUFrequency);
   printSettingInteger("show_cached_memory", this->showCachedMemory);
   printSettingInteger("update_process_names", this->updateProcessNames);
   printSettingInteger("account_guest_in_cpu_meter", this->accountGuestInCPUMeter);
   printSettingInteger("color_scheme", this->colorScheme);
   printSettingInteger("enable_mouse", this->enableMouse);
   printSettingInteger("delay", this->delay);
   printSettingInteger("hide_function_bar", this->hideFunctionBar);
   printSettingString("header_layout", HeaderLayout_layouts[this->hLayout].name);
   for (unsigned int i = 0; i < (unsigned int)HeaderLayout_layouts[this->hLayout].columns; i++) {
      fprintf(fd, "column_meters_%u=", i);
      writeMeters(this, fd, separator, i);
      fprintf(fd, "column_meter_modes_%u=", i);
      writeMeterModes(this, fd, separator, i);
   }
   /* legacy */
   {
      const ScreenSettings* ss = this->screens[0];
      printSettingInteger("tree_view", ss->treeView);
      printSettingInteger("sort_key", ss->sortKey - 1);
      printSettingInteger("tree_sort_key", ss->treeSortKey - 1);
      printSettingInteger("sort_direction", ss->direction);
      printSettingInteger("tree_sort_direction", ss->treeDirection);
      printSettingInteger("tree_view_always_by_pid", ss->treeViewAlwaysByPID);
      printSettingInteger("all_branches_collapsed", ss->allBranchesCollapsed);
   }
   for (unsigned int i = 0; i < this->nScreens; i++) {
      const ScreenSettings* ss = this->screens[i];
      fprintf(fd, "screen:%s=", ss->heading);
      writeFields(fd, ss->fields, true, separator);
      if (ss->dynamic) printSettingString(".dynamic", ss->dynamic);
      printSettingString(".sort_key", Process_fields[ss->sortKey].name);
      printSettingString(".tree_sort_key", Process_fields[ss->treeSortKey].name);
      printSettingInteger(".tree_view_always_by_pid", ss->treeViewAlwaysByPID);
      printSettingInteger(".tree_view", ss->treeView);
      printSettingInteger(".sort_direction", ss->direction);
      printSettingInteger(".tree_sort_direction", ss->treeDirection);
      printSettingInteger(".all_branches_collapsed", ss->allBranchesCollapsed);
   }
#undef printSettingInteger
#undef printSettingString
   if (onCrash) return 0;
   int r = 0;
   if (ferror(fd)) r = -EIO;
   if (fclose(fd) != 0) r = r ? r : -errno;
   if (r == 0) {
      if (rename(tmpFilename, this->filename) != 0) r = -errno;
   }
   if (r != 0) unlink(tmpFilename);
   free(tmpFilename);
   return r;
}

static char* Settings_configPath(bool* legacy) {
   *legacy = false;
   const char* rcfile = getenv("HTOPRC");
   if (rcfile && rcfile[0]) return xstrdup(rcfile);
   const char* home = getenv("HOME");
   if (!home) { struct passwd* pw = getpwuid(getuid()); home = pw ? pw->pw_dir : NULL; }
   if (!home) home = "";
   const char* xdg = getenv("XDG_CONFIG_HOME");
   char* configDir;
   char* htopDir;
   if (xdg && xdg[0]) {
      configDir = xstrdup(xdg);
      htopDir = xasprintf("%s/htop", xdg);
   } else {
      configDir = xasprintf("%s/.config", home);
      htopDir = xasprintf("%s/.config/htop", home);
   }
   char* legacyFile = xasprintf("%s/.htoprc", home);
   char* newFile = xasprintf("%s/htoprc", htopDir);
   if (access(newFile, R_OK) != 0 && access(legacyFile, R_OK) == 0) {
      /* migrate: prefer legacy if it exists and new doesn't; htop rename legacy to new location */
      *legacy = true;
   }
   mkdir(configDir, 0700);
   mkdir(htopDir, 0700);
   free(configDir); free(htopDir);
   if (*legacy) {
      /* rename legacy into the new location */
      if (rename(legacyFile, newFile) == 0) { *legacy = false; }
      else { free(newFile); return legacyFile; }
   }
   free(legacyFile);
   return newFile;
}

Settings* Settings_new(unsigned int initialCpuCount) {
   Settings* this = xcalloc(1, sizeof(Settings));
   Settings_defaults(this);
   this->screens = xcalloc(1, sizeof(ScreenSettings*));
   this->nScreens = 0;
   Settings_defaultMeters(this, initialCpuCount);
   bool legacy;
   this->filename = Settings_configPath(&legacy);
   this->initialFilename = xstrdup(this->filename);
   bool ok = Settings_read(this, this->filename, initialCpuCount);
   if (!ok) {
      this->changed = true;
      /* try system-wide config */
      const char* systemSettings[] = { "/etc/htoprc", "/usr/local/etc/htoprc", NULL };
      for (int i = 0; systemSettings[i] && !ok; i++) {
         ok = Settings_read(this, systemSettings[i], initialCpuCount);
      }
      if (!ok) {
         Settings_defaultScreens(this);
      }
   }
   if (this->nScreens == 0) Settings_defaultScreens(this);
   this->ssIndex = 0;
   this->ss = this->screens[0];
   return this;
}

void Settings_delete(Settings* this) {
   if (!this) return;
   free(this->filename); free(this->initialFilename);
   for (int i = 0; i < 4; i++) MeterColumnSettings_clear(&this->hColumns[i]);
   free(this->hColumns);
   for (unsigned int i = 0; i < this->nScreens; i++) ScreenSettings_delete(this->screens[i]);
   free(this->screens);
   free(this->filterString);
   free(this);
}

void Settings_setSortKey(Settings* this, int sortKey) {
   ScreenSettings_setSortKey(this->ss, sortKey);
   this->changed = true;
}

void Settings_invertSortOrder(Settings* this) {
   ScreenSettings_invertSortOrder(this->ss);
   this->changed = true;
}
