#include "machine.h"
#include "crt.h"
#include <unistd.h>
#include <dirent.h>
#include <time.h>
#include <math.h>
#include <sys/sysinfo.h>

Machine* Machine_instance = NULL;

static unsigned int countCPUs(void) {
   long n = sysconf(_SC_NPROCESSORS_CONF);
   /* also check /proc/stat for the highest cpu number */
   FILE* f = fopen("/proc/stat", "r");
   unsigned int maxId = 0;
   if (f) {
      char line[512];
      while (fgets(line, sizeof(line), f)) {
         if (strncmp(line, "cpu", 3) == 0 && isdigit((unsigned char)line[3])) {
            unsigned int id = atoi(line + 3);
            if (id + 1 > maxId) maxId = id + 1;
         }
      }
      fclose(f);
   }
   if (n < 1) n = 1;
   if (maxId > (unsigned int)n) return maxId;
   return (unsigned int)n;
}

unsigned int Machine_cpuCount(void) {
   return countCPUs();
}

Machine* Machine_new(Settings* settings) {
   Machine* this = xcalloc(1, sizeof(Machine));
   this->settings = settings;
   this->htopUserId = getuid();
   this->existingCPUs = countCPUs();
   this->activeCPUs = this->existingCPUs;
   this->cpuData = xcalloc(this->existingCPUs + 1, sizeof(CPUData));
   for (unsigned int i = 0; i <= this->existingCPUs; i++) this->cpuData[i].online = true;
   this->pidDigits = 5;
   this->uidDigits = 5;
   this->iterationsRemaining = (unsigned int)-1;
   /* btime */
   FILE* f = fopen("/proc/stat", "r");
   if (f) {
      char line[512];
      while (fgets(line, sizeof(line), f)) {
         if (strncmp(line, "btime ", 6) == 0) { this->btime = strtoull(line + 6, NULL, 10); break; }
      }
      fclose(f);
   }
   Machine_instance = this;
   return this;
}

void Machine_delete(Machine* this) {
   if (!this) return;
   free(this->cpuData);
   free(this);
}

static void scanCPUTime(Machine* this) {
   FILE* f = fopen("/proc/stat", "r");
   if (!f) return;
   char line[1024];
   unsigned int active = 0;
   for (unsigned int i = 1; i <= this->existingCPUs; i++) this->cpuData[i].online = false;
   while (fgets(line, sizeof(line), f)) {
      if (strncmp(line, "cpu", 3) != 0) {
         if (strncmp(line, "procs_running ", 14) == 0) this->runningTasks = atoi(line + 14);
         continue;
      }
      unsigned int cpuid;
      unsigned long long user = 0, nice = 0, system = 0, idle = 0, iowait = 0, irq = 0, softirq = 0, steal = 0, guest = 0, guestnice = 0;
      int idx;
      if (line[3] == ' ') {
         idx = 0;
         sscanf(line + 4, "%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guestnice);
      } else {
         if (sscanf(line + 3, "%u %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu", &cpuid, &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guestnice) < 2) continue;
         if (cpuid + 1 > this->existingCPUs) continue;
         idx = cpuid + 1;
         active++;
      }
      CPUData* c = &this->cpuData[idx];
      c->online = true;
      /* guest time is already included in user/nice */
      unsigned long long usertime = user - guest;
      unsigned long long nicetime = nice - guestnice;
      unsigned long long idlealltime = idle + iowait;
      unsigned long long systemalltime = system + irq + softirq;
      unsigned long long virtalltime = guest + guestnice;
      unsigned long long totaltime = usertime + nicetime + systemalltime + idlealltime + steal + virtalltime;
#define PER(x, y) c->x##Period = (c->x##Time > (y)) ? 0 : ((y) - c->x##Time); c->x##Time = (y)
      c->userPeriod = usertime > c->userTime ? usertime - c->userTime : 0; c->userTime = usertime;
      c->nicePeriod = nicetime > c->niceTime ? nicetime - c->niceTime : 0; c->niceTime = nicetime;
      c->systemPeriod = system > c->systemTime ? system - c->systemTime : 0; c->systemTime = system;
      c->systemAllPeriod = systemalltime > c->systemAllTime ? systemalltime - c->systemAllTime : 0; c->systemAllTime = systemalltime;
      c->idleAllPeriod = idlealltime > c->idleAllTime ? idlealltime - c->idleAllTime : 0; c->idleAllTime = idlealltime;
      c->idlePeriod = idle > c->idleTime ? idle - c->idleTime : 0; c->idleTime = idle;
      c->ioWaitPeriod = iowait > c->ioWaitTime ? iowait - c->ioWaitTime : 0; c->ioWaitTime = iowait;
      c->irqPeriod = irq > c->irqTime ? irq - c->irqTime : 0; c->irqTime = irq;
      c->softIrqPeriod = softirq > c->softIrqTime ? softirq - c->softIrqTime : 0; c->softIrqTime = softirq;
      c->stealPeriod = steal > c->stealTime ? steal - c->stealTime : 0; c->stealTime = steal;
      c->guestPeriod = virtalltime > c->guestTime ? virtalltime - c->guestTime : 0; c->guestTime = virtalltime;
      c->totalPeriod = totaltime > c->totalTime ? totaltime - c->totalTime : 0; c->totalTime = totaltime;
#undef PER
   }
   fclose(f);
   if (active > 0) this->activeCPUs = active;
}

static void scanCPUFrequency(Machine* this) {
   if (!this->settings->showCPUFrequency) return;
   for (unsigned int i = 1; i <= this->existingCPUs; i++) this->cpuData[i].frequency = NAN;
   bool any = false;
   for (unsigned int i = 1; i <= this->existingCPUs; i++) {
      char path[128];
      xsnprintf(path, sizeof(path), "/sys/devices/system/cpu/cpu%u/cpufreq/scaling_cur_freq", i - 1);
      FILE* f = fopen(path, "r");
      if (!f) continue;
      unsigned long long khz;
      if (fscanf(f, "%llu", &khz) == 1) { this->cpuData[i].frequency = khz / 1000.0; any = true; }
      fclose(f);
   }
   if (!any) {
      FILE* f = fopen("/proc/cpuinfo", "r");
      if (f) {
         char line[512]; int cpu = -1;
         while (fgets(line, sizeof(line), f)) {
            if (strncmp(line, "processor", 9) == 0) { char* c = strchr(line, ':'); if (c) cpu = atoi(c + 1); }
            else if (strncmp(line, "cpu MHz", 7) == 0 && cpu >= 0 && (unsigned)cpu < this->existingCPUs) { char* c = strchr(line, ':'); if (c) this->cpuData[cpu + 1].frequency = atof(c + 1); }
         }
         fclose(f);
      }
   }
   double sum = 0; int n = 0;
   for (unsigned int i = 1; i <= this->existingCPUs; i++) if (!isnan(this->cpuData[i].frequency)) { sum += this->cpuData[i].frequency; n++; }
   this->cpuData[0].frequency = n ? sum / n : NAN;
}

static void scanMemory(Machine* this) {
   FILE* f = fopen("/proc/meminfo", "r");
   if (!f) return;
   unsigned long long freeMem = 0, swapFree = 0, sreclaimable = 0, shmem = 0, cached = 0, buffers = 0, available = 0, swapCached = 0, zswap = 0, zswapped = 0;
   unsigned long long hugePagesTotal = 0, hugePagesFree = 0, hugePageSize = 0;
   char line[256];
   while (fgets(line, sizeof(line), f)) {
      unsigned long long v;
      char key[64];
