double Platform_setCPUValues(double* v, unsigned int cpu, int* curItems, const Machine* this) {
   const Settings* settings = this->settings;
   const CPUData* c = &this->cpuData[cpu];
   double total = (double)(c->totalPeriod == 0 ? 1 : c->totalPeriod);
   double percent;
   v[0] = c->nicePeriod / total * 100.0;       /* nice */
   v[1] = c->userPeriod / total * 100.0;       /* normal */
   if (settings->detailedCPUTime) {
      v[2] = c->systemPeriod / total * 100.0;
      v[3] = c->irqPeriod / total * 100.0;
      v[4] = c->softIrqPeriod / total * 100.0;
      v[5] = c->stealPeriod / total * 100.0;
      v[6] = c->guestPeriod / total * 100.0;
      v[7] = c->ioWaitPeriod / total * 100.0;
      *curItems = 8;
      percent = v[0] + v[1] + v[2] + v[3] + v[4];
      if (settings->accountGuestInCPUMeter) percent += v[5] + v[6];
   } else {
      v[2] = c->systemAllPeriod / total * 100.0;
