         if (strncmp(line, "btime ", 6) == 0) { this->btime = strtoull(line + 6, NULL, 10); break; }
      }
      fclose(f);
   }
   Machine_instance = this;
   return this;
}

void Machine_delete(Machine* this) {
   if (!this) return;
   free(this->cpuData);
   free(this);
}

static void scanCPUTime(Machine* this) {
   FILE* f = fopen("/proc/stat", "r");
   if (!f) return;
   char line[1024];
   unsigned int active = 0;
   for (unsigned int i = 1; i <= this->existingCPUs; i++) this->cpuData[i].online = false;
   while (fgets(line, sizeof(line), f)) {
      if (strncmp(line, "cpu", 3) != 0) {
         if (strncmp(line, "procs_running ", 14) == 0) this->runningTasks = atoi(line + 14);
         continue;
      }
      unsigned int cpuid;
      unsigned long long user = 0, nice = 0, system = 0, idle = 0, iowait = 0, irq = 0, softirq = 0, steal = 0, guest = 0, guestnice = 0;
      int idx;
      if (line[3] == ' ') {
         idx = 0;
