{"command":"cd /workspace/src; cat > process.c <<'EOF'
#include "process.h"
#include "crt.h"
#include <math.h>
#include <pwd.h>
#include <time.h>
#include <limits.h>
#include <signal.h>
#include <sys/resource.h>
#include <sched.h>

int Process_autoWidth[LAST_PROCESSFIELD];

/* ---- users cache ---- */
typedef struct UserEntry_ { uid_t uid; char* name; } UserEntry;
static UserEntry* users = NULL;
static int nUsers = 0, capUsers = 0;

const char* UsersTable_getRef(uid_t uid) {
   for (int i = 0; i < nUsers; i++) if (users[i].uid == uid) return users[i].name;
   struct passwd* pw = getpwuid(uid);
   if (nUsers >= capUsers) { capUsers = capUsers ? capUsers * 2 : 16; users = xrealloc(users, capUsers * sizeof(UserEntry)); }
   users[nUsers].uid = uid;
   users[nUsers].name = pw ? xstrdup(pw->pw_name) : NULL;
   return users[nUsers++].name;
}

int Process_pidDigits(void) { return Machine_instance ? Machine_instance->pidDigits : 5; }

bool Process_isThread(const Process* this) { return this->isUserlandThread || this->isKernelThread; }
bool Process_isTomb(const Process* this) { return this->tombStampMs > 0; }
bool Process_isNew(const Process* this) {
   const Machine* host = Machine_instance;
   if (host->monotonicMs < this->seenStampMs) return false;
   return host->monotonicMs - this->seenStampMs <= 1000 * (uint64_t)host->settings->highlightDelaySecs;
}
void Process_toggleTag(Process* this) { this->tag = !this->tag; }

/* ---- formatting helpers ---- */

void Process_printTime(RichString* str, unsigned long long totalHundredths, bool coloring) {
   char buffer[16];
   int len;
   unsigned long long totalSeconds = totalHundredths / 100;
   unsigned long long totalMinutes = totalSeconds / 60;
   unsigned long long totalHours = totalMinutes / 60;
   unsigned int seconds = totalSeconds % 60;
   unsigned int minutes = totalMinutes % 60;
   unsigned int hundredths = totalHundredths - totalSeconds * 100;
   int yearColor = coloring ? CRT_colors[LARGE_NUMBER] : CRT_colors[PROCESS];
   int dayColor = coloring ? CRT_colors[PROCESS_GIGABYTES] : CRT_colors[PROCESS];
   int hourColor = coloring ? CRT_colors[PROCESS_MEGABYTES] : CRT_colors[PROCESS];
   int defColor = CRT_colors[PROCESS];
   if (totalHundredths == 0) {
      RichString_appendAscii(str, coloring ? CRT_colors[PROCESS_SHADOW] : defColor, " 0:00.00 ");
      return;
   }
   if (totalHours < 1) {
      len = xsnprintf(buffer, sizeof(buffer), "%2u:%02u.%02u ", minutes, seconds, hundredths);
      RichString_appendnAscii(str, defColor, buffer, len);
      return;
   }
   if (totalHours < 100) {
      len = xsnprintf(buffer, sizeof(buffer), "%2lluh", totalHours);
      RichString_appendnAscii(str, hourColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02u:%02u ", minutes, seconds);
      RichString_appendnAscii(str, defColor, buffer, len);
      return;
   }
   unsigned long long totalDays = totalHours / 24;
   if (totalDays < 1000) {
      len = xsnprintf(buffer, sizeof(buffer), "%3llud", totalDays);
      RichString_appendnAscii(str, dayColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02lluh%02um ", totalHours % 24, minutes);
      RichString_appendnAscii(str, defColor, buffer, len);
      return;
   }
   unsigned long long years = totalDays / 365;
   len = xsnprintf(buffer, sizeof(buffer), "%4lluy", years);
   RichString_appendnAscii(str, yearColor, buffer, len);
   len = xsnprintf(buffer, sizeof(buffer), "%03llud ", totalDays % 365);
   RichString_appendnAscii(str, defColor, buffer, len);
}

#define ONE_K 1024ULL
#define ONE_M (ONE_K * ONE_K)
#define ONE_G (ONE_M * ONE_K)
#define ONE_T (ONE_G * ONE_K)
#define ONE_DECIMAL_K 1000ULL
#define ONE_DECIMAL_M (ONE_DECIMAL_K * ONE_DECIMAL_K)
#define ONE_DECIMAL_G (ONE_DECIMAL_M * ONE_DECIMAL_K)
#define ONE_DECIMAL_T (ONE_DECIMAL_G * ONE_DECIMAL_K)

static void printNA(RichString* str, int width, bool coloring) {
   char buffer[16];
   xsnprintf(buffer, sizeof(buffer), "%*s ", width, "N/A");
   RichString_appendAscii(str, coloring ? CRT_colors[PROCESS_SHADOW] : CRT_colors[PROCESS], buffer);
}

/* value in bytes, printed in 5 chars + space */
void Process_printBytes(RichString* str, unsigned long long number, bool coloring) {
   char buffer[16];
   int len;
   int largeNumberColor = coloring ? CRT_colors[LARGE_NUMBER] : CRT_colors[PROCESS];
   int processMegabytesColor = coloring ? CRT_colors[PROCESS_MEGABYTES] : CRT_colors[PROCESS];
   int processGigabytesColor = coloring ? CRT_colors[PROCESS_GIGABYTES] : CRT_colors[PROCESS];
   int processColor = CRT_colors[PROCESS];
   if (number == ULLONG_MAX) { printNA(str, 5, coloring); return; }
   if (number < ONE_K * 100) { /* < 100 KiB in bytes: plain */
      if (number < 100000) {
         len = xsnprintf(buffer, sizeof(buffer), "%5llu ", number);
         RichString_appendnAscii(str, processColor, buffer, len);
         return;
      }
   }
   if (number < 100000) {
      len = xsnprintf(buffer, sizeof(buffer), "%5llu ", number);
      RichString_appendnAscii(str, processColor, buffer, len);
   } else if (number < 10000 * ONE_K) {
      len = xsnprintf(buffer, sizeof(buffer), "%4lluK ", number / ONE_K);
      RichString_appendnAscii(str, processColor, buffer, len);
   } else if (number < 10000 * ONE_M) {
      len = xsnprintf(buffer, sizeof(buffer), "%4lluM ", number / ONE_M);
      RichString_appendnAscii(str, processMegabytesColor, buffer, len);
   } else if (number < 10000 * ONE_G) {
      len = xsnprintf(buffer, sizeof(buffer), "%4lluG ", number / ONE_G);
      RichString_appendnAscii(str, processGigabytesColor, buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%4lluT ", number / ONE_T);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   }
}

/* value in KiB, printed in 5 chars + space */
void Process_printKBytes(RichString* str, unsigned long long number, bool coloring) {
   char buffer[16];
   int len;
   int largeNumberColor = coloring ? CRT_colors[LARGE_NUMBER] : CRT_colors[PROCESS];
   int processMegabytesColor = coloring ? CRT_colors[PROCESS_MEGABYTES] : CRT_colors[PROCESS];
   int processGigabytesColor = coloring ? CRT_colors[PROCESS_GIGABYTES] : CRT_colors[PROCESS];
   int processColor = CRT_colors[PROCESS];
   if (number == ULLONG_MAX) { printNA(str, 5, coloring); return; }
   if (number < 100000) {
      len = xsnprintf(buffer, sizeof(buffer), "%5llu ", number);
      if (number >= 1000) {
         RichString_appendnAscii(str, processMegabytesColor, buffer, 2);
         RichString_appendnAscii(str, processColor, buffer + 2, len - 2);
      } else {
         RichString_appendnAscii(str, processColor, buffer, len);
      }
   } else if (number < 10000 * ONE_K) {
      unsigned long long m = number / ONE_K;
      len = xsnprintf(buffer, sizeof(buffer), "%4lluM ", m);
      if (m >= 1000) {
         RichString_appendnAscii(str, processGigabytesColor, buffer, 1);
         RichString_appendnAscii(str, processMegabytesColor, buffer + 1, len - 1);
      } else {
         RichString_appendnAscii(str, processMegabytesColor, buffer, len);
      }
   } else if (number < 100 * ONE_M) {
      unsigned long long tenths = number / (ONE_M / 10);
      len = xsnprintf(buffer, sizeof(buffer), "%2llu.%1lluG ", tenths / 10, tenths % 10);
      RichString_appendnAscii(str, processGigabytesColor, buffer, 2);
      RichString_appendnAscii(str, processMegabytesColor, buffer + 2, 2);
      RichString_appendnAscii(str, processGigabytesColor, buffer + 4, len - 4);
   } else if (number < 10000 * ONE_M) {
      len = xsnprintf(buffer, sizeof(buffer), "%4lluG ", number / ONE_M);
      RichString_appendnAscii(str, processGigabytesColor, buffer, len);
   } else if (number < 100 * ONE_G) {
      unsigned long long tenths = number / (ONE_G / 10);
      len = xsnprintf(buffer, sizeof(buffer), "%2llu.%1lluT ", tenths / 10, tenths % 10);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%4lluT ", number / ONE_G);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   }
}

/* counter, 11 chars + space */
void Process_printCount(RichString* str, unsigned long long number, bool coloring) {
   char buffer[16];
   int len;
   int largeNumberColor = coloring ? CRT_colors[LARGE_NUMBER] : CRT_colors[PROCESS];
   int processMegabytesColor = coloring ? CRT_colors[PROCESS_MEGABYTES] : CRT_colors[PROCESS];
   int processColor = CRT_colors[PROCESS];
   int processShadowColor = coloring ? CRT_colors[PROCESS_SHADOW] : CRT_colors[PROCESS];
   if (number == ULLONG_MAX) { printNA(str, 11, coloring); return; }
   if (number >= 100000ULL * ONE_DECIMAL_T) {
      len = xsnprintf(buffer, sizeof(buffer), "%11lluT ", number / ONE_DECIMAL_T);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   } else if (number >= 100000ULL * ONE_DECIMAL_G) {
      len = xsnprintf(buffer, sizeof(buffer), "%11lluG ", number / ONE_DECIMAL_G);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   } else if (number >= 100000ULL * ONE_DECIMAL_M) {
      len = xsnprintf(buffer, sizeof(buffer), "%11lluM ", number / ONE_DECIMAL_M);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%11llu ", number);
      RichString_appendnAscii(str, largeNumberColor, buffer, 2);
      RichString_appendnAscii(str, processMegabytesColor, buffer + 2, 3);
      RichString_appendnAscii(str, processColor, buffer + 5, 3);
      RichString_appendnAscii(str, processShadowColor, buffer + 8, len - 8);
   }
}

void Process_printPercentage(float val, char* buffer, size_t n, uint8_t width, int* attrColor) {
   if (val >= 0) {
      if (val < 0.05F) *attrColor = CRT_colors[PROCESS_SHADOW];
      else if (val >= 99.9F) *attrColor = CRT_colors[PROCESS_MEGABYTES];
      int precision = 1;
      if (width == 4 && val > 99.9F) precision = 0;
      xsnprintf(buffer, n, "%*.*f ", width, precision, val);
   } else {
      *attrColor = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%*.*s ", width, width, "N/A");
   }
}

void Process_printRate(RichString* str, double rate, bool coloring) {
   char buffer[16];
   int largeNumberColor = CRT_colors[LARGE_NUMBER];
   int processMegabytesColor = CRT_colors[PROCESS_MEGABYTES];
   int processColor = CRT_colors[PROCESS];
   int shadowColor = CRT_colors[PROCESS_SHADOW];
   if (!coloring) { largeNumberColor = processColor; processMegabytesColor = processColor; shadowColor = processColor; }
   if (isnan(rate)) {
      RichString_appendAscii(str, shadowColor, "        N/A ");
   } else if (rate < 0.005) {
      int len = xsnprintf(buffer, sizeof(buffer), "%7.2f B/s ", rate);
      RichString_appendnAscii(str, shadowColor, buffer, len);
   } else if (rate < ONE_K) {
      int len = xsnprintf(buffer, sizeof(buffer), "%7.2f B/s ", rate);
      RichString_appendnAscii(str, processColor, buffer, len);
   } else if (rate < ONE_M) {
      int len = xsnprintf(buffer, sizeof(buffer), "%7.2f K/s ", rate / ONE_K);
      RichString_appendnAscii(str, processColor, buffer, len);
   } else if (rate < ONE_G) {
      int len = xsnprintf(buffer, sizeof(buffer), "%7.2f M/s ", rate / ONE_M);
      RichString_appendnAscii(str, processMegabytesColor, buffer, len);
   } else if (rate < ONE_T) {
      int len = xsnprintf(buffer, sizeof(buffer), "%7.2f G/s ", rate / ONE_G);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   } else {
      int len = xsnprintf(buffer, sizeof(buffer), "%7.2f T/s ", rate / ONE_T);
      RichString_appendnAscii(str, largeNumberColor, buffer, len);
   }
}

static void printLeftAligned(RichString* str, int attr, const char* content, int width) {
   int len = (int)strlen(content);
   if (len > width) len = width;
   RichString_appendnAscii(str, attr, content, len);
   RichString_appendChr(str, attr, ' ', width - len + 1);
}

int Process_fieldWidth(ProcessField field) {
   const ProcessFieldData* fd = &Process_fields[field];
   if (fd->pidColumn) return Process_pidDigits() + 1;
   if (field == ST_UID) return (Machine_instance ? Machine_instance->uidDigits : 5) + 1;
   if (fd->autoWidth) {
      int w = (int)strlen(fd->title);
      if (Process_autoWidth[field] + 1 > w) w = Process_autoWidth[field] + 1;
      return w;
   }
   return (int)strlen(fd->title);
}

const char* Process_fieldTitle(ProcessField field, char* buf, size_t len) {
   const ProcessFieldData* fd = &Process_fields[field];
   if (fd->pidColumn) { xsnprintf(buf, len, "%*s ", Process_pidDigits(), fd->title); return buf; }
   if (field == ST_UID) { xsnprintf(buf, len, "%*s ", Machine_instance ? Machine_instance->uidDigits : 5, fd->title); return buf; }
   if (fd->autoWidth) {
      int w = Process_fieldWidth(field) - 1;
      xsnprintf(buf, len, "%-*.*s ", w, w, fd->title);
      return buf;
   }
   xsnprintf(buf, len, "%s", fd->title);
   return buf;
}

const char* Process_getCommand(const Process* this) {
   return this->cmdline ? this->cmdline : (this->procComm ? this->procComm : "");
}

static const char* basenameOf(const char* s) {
   const char* b = strrchr(s, '/');
   return b ? b + 1 : s;
}

/* ---- command string rendering ---- */

static void writeCommand(const Process* this, RichString* str, int baseAttr) {
   const Settings* settings = Machine_instance->settings;
   int attr = baseAttr;
   int baseAttrBasename = CRT_colors[PROCESS_BASENAME];
   int commAttr = CRT_colors[PROCESS_COMM];
   if (settings->highlightThreads && Process_isThread(this)) {
      attr = CRT_colors[PROCESS_THREAD];
      baseAttrBasename = CRT_colors[PROCESS_THREAD_BASENAME];
      commAttr = CRT_colors[PROCESS_THREAD_COMM];
   }
   if (this->isKernelThread || !this->cmdline || !this->cmdline[0]) {
      /* kernel threads / no cmdline: shown in shadow using comm */
      const char* c = this->procComm ? this->procComm : (this->cmdline ? this->cmdline : "");
      int a = this->isKernelThread ? CRT_colors[PROCESS_SHADOW] : attr;
      if (this->isKernelThread && settings->highlightThreads) a = CRT_colors[PROCESS_THREAD];
      if (this->isKernelThread) { RichString_appendAscii(str, a, c); return; }
      RichString_appendAscii(str, a, c);
      return;
   }
   const char* cmdline = this->cmdline;
   if (!settings->showMergedCommand) {
      int start = 0;
      int bnStart = this->cmdlineBasenameStart;
      int bnEnd = this->cmdlineBasenameEnd;
      if (!settings->showProgramPath && !this->isCmdlineFromComm) start = bnStart;
      if (settings->highlightBaseName && !this->isCmdlineFromComm) {
         if (bnStart > start) RichString_appendnAscii(str, attr, cmdline + start, bnStart - start);
         int bAttr = baseAttrBasename;
         if (settings->highlightDeletedExe) {
            if (this->procExeDeleted) bAttr = CRT_colors[FAILED_READ];
            else if (this->usesDeletedLib) bAttr = CRT_colors[PROCESS_TAG];
         }
         RichString_appendnAscii(str, bAttr, cmdline + bnStart, bnEnd - bnStart);
         RichString_appendAscii(str, attr, cmdline + bnEnd);
      } else {
         RichString_appendAscii(str, attr, cmdline + start);
      }
      return;
   }
   /* merged command */
   const char* exe = this->procExe;
   const char* comm = this->procComm;
   int sepAttr = CRT_colors[FAILED_READ];
   int exeAttr = baseAttrBasename;
   if (settings->highlightDeletedExe) {
      if (this->procExeDeleted) exeAttr = CRT_colors[FAILED_READ];
      else if (this->usesDeletedLib) exeAttr = CRT_colors[PROCESS_TAG];
   }
   bool wroteExe = false;
   if (exe && exe[0]) {
      const char* exeShown = settings->showProgramPath ? exe : exe + this->procExeBasenameOffset;
      if (settings->showProgramPath && this->procExeBasenameOffset > 0) {
         RichString_appendnAscii(str, attr, exe, this->procExeBasenameOffset);
         RichString_appendAscii(str, settings->highlightBaseName ? exeAttr : attr, exe + this->procExeBasenameOffset);
      } else {
         RichString_appendAscii(str, settings->highlightBaseName ? exeAttr : attr, exeShown);
      }
      wroteExe = true;
   }
   /* comm, if not found in cmdline */
   bool commInCmdline = false;
   const char* commPos = NULL;
   if (comm && comm[0] && settings->findCommInCmdline) {
      /* search comm in cmdline basename region */
      commPos = strstr(cmdline, comm);
      if (commPos) commInCmdline = true;
   }
   if (comm && comm[0] && !commInCmdline) {
      bool exeHasComm = exe && strcmp(exe + this->procExeBasenameOffset, comm) == 0;
      if (!exeHasComm) {
         if (wroteExe) RichString_appendAscii(str, sepAttr, "|");
         RichString_appendAscii(str, commAttr, comm);
         wroteExe = true;
      }
   }
   /* cmdline, possibly stripped */
   const char* rest = cmdline;
   if (settings->stripExeFromCmdline && exe && exe[0]) {
      size_t el = strlen(exe);
      if (strncmp(cmdline, exe, el) == 0 && (cmdline[el] == ' ' || cmdline[el] == 0)) {
         rest = cmdline + el;
         while (*rest == ' ') rest++;
      } else {
         const char* bn = exe + this->procExeBasenameOffset;
         size_t bl = strlen(bn);
         if (strncmp(cmdline + this->cmdlineBasenameStart, bn, bl) == 0 && (cmdline[this->cmdlineBasenameStart + bl] == ' ' || cmdline[this->cmdlineBasenameStart + bl] == 0)) {
            rest = cmdline + this->cmdlineBasenameStart + bl;
            while (*rest == ' ') rest++;
         }
      }
   }
   if (rest != cmdline || !wroteExe) {
      if (wroteExe && rest[0]) RichString_appendAscii(str, sepAttr, "|");
      if (!wroteExe) {
         RichString_appendAscii(str, attr, rest);
      } else if (rest[0]) {
         RichString_appendAscii(str, attr, rest);
      }
   } else {
      if (wroteExe) RichString_appendAscii(str, sepAttr, "|");
      /* highlight comm within cmdline */
      if (commInCmdline && commPos) {
         int off = (int)(commPos - cmdline);
         RichString_appendnAscii(str, attr, cmdline, off);
         RichString_appendnAscii(str, commAttr, commPos, strlen(comm));
         RichString_appendAscii(str, attr, commPos + strlen(comm));
      } else {
         RichString_appendAscii(str, attr, cmdline);
      }
   }
}

static const char* schedPolicyName(int policy) {
   switch (policy) {
      case SCHED_OTHER: return "OTHER";
      case SCHED_FIFO: return "FIFO";
      case SCHED_RR: return "RR";
      case SCHED_BATCH: return "BATCH";
      case 4: return "ISO";
      case SCHED_IDLE: return "IDLE";
      case 6: return "DLINE";
      default: return "N/A";
   }
}

static void writeTree(const Process* this, RichString* str) {
   const Settings* settings = Machine_instance->settings;
   if (!settings->ss->treeView || this->tree_depth <= 0) return;
   int attr = CRT_colors[PROCESS_TREE];
   int maxIndent = CLAMP(this->tree_depth - 1, 0, 30);
   for (int i = 0; i < maxIndent; i++) {
      if (this->indent & (1U << i)) {
         RichString_appendAscii(str, attr, CRT_treeStr[TREE_STR_VERT]);
         RichString_appendAscii(str, attr, "  ");
      } else {
         RichString_appendAscii(str, attr, "   ");
      }
   }
   bool last = (this->indent & (1U << (this->tree_depth - 1))) == 0;
   RichString_appendAscii(str, attr, CRT_treeStr[last ? TREE_STR_BEND : TREE_STR_RTEE]);
   RichString_appendAscii(str, attr, this->showChildren ? CRT_treeStr[TREE_STR_SHUT] : CRT_treeStr[TREE_STR_OPEN]);
   RichString_appendAscii(str, attr, " ");
}

void Process_writeField(const Process* this, RichString* str, ProcessField field) {
   const Settings* settings = Machine_instance->settings;
   const Machine* host = Machine_instance;
   bool coloring = settings->highlightMegabytes;
   char buffer[256];
   size_t n = sizeof(buffer);
   int attr = CRT_colors[PROCESS];
   int baseattr = CRT_colors[PROCESS];
   if (settings->shadowOtherUsers && this->st_uid != host->htopUserId) { attr = CRT_colors[PROCESS_SHADOW]; baseattr = attr; }
   if (this->tag) { attr = CRT_colors[PROCESS_TAG]; baseattr = attr; }
   if (settings->highlightChanges) {
      if (Process_isTomb(this)) attr = baseattr = CRT_colors[PROCESS_TOMB];
      else if (Process_isNew(this)) attr = baseattr = CRT_colors[PROCESS_NEW];
   }
   switch (field) {
   case PID: xsnprintf(buffer, n, "%*d ", Process_pidDigits(), (int)this->pid); break;
   case PPID: xsnprintf(buffer, n, "%*d ", Process_pidDigits(), (int)this->ppid); break;
   case PGRP: xsnprintf(buffer, n, "%*d ", Process_pidDigits(), (int)this->pgrp); break;
   case SESSION: xsnprintf(buffer, n, "%*d ", Process_pidDigits(), (int)this->session); break;
   case TPGID: xsnprintf(buffer, n, "%*d ", Process_pidDigits(), (int)this->tpgid); break;
   case TGID:
      if (this->tgid == this->pid) attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%*d ", Process_pidDigits(), (int)this->tgid); break;
   case COMM: {
      if (settings->highlightThreads && Process_isThread(this) && !this->tag) attr = CRT_colors[PROCESS_THREAD];
      writeTree(this, str);
      writeCommand(this, str, baseattr);
      return;
   }
   case STATE: {
      xsnprintf(buffer, n, "%c ", this->state);
      switch (this->state) {
         case 'R': attr = CRT_colors[PROCESS_RUN_STATE]; break;
         case 'D': case 'Z': attr = CRT_colors[PROCESS_D_STATE]; break;
         case 'T': case 't': attr = CRT_colors[PROCESS_RUN_STATE]; break;
         case 'S': case 'I': case 'W': case 'X': attr = CRT_colors[PROCESS_SHADOW]; break;
         default: break;
      }
      break;
   }
   case TTY:
      if (!this->tty_name) {
         attr = CRT_colors[PROCESS_SHADOW];
         printLeftAligned(str, attr, "(no tty)", 8);
         return;
      }
      printLeftAligned(str, attr, this->tty_name, 8);
      return;
   case MINFLT: Process_printCount(str, this->minflt, coloring); return;
   case CMINFLT: Process_printCount(str, this->cminflt, coloring); return;
   case MAJFLT: Process_printCount(str, this->majflt, coloring); return;
   case CMAJFLT: Process_printCount(str, this->cmajflt, coloring); return;
   case UTIME: Process_printTime(str, this->utime * 100 / CRT_clockTicks, coloring); return;
   case STIME: Process_printTime(str, this->stime * 100 / CRT_clockTicks, coloring); return;
   case CUTIME: Process_printTime(str, this->cutime * 100 / CRT_clockTicks, coloring); return;
   case CSTIME: Process_printTime(str, this->cstime * 100 / CRT_clockTicks, coloring); return;
   case TIME: Process_printTime(str, this->time * 100 / CRT_clockTicks, coloring); return;
   case ELAPSED: {
      double realtime = host->realtime.tv_sec + host->realtime.tv_usec / 1e6;
      double elapsed = realtime - (double)this->starttime_ctime;
      if (elapsed < 0) elapsed = 0;
      Process_printTime(str, (unsigned long long)(elapsed * 100), coloring);
      return;
   }
   case PRIORITY:
      if (this->priority <= -100) xsnprintf(buffer, n, " RT ");
      else xsnprintf(buffer, n, "%3ld ", this->priority);
      break;
   case NICE:
      xsnprintf(buffer, n, "%3ld ", this->nice);
      attr = this->nice < 0 ? CRT_colors[PROCESS_HIGH_PRIORITY] : this->nice > 0 ? CRT_colors[PROCESS_LOW_PRIORITY] : CRT_colors[PROCESS_SHADOW];
      break;
   case STARTTIME: xsnprintf(buffer, n, "%s ", this->starttime_show); break;
   case PROCESSOR: xsnprintf(buffer, n, "%3d ", settings->countCPUsFromOne ? this->processor + 1 : this->processor); break;
   case M_VIRT: Process_printKBytes(str, this->m_virt, coloring); return;
   case M_RESIDENT: Process_printKBytes(str, this->m_resident, coloring); return;
   case M_SHARE: Process_printKBytes(str, this->m_share, coloring); return;
   case M_TRS: Process_printKBytes(str, this->m_trs, coloring); return;
   case M_DRS: Process_printKBytes(str, this->m_drs, coloring); return;
   case M_LRS: Process_printKBytes(str, this->m_lrs < 0 ? ULLONG_MAX : (unsigned long long)this->m_lrs, coloring); return;
   case M_PRIV: Process_printKBytes(str, this->m_resident > this->m_share ? this->m_resident - this->m_share : 0, coloring); return;
   case M_PSS: Process_printKBytes(str, this->haveSmaps ? this->m_pss : (this->m_pss), coloring); return;
   case M_SWAP: Process_printKBytes(str, this->m_swap, coloring); return;
   case M_PSSWP: Process_printKBytes(str, this->m_psswp, coloring); return;
   case ST_UID: xsnprintf(buffer, n, "%*d ", host->uidDigits, (int)this->st_uid); break;
   case PERCENT_CPU: Process_printPercentage(this->percent_cpu, buffer, n, 5, &attr); break;
   case PERCENT_NORM_CPU: {
      float val = this->percent_cpu / (host->activeCPUs ? host->activeCPUs : 1);
      Process_printPercentage(val, buffer, n, 5, &attr); break;
   }
   case PERCENT_MEM: Process_printPercentage(this->percent_mem, buffer, n, 4, &attr); break;
   case GPU_PERCENT: Process_printPercentage(0.0f, buffer, n, 5, &attr); break;
   case GPU_TIME: xsnprintf(buffer, n, "%7s%s ", "0", "ns"); attr = CRT_colors[PROCESS_SHADOW]; break;
   case USER:
      if (host->htopUserId != this->st_uid) attr = CRT_colors[PROCESS_SHADOW];
      if (this->elevated_priv) attr = CRT_colors[PROCESS_PRIV];
      if (this->user) { printLeftAligned(str, attr, this->user, 10); return; }
      xsnprintf(buffer, n, "%-10d ", (int)this->st_uid);
      break;
   case NLWP:
      if (this->nlwp == 1) attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%4ld ", this->nlwp); break;
   case SCHEDULERPOLICY: xsnprintf(buffer, n, "%-5s ", schedPolicyName(this->scheduler_policy)); break;
   case RCHAR: Process_printBytes(str, this->haveIo ? this->io_rchar : ULLONG_MAX, coloring); return;
   case WCHAR: Process_printBytes(str, this->haveIo ? this->io_wchar : ULLONG_MAX, coloring); return;
   case SYSCR: Process_printCount(str, this->haveIo ? this->io_syscr : ULLONG_MAX, coloring); return;
   case SYSCW: Process_printCount(str, this->haveIo ? this->io_syscw : ULLONG_MAX, coloring); return;
   case RBYTES: Process_printBytes(str, this->haveIo ? this->io_read_bytes : ULLONG_MAX, coloring); return;
   case WBYTES: Process_printBytes(str, this->haveIo ? this->io_write_bytes : ULLONG_MAX, coloring); return;
   case CNCLWB: Process_printBytes(str, this->haveIo ? this->io_cancelled_write_bytes : ULLONG_MAX, coloring); return;
   case IO_READ_RATE: Process_printRate(str, this->haveIo ? this->io_rate_read_bps : NAN, coloring); return;
   case IO_WRITE_RATE: Process_printRate(str, this->haveIo ? this->io_rate_write_bps : NAN, coloring); return;
   case IO_RATE: {
      double r = NAN;
      if (this->haveIo && !isnan(this->io_rate_read_bps) && !isnan(this->io_rate_write_bps)) r = this->io_rate_read_bps + this->io_rate_write_bps;
      Process_printRate(str, r, coloring); return;
   }
   case CGROUP: printLeftAligned(str, attr, this->cgroup ? this->cgroup : "N/A", Process_fieldWidth(CGROUP) - 1); return;
   case CCGROUP: printLeftAligned(str, attr, this->cgroup_short ? this->cgroup_short : (this->cgroup ? this->cgroup : "N/A"), Process_fieldWidth(CCGROUP) - 1); return;
   case CONTAINER: printLeftAligned(str, attr, this->container_short ? this->container_short : "N/A", Process_fieldWidth(CONTAINER) - 1); return;
   case ISCONTAINER: xsnprintf(buffer, n, "%-4s ", this->isRunningInContainer ? "YES" : "NO"); break;
   case OOM: xsnprintf(buffer, n, "%4u ", this->oom); break;
   case IO_PRIORITY: {
      int klass = this->ioPriority >> 13;
      int data = this->ioPriority & 0x1fff;
      if (klass == 1) xsnprintf(buffer, n, "R%1d ", data);
      else if (klass == 2) xsnprintf(buffer, n, "B%1d ", data);
      else if (klass == 3) xsnprintf(buffer, n, "id ");
      else if (klass == 0) xsnprintf(buffer, n, "B%1d ", (int)((this->nice + 20) / 5));
      else xsnprintf(buffer, n, "?? ");
      break;
   }
   case CTXT:
      if (this->ctxt_diff == 0) attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%5lu ", this->ctxt_diff); break;
   case SECATTR: printLeftAligned(str, attr, this->secattr ? this->secattr : "N/A", Process_fieldWidth(SECATTR) - 1); return;
   case PROC_COMM: {
      const char* comm;
      if (this->procComm && (!Process_isThread(this) || settings->showThreadNames)) {
         attr = this->isUserlandThread ? CRT_colors[PROCESS_THREAD_COMM] : CRT_colors[PROCESS_COMM];
         comm = this->procComm;
      } else {
         attr = CRT_colors[PROCESS_SHADOW];
         comm = "N/A";
      }
      printLeftAligned(str, attr, comm, 15); return;
   }
   case PROC_EXE: {
      const char* exe;
      if (this->procExe) {
         exe = this->procExe + this->procExeBasenameOffset;
         if (this->procExeDeleted) attr = CRT_colors[FAILED_READ];
         else if (this->usesDeletedLib) attr = CRT_colors[PROCESS_TAG];
         else attr = Process_isThread(this) ? CRT_colors[PROCESS_THREAD_BASENAME] : CRT_colors[PROCESS_BASENAME];
      } else {
         attr = CRT_colors[PROCESS_SHADOW];
         exe = "N/A";
      }
      printLeftAligned(str, attr, exe, 15); return;
   }
   case CWD: {
      const char* cwd;
      if (!this->procCwd) { attr = CRT_colors[PROCESS_SHADOW]; cwd = "N/A"; }
      else if (string_startsWith(this->procCwd, "/proc/") && strstr(this->procCwd, " (deleted)")) { attr = CRT_colors[PROCESS_SHADOW]; cwd = "main thread terminated"; }
      else cwd = this->procCwd;
      printLeftAligned(str, attr, cwd, 25); return;
   }
   case AUTOGROUP_ID:
      if (this->haveAutogroup) xsnprintf(buffer, n, "%7ld ", this->autogroup_id);
      else { attr = CRT_colors[PROCESS_SHADOW]; xsnprintf(buffer, n, "%7s ", "N/A"); }
      break;
   case AUTOGROUP_NICE:
      if (this->haveAutogroup) {
         xsnprintf(buffer, n, "%3d ", this->autogroup_nice);
         attr = this->autogroup_nice < 0 ? CRT_colors[PROCESS_HIGH_PRIORITY] : this->autogroup_nice > 0 ? CRT_colors[PROCESS_LOW_PRIORITY] : CRT_colors[PROCESS_SHADOW];
      } else { attr = CRT_colors[PROCESS_SHADOW]; xsnprintf(buffer, n, "%3s ", "N/A"); }
      break;
   default:
      xsnprintf(buffer, n, "- ");
      break;
   }
   RichString_appendAscii(str, attr, buffer);
}

void Process_display(const Process* this, RichString* out) {
   const Settings* settings = Machine_instance->settings;
   const int* fields = settings->ss->fields;
   for (int i = 0; fields[i]; i++) Process_writeField(this, out, fields[i]);
   if (settings->shadowOtherUsers && this->st_uid != Machine_instance->htopUserId) RichString_setAttr(out, CRT_colors[PROCESS_SHADOW]);
   if (this->tag) RichString_setAttr(out, CRT_colors[PROCESS_TAG]);
   if (settings->highlightChanges) {
      if (Process_isTomb(this)) RichString_setAttr(out, CRT_colors[PROCESS_TOMB]);
      else if (Process_isNew(this)) RichString_setAttr(out, CRT_colors[PROCESS_NEW]);
   }
}

/* ---- comparison ---- */
#define SPACESHIP_NUMBER(a, b) (((a) > (b)) - ((a) < (b)))
static int cmpStr(const char* a, const char* b) { if (!a) a = ""; if (!b) b = ""; return strcmp(a, b); }

int Process_compareByKey(const Process* p1, const Process* p2, ProcessField key) {
   switch (key) {
   case PID: return SPACESHIP_NUMBER(p1->pid, p2->pid);
   case PPID: return SPACESHIP_NUMBER(p1->ppid, p2->ppid);
   case TPGID: return SPACESHIP_NUMBER(p1->tpgid, p2->tpgid);
   case PGRP: return SPACESHIP_NUMBER(p1->pgrp, p2->pgrp);
   case SESSION: return SPACESHIP_NUMBER(p1->session, p2->session);
   case TGID: return SPACESHIP_NUMBER(p1->tgid, p2->tgid);
   case TTY: {
      int r = SPACESHIP_NUMBER(p1->tty_nr, p2->tty_nr);
      if (r) return r;
      return cmpStr(p1->tty_name, p2->tty_name);
   }
   case COMM: return strcasecmp(Process_getCommand(p1), Process_getCommand(p2));
   case STATE: return SPACESHIP_NUMBER(p1->state, p2->state);
   case MINFLT: return SPACESHIP_NUMBER(p1->minflt, p2->minflt);
   case CMINFLT: return SPACESHIP_NUMBER(p1->cminflt, p2->cminflt);
   case MAJFLT: return SPACESHIP_NUMBER(p1->majflt, p2->majflt);
   case CMAJFLT: return SPACESHIP_NUMBER(p1->cmajflt, p2->cmajflt);
   case UTIME: return SPACESHIP_NUMBER(p1->utime, p2->utime);
   case STIME: return SPACESHIP_NUMBER(p1->stime, p2->stime);
   case CUTIME: return SPACESHIP_NUMBER(p1->cutime, p2->cutime);
   case CSTIME: return SPACESHIP_NUMBER(p1->cstime, p2->cstime);
   case TIME: return SPACESHIP_NUMBER(p1->time, p2->time);
   case ELAPSED: return SPACESHIP_NUMBER(p2->starttime_ctime, p1->starttime_ctime);
   case PRIORITY: return SPACESHIP_NUMBER(p1->priority, p2->priority);
   case NICE: return SPACESHIP_NUMBER(p1->nice, p2->nice);
   case STARTTIME: {
      int r = SPACESHIP_NUMBER(p1->starttime_ctime, p2->starttime_ctime);
      return r ? r : SPACESHIP_NUMBER(p1->pid, p2->pid);
   }
   case PROCESSOR: return SPACESHIP_NUMBER(p1->processor, p2->processor);
   case M_VIRT: return SPACESHIP_NUMBER(p1->m_virt, p2->m_virt);
   case M_RESIDENT: return SPACESHIP_NUMBER(p1->m_resident, p2->m_resident);
   case M_SHARE: return SPACESHIP_NUMBER(p1->m_share, p2->m_share);
   case M_TRS: return SPACESHIP_NUMBER(p1->m_trs, p2->m_trs);
   case M_DRS: return SPACESHIP_NUMBER(p1->m_drs, p2->m_drs);
   case M_LRS: return SPACESHIP_NUMBER(p1->m_lrs, p2->m_lrs);
   case M_PRIV: return SPACESHIP_NUMBER(p1->m_resident - p1->m_share, p2->m_resident - p2->m_share);
   case M_PSS: return SPACESHIP_NUMBER(p1->m_pss, p2->m_pss);
   case M_SWAP: return SPACESHIP_NUMBER(p1->m_swap, p2->m_swap);
   case M_PSSWP: return SPACESHIP_NUMBER(p1->m_psswp, p2->m_psswp);
   case ST_UID: return SPACESHIP_NUMBER(p1->st_uid, p2->st_uid);
   case PERCENT_CPU: case PERCENT_NORM_CPU: return SPACESHIP_NUMBER(p1->percent_cpu, p2->percent_cpu);
   case PERCENT_MEM: return SPACESHIP_NUMBER(p1->m_resident, p2->m_resident);
   case USER: return cmpStr(p1->user, p2->user);
   case NLWP: return SPACESHIP_NUMBER(p1->nlwp, p2->nlwp);
   case SCHEDULERPOLICY: return SPACESHIP_NUMBER(p1->scheduler_policy, p2->scheduler_policy);
   case RCHAR: return SPACESHIP_NUMBER(p1->io_rchar, p2->io_rchar);
   case WCHAR: return SPACESHIP_NUMBER(p1->io_wchar, p2->io_wchar);
   case SYSCR: return SPACESHIP_NUMBER(p1->io_syscr, p2->io_syscr);
   case SYSCW: return SPACESHIP_NUMBER(p1->io_syscw, p2->io_syscw);
   case RBYTES: return SPACESHIP_NUMBER(p1->io_read_bytes, p2->io_read_bytes);
   case WBYTES: return SPACESHIP_NUMBER(p1->io_write_bytes, p2->io_write_bytes);
   case CNCLWB: return SPACESHIP_NUMBER(p1->io_cancelled_write_bytes, p2->io_cancelled_write_bytes);
   case IO_READ_RATE: { double a = isnan(p1->io_rate_read_bps) ? -1 : p1->io_rate_read_bps, b = isnan(p2->io_rate_read_bps) ? -1 : p2->io_rate_read_bps; return SPACESHIP_NUMBER(a, b); }
   case IO_WRITE_RATE: { double a = isnan(p1->io_rate_write_bps) ? -1 : p1->io_rate_write_bps, b = isnan(p2->io_rate_write_bps) ? -1 : p2->io_rate_write_bps; return SPACESHIP_NUMBER(a, b); }
   case IO_RATE: {
      double a = (isnan(p1->io_rate_read_bps) || isnan(p1->io_rate_write_bps)) ? -1 : p1->io_rate_read_bps + p1->io_rate_write_bps;
      double b = (isnan(p2->io_rate_read_bps) || isnan(p2->io_rate_write_bps)) ? -1 : p2->io_rate_read_bps + p2->io_rate_write_bps;
      return SPACESHIP_NUMBER(a, b);
   }
   case CGROUP: return cmpStr(p1->cgroup, p2->cgroup);
   case CCGROUP: return cmpStr(p1->cgroup_short, p2->cgroup_short);
   case CONTAINER: return cmpStr(p1->container_short, p2->container_short);
   case ISCONTAINER: return SPACESHIP_NUMBER(p1->isRunningInContainer, p2->isRunningInContainer);
   case OOM: return SPACESHIP_NUMBER(p1->oom, p2->oom);
   case IO_PRIORITY: return SPACESHIP_NUMBER(p1->ioPriority, p2->ioPriority);
   case CTXT: return SPACESHIP_NUMBER(p1->ctxt_diff, p2->ctxt_diff);
   case SECATTR: return cmpStr(p1->secattr, p2->secattr);
   case PROC_COMM: return cmpStr(p1->procComm, p2->procComm);
   case PROC_EXE: return cmpStr(p1->procExe ? p1->procExe + p1->procExeBasenameOffset : NULL, p2->procExe ? p2->procExe + p2->procExeBasenameOffset : NULL);
   case CWD: return cmpStr(p1->procCwd, p2->procCwd);
   case AUTOGROUP_ID: return SPACESHIP_NUMBER(p1->autogroup_id, p2->autogroup_id);
   case AUTOGROUP_NICE: return SPACESHIP_NUMBER(p1->autogroup_nice, p2->autogroup_nice);
   case GPU_TIME: case GPU_PERCENT: return 0;
   default: return SPACESHIP_NUMBER(p1->pid, p2->pid);
   }
}

int Process_compare(const void* v1, const void* v2) {
   const Process* p1 = *(const Process* const*)v1;
   const Process* p2 = *(const Process* const*)v2;
   const ScreenSettings* ss = Machine_instance->settings->ss;
   ProcessField key = ScreenSettings_getActiveSortKey(ss);
   int result = Process_compareByKey(p1, p2, key);
   if (ScreenSettings_getActiveDirection(ss) == -1) result = -result;
   if (result == 0) result = SPACESHIP_NUMBER(p1->pid, p2->pid);
   return result;
}

/* ---- actions ---- */
bool Process_setPriority(Process* this, int priority) {
   int old_errno = errno;
   errno = 0;
   int err = setpriority(PRIO_PROCESS, this->pid, priority);
   if (err == 0 || errno == 0) {
      errno = 0;
      this->nice = getpriority(PRIO_PROCESS, this->pid);
   }
   bool ok = (err == 0);
   errno = old_errno;
   return ok;
}
bool Process_changePriorityBy(Process* this, int delta) { return Process_setPriority(this, this->nice + delta); }
bool Process_sendSignal(Process* this, int sgn) { return kill(this->pid, sgn) == 0; }
