static ssize_t readfile(const char* path, char* buf, size_t size) {
   int fd = open(path, O_RDONLY);
   if (fd < 0) return -1;
   size_t total = 0;
   while (total < size - 1) {
      ssize_t r = read(fd, buf + total, size - 1 - total);
      if (r < 0) { if (errno == EINTR) continue; close(fd); return -1; }
      if (r == 0) break;
      total += r;
   }
   close(fd);
   buf[total] = 0;
   return (ssize_t)total;
}

static bool readStat(Process* p, const char* dir, char* commOut, size_t commLen) {
   char path[PATH_MAX];
   char buf[4096];
