   if (readfile(path, buf, sizeof(buf)) <= 0) return false;
   char* lp = strchr(buf, '(');
   char* rp = strrchr(buf, ')');
   if (!lp || !rp || rp < lp) return false;
   size_t cl = rp - lp - 1;
   if (cl >= commLen) cl = commLen - 1;
   memcpy(commOut, lp + 1, cl); commOut[cl] = 0;
   char* s = rp + 2;
   p->state = *s; s += 2;
   char* end;
   long long v;
#define NEXT_LL() (v = strtoll(s, &end, 10), s = end + 1, v)
#define NEXT_ULL() (v = (long long)strtoull(s, &end, 10), s = end + 1, (unsigned long long)v)
   p->ppid = (pid_t)NEXT_LL();
   p->pgrp = (pid_t)NEXT_LL();
   p->session = (pid_t)NEXT_LL();
   p->tty_nr = (unsigned int)NEXT_LL();
   p->tpgid = (pid_t)NEXT_LL();
   p->flags = (unsigned long)NEXT_ULL();
   p->minflt = NEXT_ULL();
   p->cminflt = NEXT_ULL();
   p->majflt = NEXT_ULL();
   p->cmajflt = NEXT_ULL();
   p->utime = NEXT_ULL();
   p->stime = NEXT_ULL();
   p->cutime = NEXT_ULL();
   p->cstime = NEXT_ULL();
   p->priority = (long)NEXT_LL();
   p->nice = (long)NEXT_LL();
   p->nlwp = (long)NEXT_LL();
   NEXT_LL(); /* itrealvalue */
   p->starttime_ticks = NEXT_ULL();
   NEXT_ULL(); /* vsize */
   NEXT_ULL(); /* rss */
   /* skip 16 fields: rsslim(25) startcode endcode startstack kstkesp kstkeip signal blocked sigignore sigcatch wchan nswap cnswap exit_signal(38) */
   for (int i = 0; i < 14; i++) { while (*s && *s != ' ') s++; if (*s) s++; }
   p->processor = (int)NEXT_LL();
#undef NEXT_LL
#undef NEXT_ULL
