      p->haveIo = false;
      p->io_rate_read_bps = NAN; p->io_rate_write_bps = NAN;
      return;
   }
   unsigned long long last_read = p->io_read_bytes, last_write = p->io_write_bytes;
   char* line = buf;
   while (line && *line) {
      char* nl = strchr(line, '\n'); if (nl) *nl = 0;
      char* colon = strchr(line, ':');
      if (colon) {
         unsigned long long v = strtoull(colon + 1, NULL, 10);
         *colon = 0;
         if (strcmp(line, "rchar") == 0) p->io_rchar = v;
         else if (strcmp(line, "wchar") == 0) p->io_wchar = v;
         else if (strcmp(line, "syscr") == 0) p->io_syscr = v;
         else if (strcmp(line, "syscw") == 0) p->io_syscw = v;
         else if (strcmp(line, "read_bytes") == 0) p->io_read_bytes = v;
         else if (strcmp(line, "write_bytes") == 0) p->io_write_bytes = v;
         else if (strcmp(line, "cancelled_write_bytes") == 0) p->io_cancelled_write_bytes = v;
      }
      line = nl ? nl + 1 : NULL;
   }
   if (p->haveIo && p->io_last_scan_time_ms > 0 && nowMs > p->io_last_scan_time_ms) {
      double dt = (nowMs - p->io_last_scan_time_ms) / 1000.0;
      p->io_rate_read_bps = (p->io_read_bytes >= last_read ? p->io_read_bytes - last_read : 0) / dt;
      p->io_rate_write_bps = (p->io_write_bytes >= last_write ? p->io_write_bytes - last_write : 0) / dt;
   } else {
      p->io_rate_read_bps = NAN; p->io_rate_write_bps = NAN;
   }
   p->haveIo = true;
   p->io_last_scan_time_ms = nowMs;
}

