static char* shortenCgroup(const char* cgroup) {
   /* apply shortening rules */
   char* out = xmalloc(strlen(cgroup) * 2 + 16);
   size_t o = 0;
   const char* s = cgroup;
   while (*s) {
      if (*s != '/') { out[o++] = *s++; continue; }
      /* component starting at s (including '/') */
      const char* comp = s + 1;
      const char* e = strchr(comp, '/');
      size_t cl = e ? (size_t)(e - comp) : strlen(comp);
      char name[512];
      if (cl >= sizeof(name)) cl = sizeof(name) - 1;
      memcpy(name, comp, cl); name[cl] = 0;
      out[o++] = '/';
      size_t nl = strlen(name);
      const char* nextComp = e ? e + 1 : NULL;
      if (nl > 6 && strcmp(name + nl - 6, ".slice") == 0) {
         name[nl - 6] = 0;
         if (strcmp(name, "system") == 0) { o += sprintf(out + o, "[S]"); }
         else if (strcmp(name, "user") == 0) {
            /* check if next is user-*.slice: then drop [U] */
            if (nextComp && string_startsWith(nextComp, "user-")) {
               const char* ne = strchr(nextComp, '/');
               size_t ncl = ne ? (size_t)(ne - nextComp) : strlen(nextComp);
               if (ncl > 6 && strncmp(nextComp + ncl - 6, ".slice", 6) == 0) { o--; /* drop the slash and [U] */ }
               else o += sprintf(out + o, "[U]");
            } else o += sprintf(out + o, "[U]");
         }
         else if (string_startsWith(name, "user-")) { o += sprintf(out + o, "[U:%s]", name + 5); }
         else if (strcmp(name, "machine") == 0) { o += sprintf(out + o, "[M]"); }
         else { o += sprintf(out + o, "[%s]", name); }
      } else if (nl > 6 && strcmp(name + nl - 6, ".scope") == 0) {
         name[nl - 6] = 0;
         if (string_startsWith(name, "machine-")) { o += sprintf(out + o, "[SNC:%s]", name + 8); }
         else if (string_startsWith(name, "docker-")) { o += sprintf(out + o, "[docker:%.12s]", name + 7); }
         else { o += sprintf(out + o, "!%s", name); }
      } else if (nl > 8 && strcmp(name + nl - 8, ".service") == 0) {
         name[nl - 8] = 0;
         o += sprintf(out + o, "%s", name);
      } else if (string_startsWith(name, "lxc.monitor.")) {
         o += sprintf(out + o, "[LXC:%s]", name + 12);
      } else if (string_startsWith(name, "lxc.payload.")) {
         o += sprintf(out + o, "[lxc:%s]", name + 12);
      } else {
         o += sprintf(out + o, "%s", name);
      }
      s = comp + cl;
   }
   out[o] = 0;
   return out;
}

static char* containerFromCgroup(const char* cgroup) {
   /* heuristics: docker-<id>.scope, lxc.payload.<name>, machine-<name>.scope, /docker/<id> */
   const char* p;
   if ((p = strstr(cgroup, "docker-")) != NULL) { return xstrndup(p + 7, 12); }
   if ((p = strstr(cgroup, "/docker/")) != NULL) { return xstrndup(p + 8, 12); }
   if ((p = strstr(cgroup, "lxc.payload.")) != NULL) { const char* e = strchr(p + 12, '/'); return xstrndup(p + 12, e ? (size_t)(e - p - 12) : strlen(p + 12)); }
   if ((p = strstr(cgroup, "machine-")) != NULL) { const char* e = strstr(p + 8, ".scope"); return xstrndup(p + 8, e ? (size_t)(e - p - 8) : strlen(p + 8)); }
