#include "process.h"
#include "crt.h"
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <limits.h>
#include <sched.h>
#include <sys/stat.h>
#include <sys/syscall.h>

#define PF_KTHREAD 0x00200000

/* ---- simple pid hash ---- */
#define HASH_SIZE 4099
typedef struct HashNode_ { pid_t pid; Process* p; struct HashNode_* next; } HashNode;
typedef struct PidHash_ { HashNode* buckets[HASH_SIZE]; } PidHash;

static Process* hash_get(PidHash* h, pid_t pid) {
   for (HashNode* n = h->buckets[(unsigned)pid % HASH_SIZE]; n; n = n->next) if (n->pid == pid) return n->p;
   return NULL;
}
static void hash_put(PidHash* h, pid_t pid, Process* p) {
   HashNode* n = xmalloc(sizeof(HashNode)); n->pid = pid; n->p = p;
   unsigned b = (unsigned)pid % HASH_SIZE; n->next = h->buckets[b]; h->buckets[b] = n;
}
static void hash_remove(PidHash* h, pid_t pid) {
   HashNode** pp = &h->buckets[(unsigned)pid % HASH_SIZE];
   while (*pp) { if ((*pp)->pid == pid) { HashNode* d = *pp; *pp = d->next; free(d); return; } pp = &(*pp)->next; }
}
static void hash_clear(PidHash* h) {
   for (int i = 0; i < HASH_SIZE; i++) { HashNode* n = h->buckets[i]; while (n) { HashNode* d = n; n = n->next; free(d); } h->buckets[i] = NULL; }
}

static void Process_free(void* p) {
   Process* this = p;
   free(this->tty_name); free(this->cmdline); free(this->procComm); free(this->procExe); free(this->procCwd);
   free(this->cgroup); free(this->cgroup_short); free(this->container_short); free(this->secattr); free(this->mergedCommand);
   free(this);
}

ProcessTable* ProcessTable_new(Machine* host, Settings* settings, int* pidMatchList, uid_t userId) {
   ProcessTable* this = xcalloc(1, sizeof(ProcessTable));
   this->host = host;
   this->settings = settings;
   this->processes = Vector_new(Process_free);
   this->displayList = Vector_new(NULL);
   this->pidTable = xcalloc(1, sizeof(PidHash));
   this->pidMatchList = pidMatchList;
   this->userId = userId;
   this->needsSort = true;
   this->firstScan = true;
   return this;
}

void ProcessTable_delete(ProcessTable* this) {
   if (!this) return;
   hash_clear(this->pidTable); free(this->pidTable);
   Vector_delete(this->displayList);
   Vector_delete(this->processes);
   free(this);
}

void ProcessTable_setPidMatchList(ProcessTable* this, int* list) { this->pidMatchList = list; }

Process* ProcessTable_findProcess(ProcessTable* this, pid_t pid) { return hash_get(this->pidTable, pid); }

/* ---- /proc reading helpers ---- */

static ssize_t readfile(const char* path, char* buf, size_t size) {
   int fd = open(path, O_RDONLY);
   if (fd < 0) return -1;
   size_t total = 0;
   while (total < size - 1) {
      ssize_t r = read(fd, buf + total, size - 1 - total);
      if (r < 0) { if (errno == EINTR) continue; close(fd); return -1; }
      if (r == 0) break;
      total += r;
   }
   close(fd);
   buf[total] = 0;
   return (ssize_t)total;
}

static bool readStat(Process* p, const char* dir, char* commOut, size_t commLen) {
   char path[PATH_MAX];
   char buf[4096];
   xsnprintf(path, sizeof(path), "%s/stat", dir);
   if (readfile(path, buf, sizeof(buf)) <= 0) return false;
   char* lp = strchr(buf, '(');
   char* rp = strrchr(buf, ')');
   if (!lp || !rp || rp < lp) return false;
   size_t cl = rp - lp - 1;
   if (cl >= commLen) cl = commLen - 1;
   memcpy(commOut, lp + 1, cl); commOut[cl] = 0;
   char* s = rp + 2;
   p->state = *s; s += 2;
   char* end;
   long long v;
#define NEXT_LL() (v = strtoll(s, &end, 10), s = end + 1, v)
#define NEXT_ULL() (v = (long long)strtoull(s, &end, 10), s = end + 1, (unsigned long long)v)
   p->ppid = (pid_t)NEXT_LL();
   p->pgrp = (pid_t)NEXT_LL();
   p->session = (pid_t)NEXT_LL();
   p->tty_nr = (unsigned int)NEXT_LL();
   p->tpgid = (pid_t)NEXT_LL();
   p->flags = (unsigned long)NEXT_ULL();
   p->minflt = NEXT_ULL();
   p->cminflt = NEXT_ULL();
   p->majflt = NEXT_ULL();
   p->cmajflt = NEXT_ULL();
   p->utime = NEXT_ULL();
   p->stime = NEXT_ULL();
   p->cutime = NEXT_ULL();
   p->cstime = NEXT_ULL();
   p->priority = (long)NEXT_LL();
   p->nice = (long)NEXT_LL();
   p->nlwp = (long)NEXT_LL();
   NEXT_LL(); /* itrealvalue */
   p->starttime_ticks = NEXT_ULL();
   NEXT_ULL(); /* vsize */
   NEXT_ULL(); /* rss */
   /* skip 16 fields: rsslim(25) startcode endcode startstack kstkesp kstkeip signal blocked sigignore sigcatch wchan nswap cnswap exit_signal(38) */
   for (int i = 0; i < 14; i++) { while (*s && *s != ' ') s++; if (*s) s++; }
   p->processor = (int)NEXT_LL();
#undef NEXT_LL
#undef NEXT_ULL
   p->time = p->utime + p->stime;
   return true;
}

static bool readStatm(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[256];
   xsnprintf(path, sizeof(path), "%s/statm", dir);
   if (readfile(path, buf, sizeof(buf)) <= 0) return false;
   long size = 0, resident = 0, shared = 0, trs = 0, lrs = 0, drs = 0;
   if (sscanf(buf, "%ld %ld %ld %ld %ld %ld", &size, &resident, &shared, &trs, &lrs, &drs) < 6) return false;
   p->m_virt = size * CRT_pageSizeKB;
   p->m_resident = resident * CRT_pageSizeKB;
   p->m_share = shared * CRT_pageSizeKB;
   p->m_trs = trs * CRT_pageSizeKB;
   p->m_drs = drs * CRT_pageSizeKB;
   return true;
}

static void readMaps(Process* p, const char* dir, bool calcSize, bool checkDeleted) {
   char path[PATH_MAX];
   xsnprintf(path, sizeof(path), "%s/maps", dir);
   FILE* f = fopen(path, "r");
   if (!f) { if (calcSize) p->m_lrs = -1; return; }
   unsigned long long total = 0;
   bool deleted = false;
   char line[1024];
   while (fgets(line, sizeof(line), f)) {
      unsigned long long start, end; char perms[8]; unsigned long long offset; unsigned int devmaj, devmin; unsigned long long inode; int pos = 0;
      if (sscanf(line, "%llx-%llx %7s %llx %x:%x %llu %n", &start, &end, perms, &offset, &devmaj, &devmin, &inode, &pos) < 7) continue;
      if (inode == 0) continue;
      if (calcSize) total += (end - start) / 1024;
      if (checkDeleted && !deleted) {
         const char* name = line + pos;
         size_t l = strlen(name);
         while (l && (name[l-1] == '\n')) l--;
         if (l >= 10 && strncmp(name + l - 10, " (deleted)", 10) == 0) {
            /* ignore memfd and such */
            if (strncmp(name, "/memfd:", 7) != 0 && strncmp(name, "/dev/", 5) != 0) deleted = true;
         }
      }
   }
   fclose(f);
   if (calcSize) p->m_lrs = (long)total;
   if (checkDeleted) p->usesDeletedLib = deleted;
}

static void readStatus(Process* p, const char* dir, bool wantCtxt) {
   char path[PATH_MAX]; char buf[8192];
   xsnprintf(path, sizeof(path), "%s/status", dir);
   if (readfile(path, buf, sizeof(buf)) <= 0) return;
   unsigned long vol = 0, nonvol = 0; bool haveCtxt = false;
   char* line = buf;
   while (line && *line) {
      char* nl = strchr(line, '\n');
      if (nl) *nl = 0;
      if (strncmp(line, "Tgid:", 5) == 0) p->tgid = atoi(line + 5);
      else if (strncmp(line, "Uid:", 4) == 0) { /* real uid */ }
      else if (strncmp(line, "voluntary_ctxt_switches:", 24) == 0) { vol = strtoul(line + 24, NULL, 10); haveCtxt = true; }
      else if (strncmp(line, "nonvoluntary_ctxt_switches:", 27) == 0) { nonvol = strtoul(line + 27, NULL, 10); haveCtxt = true; }
      else if (strncmp(line, "CapAmb:", 7) == 0) {
         unsigned long long caps = strtoull(line + 7, NULL, 16);
         if (caps && p->st_uid != 0) p->elevated_priv = true;
      }
      line = nl ? nl + 1 : NULL;
   }
   if (wantCtxt && haveCtxt) {
      unsigned long total = vol + nonvol;
      p->ctxt_diff = total > p->ctxt_total ? total - p->ctxt_total : 0;
      p->ctxt_total = total;
   }
}

static void readIo(Process* p, const char* dir, uint64_t nowMs) {
   char path[PATH_MAX]; char buf[1024];
   xsnprintf(path, sizeof(path), "%s/io", dir);
   if (readfile(path, buf, sizeof(buf)) <= 0) {
      p->haveIo = false;
      p->io_rate_read_bps = NAN; p->io_rate_write_bps = NAN;
      return;
   }
   unsigned long long last_read = p->io_read_bytes, last_write = p->io_write_bytes;
   char* line = buf;
   while (line && *line) {
      char* nl = strchr(line, '\n'); if (nl) *nl = 0;
      char* colon = strchr(line, ':');
      if (colon) {
         unsigned long long v = strtoull(colon + 1, NULL, 10);
         *colon = 0;
         if (strcmp(line, "rchar") == 0) p->io_rchar = v;
         else if (strcmp(line, "wchar") == 0) p->io_wchar = v;
         else if (strcmp(line, "syscr") == 0) p->io_syscr = v;
         else if (strcmp(line, "syscw") == 0) p->io_syscw = v;
         else if (strcmp(line, "read_bytes") == 0) p->io_read_bytes = v;
         else if (strcmp(line, "write_bytes") == 0) p->io_write_bytes = v;
         else if (strcmp(line, "cancelled_write_bytes") == 0) p->io_cancelled_write_bytes = v;
      }
      line = nl ? nl + 1 : NULL;
   }
   if (p->haveIo && p->io_last_scan_time_ms > 0 && nowMs > p->io_last_scan_time_ms) {
      double dt = (nowMs - p->io_last_scan_time_ms) / 1000.0;
      p->io_rate_read_bps = (p->io_read_bytes >= last_read ? p->io_read_bytes - last_read : 0) / dt;
      p->io_rate_write_bps = (p->io_write_bytes >= last_write ? p->io_write_bytes - last_write : 0) / dt;
   } else {
      p->io_rate_read_bps = NAN; p->io_rate_write_bps = NAN;
   }
   p->haveIo = true;
   p->io_last_scan_time_ms = nowMs;
}

static void readSmaps(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[4096];
   xsnprintf(path, sizeof(path), "%s/smaps_rollup", dir);
   if (readfile(path, buf, sizeof(buf)) <= 0) { p->haveSmaps = false; return; }
   p->haveSmaps = true;
   p->m_pss = p->m_swap = p->m_psswp = 0;
   char* line = buf;
   while (line && *line) {
      char* nl = strchr(line, '\n'); if (nl) *nl = 0;
      unsigned long long v;
      if (sscanf(line, "Pss: %llu", &v) == 1) p->m_pss = v;
      else if (sscanf(line, "Swap: %llu", &v) == 1) p->m_swap = v;
      else if (sscanf(line, "SwapPss: %llu", &v) == 1) p->m_psswp = v;
      line = nl ? nl + 1 : NULL;
   }
}

static char* shortenCgroup(const char* cgroup) {
   /* apply shortening rules */
   char* out = xmalloc(strlen(cgroup) * 2 + 16);
   size_t o = 0;
   const char* s = cgroup;
   while (*s) {
      if (*s != '/') { out[o++] = *s++; continue; }
      /* component starting at s (including '/') */
      const char* comp = s + 1;
      const char* e = strchr(comp, '/');
      size_t cl = e ? (size_t)(e - comp) : strlen(comp);
      char name[512];
      if (cl >= sizeof(name)) cl = sizeof(name) - 1;
      memcpy(name, comp, cl); name[cl] = 0;
      out[o++] = '/';
      size_t nl = strlen(name);
      const char* nextComp = e ? e + 1 : NULL;
      if (nl > 6 && strcmp(name + nl - 6, ".slice") == 0) {
         name[nl - 6] = 0;
         if (strcmp(name, "system") == 0) { o += sprintf(out + o, "[S]"); }
         else if (strcmp(name, "user") == 0) {
            /* check if next is user-*.slice: then drop [U] */
            if (nextComp && string_startsWith(nextComp, "user-")) {
               const char* ne = strchr(nextComp, '/');
               size_t ncl = ne ? (size_t)(ne - nextComp) : strlen(nextComp);
               if (ncl > 6 && strncmp(nextComp + ncl - 6, ".slice", 6) == 0) { o--; /* drop the slash and [U] */ }
               else o += sprintf(out + o, "[U]");
            } else o += sprintf(out + o, "[U]");
         }
         else if (string_startsWith(name, "user-")) { o += sprintf(out + o, "[U:%s]", name + 5); }
         else if (strcmp(name, "machine") == 0) { o += sprintf(out + o, "[M]"); }
         else { o += sprintf(out + o, "[%s]", name); }
      } else if (nl > 6 && strcmp(name + nl - 6, ".scope") == 0) {
         name[nl - 6] = 0;
         if (string_startsWith(name, "machine-")) { o += sprintf(out + o, "[SNC:%s]", name + 8); }
         else if (string_startsWith(name, "docker-")) { o += sprintf(out + o, "[docker:%.12s]", name + 7); }
         else { o += sprintf(out + o, "!%s", name); }
      } else if (nl > 8 && strcmp(name + nl - 8, ".service") == 0) {
         name[nl - 8] = 0;
         o += sprintf(out + o, "%s", name);
      } else if (string_startsWith(name, "lxc.monitor.")) {
         o += sprintf(out + o, "[LXC:%s]", name + 12);
      } else if (string_startsWith(name, "lxc.payload.")) {
         o += sprintf(out + o, "[lxc:%s]", name + 12);
      } else {
         o += sprintf(out + o, "%s", name);
      }
      s = comp + cl;
   }
   out[o] = 0;
   return out;
}

static char* containerFromCgroup(const char* cgroup) {
   /* heuristics: docker-<id>.scope, lxc.payload.<name>, machine-<name>.scope, /docker/<id> */
   const char* p;
   if ((p = strstr(cgroup, "docker-")) != NULL) { return xstrndup(p + 7, 12); }
   if ((p = strstr(cgroup, "/docker/")) != NULL) { return xstrndup(p + 8, 12); }
   if ((p = strstr(cgroup, "lxc.payload.")) != NULL) { const char* e = strchr(p + 12, '/'); return xstrndup(p + 12, e ? (size_t)(e - p - 12) : strlen(p + 12)); }
   if ((p = strstr(cgroup, "machine-")) != NULL) { const char* e = strstr(p + 8, ".scope"); return xstrndup(p + 8, e ? (size_t)(e - p - 8) : strlen(p + 8)); }
   return xstrdup("/");
}

static void readCgroup(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[4096];
   xsnprintf(path, sizeof(path), "%s/cgroup", dir);
   if (readfile(path, buf, sizeof(buf)) <= 0) {
      free(p->cgroup); p->cgroup = NULL; free(p->cgroup_short); p->cgroup_short = NULL; free(p->container_short); p->container_short = NULL;
      return;
   }
   char* result = NULL;
   char* line = buf;
   char* v2 = NULL;
   size_t rl = 0;
   while (line && *line) {
      char* nl = strchr(line, '\n'); if (nl) *nl = 0;
      char* c1 = strchr(line, ':');
      char* c2 = c1 ? strchr(c1 + 1, ':') : NULL;
      if (c2) {
         const char* pathPart = c2 + 1;
         if (c1 + 1 == c2) { v2 = (char*)pathPart; }
         else {
            size_t pl = strlen(pathPart);
            if (!result) { result = xmalloc(pl + 1); memcpy(result, pathPart, pl + 1); rl = pl; }
            else if (!strstr(result, pathPart)) { result = xrealloc(result, rl + pl + 2); result[rl] = ','; memcpy(result + rl + 1, pathPart, pl + 1); rl += pl + 1; }
         }
      }
      line = nl ? nl + 1 : NULL;
   }
   char* cg = v2 ? xstrdup(v2) : (result ? result : xstrdup("/"));
   if (v2 && result) free(result);
   if (p->cgroup && strcmp(p->cgroup, cg) == 0) { free(cg); return; }
   free(p->cgroup); p->cgroup = cg;
   free(p->cgroup_short); p->cgroup_short = shortenCgroup(cg);
   free(p->container_short); p->container_short = containerFromCgroup(cg);
   p->isRunningInContainer = strcmp(p->container_short, "/") != 0;
}

static void readOom(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[64];
   xsnprintf(path, sizeof(path), "%s/oom_score", dir);
   if (readfile(path, buf, sizeof(buf)) > 0) p->oom = (unsigned int)atoi(buf);
}

static void readSecattr(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[1024];
   xsnprintf(path, sizeof(path), "%s/attr/current", dir);
   ssize_t r = readfile(path, buf, sizeof(buf));
   free(p->secattr); p->secattr = NULL;
   if (r <= 0) return;
   while (r > 0 && (buf[r-1] == '\n' || buf[r-1] == 0)) buf[--r] = 0;
   if (r > 0) p->secattr = xstrdup(buf);
}

static void readAutogroup(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[128];
   xsnprintf(path, sizeof(path), "%s/autogroup", dir);
   p->haveAutogroup = false;
   if (readfile(path, buf, sizeof(buf)) <= 0) return;
   long id; int nice;
   if (sscanf(buf, "/autogroup-%ld nice %d", &id, &nice) == 2) { p->autogroup_id = id; p->autogroup_nice = nice; p->haveAutogroup = true; }
}

static char* makeTtyName(unsigned int tty_nr) {
   if (tty_nr == 0) return NULL;
   unsigned int maj = (tty_nr >> 8) & 0xfff;
   unsigned int min = (tty_nr & 0xff) | ((tty_nr >> 12) & 0xfff00);
   char buf[64];
   if (maj >= 136 && maj <= 143) { xsnprintf(buf, sizeof(buf), "pts/%u", min + (maj - 136) * 256); return xstrdup(buf); }
   if (maj == 4) { if (min < 64) xsnprintf(buf, sizeof(buf), "tty%u", min); else xsnprintf(buf, sizeof(buf), "ttyS%u", min - 64); return xstrdup(buf); }
   if (maj == 5 && min == 0) return xstrdup("tty");
   if (maj == 5 && min == 1) return xstrdup("console");
   if (maj == 3) { xsnprintf(buf, sizeof(buf), "ttyp%u", min); return xstrdup(buf); }
   /* try searching /dev */
   DIR* d = opendir("/dev");
   if (d) {
      struct dirent* e;
      while ((e = readdir(d))) {
         if (strncmp(e->d_name, "tty", 3) != 0 && strncmp(e->d_name, "hvc", 3) != 0) continue;
         char path[PATH_MAX]; struct stat st;
         xsnprintf(path, sizeof(path), "/dev/%s", e->d_name);
         if (stat(path, &st) == 0 && S_ISCHR(st.st_mode) && major(st.st_rdev) == maj && minor(st.st_rdev) == min) { closedir(d); return xstrdup(e->d_name); }
      }
      closedir(d);
   }
   xsnprintf(buf, sizeof(buf), "%u:%u", maj, min);
   return xstrdup(buf);
}

static void readCmdline(Process* p, const char* dir, const char* comm) {
   char path[PATH_MAX];
   static char buf[8192];
   xsnprintf(path, sizeof(path), "%s/cmdline", dir);
   ssize_t len = readfile(path, buf, sizeof(buf));
   if (len <= 0) {
      /* kernel thread or zombie: use comm */
      free(p->cmdline);
      p->cmdline = xstrdup(comm);
      p->cmdlineBasenameStart = 0;
      p->cmdlineBasenameEnd = (int)strlen(comm);
      p->isCmdlineFromComm = true;
      return;
   }
   /* trim trailing NULs */
   while (len > 0 && buf[len-1] == 0) len--;
   int tokenEnd = -1, tokenStart = 0;
   int lastChar = 0;
   for (int i = 0; i < len; i++) {
      if (buf[i] == 0) {
         if (tokenEnd < 0) tokenEnd = i;
         buf[i] = ' ';
      } else if ((unsigned char)buf[i] < 32 || buf[i] == 127) {
         buf[i] = '?';
      }
      if (buf[i] != ' ') lastChar = i;
   }
   if (tokenEnd < 0) {
      /* no NUL: single string; basename ends at first space */
      char* sp = memchr(buf, ' ', len);
      tokenEnd = sp ? (int)(sp - buf) : (int)len;
   }
   buf[len] = 0;
   (void)lastChar;
   /* basename start: last '/' before tokenEnd */
   int bs = 0;
   for (int i = tokenEnd - 1; i >= tokenStart; i--) { if (buf[i] == '/') { bs = i + 1; break; } }
   if (bs >= tokenEnd) bs = tokenStart;
   if (!p->cmdline || strcmp(p->cmdline, buf) != 0) {
      free(p->cmdline);
      p->cmdline = xstrdup(buf);
   }
   p->cmdlineBasenameStart = bs;
   p->cmdlineBasenameEnd = tokenEnd;
   p->isCmdlineFromComm = false;
}

static void readComm(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[256];
   xsnprintf(path, sizeof(path), "%s/comm", dir);
   ssize_t r = readfile(path, buf, sizeof(buf));
   if (r <= 0) { return; }
   while (r > 0 && (buf[r-1] == '\n' || buf[r-1] == 0)) buf[--r] = 0;
   if (!p->procComm || strcmp(p->procComm, buf) != 0) { free(p->procComm); p->procComm = xstrdup(buf); }
}

static void readExe(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[PATH_MAX];
   xsnprintf(path, sizeof(path), "%s/exe", dir);
   ssize_t r = readlink(path, buf, sizeof(buf) - 1);
   if (r < 0) {
      if (p->procExe) {
         /* keep previous value, e.g. process became zombie */
         if (errno == ENOENT) { free(p->procExe); p->procExe = NULL; }
      }
      return;
   }
   buf[r] = 0;
   bool deleted = false;
   size_t l = r;
   if (l > 10 && strcmp(buf + l - 10, " (deleted)") == 0) { buf[l - 10] = 0; deleted = true; }
   if (!p->procExe || strcmp(p->procExe, buf) != 0) {
      free(p->procExe); p->procExe = xstrdup(buf);
      const char* bn = strrchr(buf, '/');
      p->procExeBasenameOffset = bn ? (int)(bn - buf) + 1 : 0;
   }
   p->procExeDeleted = deleted;
}

static void readCwd(Process* p, const char* dir) {
   char path[PATH_MAX]; char buf[PATH_MAX];
   xsnprintf(path, sizeof(path), "%s/cwd", dir);
   ssize_t r = readlink(path, buf, sizeof(buf) - 1);
   free(p->procCwd); p->procCwd = NULL;
   if (r < 0) return;
   buf[r] = 0;
   p->procCwd = xstrdup(buf);
}

static void fillStarttime(Process* p, const Machine* host) {
   time_t now = host->realtime.tv_sec;
   struct tm nowTm; localtime_r(&now, &nowTm);
   struct tm st; localtime_r(&p->starttime_ctime, &st);
   if (st.tm_year != nowTm.tm_year) strftime(p->starttime_show, sizeof(p->starttime_show), " %Y ", &st);
   else if (st.tm_yday != nowTm.tm_yday) strftime(p->starttime_show, sizeof(p->starttime_show), "%b%d ", &st);
   else strftime(p->starttime_show, sizeof(p->starttime_show), "%H:%M ", &st);
   /* strip trailing space: the field adds it */
   size_t l = strlen(p->starttime_show);
   if (l && p->starttime_show[l-1] == ' ') p->starttime_show[l-1] = 0;
}

static bool processEntry(ProcessTable* this, pid_t pid, const char* dir, Process* mainProcess, double period, uid_t dirUid) {
   Machine* host = this->host;
   const Settings* settings = this->settings;
   uint32_t flags = settings->ss->flags;
   bool preExisting = true;
   Process* p = hash_get(this->pidTable, pid);
   if (!p) {
      preExisting = false;
      p = xcalloc(1, sizeof(Process));
      p->pid = pid;
      p->showChildren = true;
      p->show = true;
      p->io_rate_read_bps = NAN; p->io_rate_write_bps = NAN;
      p->seenStampMs = host->monotonicMs;
      p->tgid = mainProcess ? mainProcess->pid : pid;
   }
   p->tgid = mainProcess ? mainProcess->pid : pid;
   p->isUserlandThread = (mainProcess != NULL);
   char comm[64];
   unsigned long long lasttimes = p->time;
   if (!readStat(p, dir, comm, sizeof(comm))) {
      if (!preExisting) Process_free(p);
      return false;
   }
   p->isKernelThread = (p->flags & PF_KTHREAD) != 0;
   if (!p->isUserlandThread && p->isKernelThread) p->isUserlandThread = false;
   p->st_uid = dirUid;
   p->user = UsersTable_getRef(p->st_uid);
   if (!preExisting) {
      p->starttime_ctime = (time_t)(host->btime + p->starttime_ticks / CRT_clockTicks);
      fillStarttime(p, host);
      p->lasttimes = p->time;
      p->percent_cpu = 0;
   } else {
      p->lasttimes = lasttimes;
      double pc = period < 1e-9 ? 0 : (double)(p->time - lasttimes) / period * 100.0;
      if (p->time < lasttimes) pc = 0;
      p->percent_cpu = (float)CLAMP(pc, 0.0, host->activeCPUs * 100.0);
      if (isnan(p->percent_cpu)) p->percent_cpu = 0;
   }
   if (p->state == 'Z' && !p->isUserlandThread) {
      p->m_virt = p->m_resident = p->m_share = p->m_trs = p->m_drs = 0;
   } else {
      readStatm(p, dir);
   }
   p->percent_mem = host->totalMem ? (float)p->m_resident / (float)host->totalMem * 100.0f : 0;
   if ((flags & PROCESS_FLAG_LRS) || (settings->highlightDeletedExe && !p->isKernelThread)) {
      bool calc = (flags & PROCESS_FLAG_LRS) != 0;
      bool chk = settings->highlightDeletedExe && !p->isKernelThread && p->state != 'Z';
      if (p->state == 'Z') { p->m_lrs = -1; }
      else if (calc || (chk && (!preExisting || host->iterationsRemaining % 1 == 0))) readMaps(p, dir, calc, chk);
   }
   readStatus(p, dir, (flags & PROCESS_FLAG_CTXT) != 0);
   if (flags & PROCESS_FLAG_IO) readIo(p, dir, host->realtimeMs);
   if (flags & PROCESS_FLAG_SMAPS) readSmaps(p, dir);
   if (flags & PROCESS_FLAG_CGROUP) readCgroup(p, dir);
   else if (!preExisting) readCgroup(p, dir);
   if (flags & PROCESS_FLAG_OOM) readOom(p, dir);
   if (flags & PROCESS_FLAG_IOPRIO) { int r = syscall(SYS_ioprio_get, 1, pid); p->ioPriority = r < 0 ? -1 : r; }
   if (flags & PROCESS_FLAG_SECATTR) readSecattr(p, dir);
   if (flags & PROCESS_FLAG_AUTOGROUP) readAutogroup(p, dir);
   if (flags & PROCESS_FLAG_SCHED) { int r = sched_getscheduler(pid); p->scheduler_policy = r < 0 ? -1 : (r & ~0x40000000); }
   if (flags & PROCESS_FLAG_TTY) {
      if (!p->tty_name || !preExisting) { free(p->tty_name); p->tty_name = makeTtyName(p->tty_nr); }
   } else if (!preExisting) { p->tty_name = makeTtyName(p->tty_nr); }
   if (flags & PROCESS_FLAG_CWD) readCwd(p, dir);
   /* command related */
   bool rereadName = !preExisting || settings->updateProcessNames || (p->procComm && strcmp(p->procComm, comm) != 0 && !p->isUserlandThread) || !p->cmdline;
   if (!preExisting || rereadName || settings->updateProcessNames) {
      readComm(p, dir);
      if (!p->procComm) p->procComm = xstrdup(comm);
      readExe(p, dir);
      readCmdline(p, dir, comm);
   } else if (p->state == 'Z' && !p->isCmdlineFromComm) {
      /* zombie: cmdline became empty */
      readCmdline(p, dir, comm);
   }
   if (p->isKernelThread) { /* kernel threads have no cmdline */ }
   /* counters */
   host->totalTasks++;
   if (p->state == 'R') { /* counted via /proc/stat */ }
   if (p->isKernelThread) host->kernelThreads++;
   else if (p->isUserlandThread) host->userlandThreads++;
   /* filtering by settings */
   p->show = !((settings->hideKernelThreads && p->isKernelThread) || (settings->hideUserlandThreads && p->isUserlandThread) || (settings->hideRunningInContainer && p->isRunningInContainer));
   p->updated = true;
   p->tombStampMs = 0;
   if (!preExisting) {
      Vector_add(this->processes, p);
      hash_put(this->pidTable, pid, p);
   }
   if (pid > host->maxPid) host->maxPid = pid;
   if ((int)p->st_uid > 0) {
      int d = 1; unsigned int u = p->st_uid; while (u >= 10) { u /= 10; d++; }
      if (d > host->uidDigits) host->uidDigits = d;
   }
   return true;
}

static void scanDir(ProcessTable* this, const char* dirname, Process* mainProcess, double period) {
   DIR* dir = opendir(dirname);
   if (!dir) return;
   struct dirent* entry;
   while ((entry = readdir(dir))) {
      const char* name = entry->d_name;
      if (name[0] < '0' || name[0] > '9') continue;
      char* end;
      long pidl = strtol(name, &end, 10);
      if (*end || pidl <= 0) continue;
      pid_t pid = (pid_t)pidl;
      if (mainProcess && pid == mainProcess->pid) continue;
      char subdir[PATH_MAX];
      xsnprintf(subdir, sizeof(subdir), "%s/%s", dirname, name);
      struct stat st;
      if (stat(subdir, &st) != 0) continue;
      if (!processEntry(this, pid, subdir, mainProcess, period, st.st_uid)) continue;
      if (!mainProcess) {
         Process* p = hash_get(this->pidTable, pid);
         if (p && p->nlwp > 1 && !p->isKernelThread) {
            char taskdir[PATH_MAX];
            xsnprintf(taskdir, sizeof(taskdir), "%s/task", subdir);
            scanDir(this, taskdir, p, period);
         }
      }
   }
   closedir(dir);
}

void ProcessTable_scan(ProcessTable* this, bool pauseUpdate) {
   Machine* host = this->host;
   const Settings* settings = this->settings;
   if (pauseUpdate) return;
   for (int i = 0; i < Vector_size(this->processes); i++) {
      Process* p = Vector_get(this->processes, i);
      p->updated = false;
      p->wasShown = p->show;
   }
   host->totalTasks = 0; host->userlandThreads = 0; host->kernelThreads = 0;
   double period = (double)host->cpuData[0].totalPeriod / (host->activeCPUs ? host->activeCPUs : 1);
   if (this->firstScan) period = 0;
   scanDir(this, "/proc", NULL, period);
   /* remove dead processes */
   for (int i = Vector_size(this->processes) - 1; i >= 0; i--) {
      Process* p = Vector_get(this->processes, i);
      if (p->updated) continue;
      if (settings->highlightChanges) {
         if (p->tombStampMs == 0) p->tombStampMs = host->monotonicMs;
         if (host->monotonicMs - p->tombStampMs <= 1000 * (uint64_t)settings->highlightDelaySecs) continue;
      }
      hash_remove(this->pidTable, p->pid);
      Vector_remove(this->processes, i);
      Process_free(p);
   }
   /* pid digits */
   int d = 1; int m = host->maxPid; while (m >= 10) { m /= 10; d++; }
   host->pidDigits = MAXIMUM(5, MINIMUM(d, 7));
   if (host->uidDigits < 5) host->uidDigits = 5;
   /* auto widths */
   for (int f = 0; f < LAST_PROCESSFIELD; f++) Process_autoWidth[f] = 0;
   uint32_t flags = settings->ss->flags;
   if (flags & (PROCESS_FLAG_CGROUP | PROCESS_FLAG_SECATTR)) {
      for (int i = 0; i < Vector_size(this->processes); i++) {
         Process* p = Vector_get(this->processes, i);
         if (p->cgroup) { int l = strlen(p->cgroup); if (l > Process_autoWidth[CGROUP]) Process_autoWidth[CGROUP] = l; }
         if (p->cgroup_short) { int l = strlen(p->cgroup_short); if (l > Process_autoWidth[CCGROUP]) Process_autoWidth[CCGROUP] = l; }
         if (p->container_short) { int l = strlen(p->container_short); if (l > Process_autoWidth[CONTAINER]) Process_autoWidth[CONTAINER] = l; }
         if (p->secattr) { int l = strlen(p->secattr); if (l > Process_autoWidth[SECATTR]) Process_autoWidth[SECATTR] = l; }
      }
   }
   this->firstScan = false;
   this->needsSort = true;
}

/* ---- filtering & tree ---- */

static bool ProcessTable_matchesFilter(const ProcessTable* this, const Process* p) {
   if (this->userId != (uid_t)-1 && p->st_uid != this->userId) return false;
   if (this->pidMatchList) {
      bool found = false;
      for (int i = 0; this->pidMatchList[i] >= 0; i++) if (this->pidMatchList[i] == p->pid) { found = true; break; }
      if (!found) return false;
   }
   if (this->incFilter && this->incFilter[0]) {
      if (!string_containsI(Process_getCommand(p), this->incFilter, true)) return false;
   }
   return true;
}

typedef struct TreeNode_ { Process* p; Vector* children; } TreeNode;

static int cmpProcessPtr(const void* a, const void* b) { return Process_compare(a, b); }

static void buildTreeBranch(ProcessTable* this, Vector* children, int level, unsigned int indent, bool parentShown) {
   int size = Vector_size(children);
   for (int i = 0; i < size; i++) {
      Process* p = Vector_get(children, i);
      bool last = (i == size - 1);
      p->tree_depth = level + 1;
      p->indent = indent | (last ? 0 : (1U << level));
      if (parentShown && p->show && ProcessTable_matchesFilter(this, p)) Vector_add(this->displayList, p);
      /* children */
      Vector* kids = Vector_new(NULL);
      for (int k = 0; k < Vector_size(this->processes); k++) {
         Process* c = Vector_get(this->processes, k);
         pid_t parent = c->isUserlandThread ? c->tgid : c->ppid;
         if (c != p && parent == p->pid) Vector_add(kids, c);
      }
      Vector_sort(kids, cmpProcessPtr);
      buildTreeBranch(this, kids, level + 1, indent | (last ? 0 : (1U << level)), parentShown && p->showChildren);
      Vector_delete(kids);
   }
}

void ProcessTable_updateDisplayList(ProcessTable* this) {
   const Settings* settings = this->settings;
   Vector_prune(this->displayList);
   if (settings->ss->treeView) {
      /* efficient child lookup: sort processes by parent */
      int n = Vector_size(this->processes);
      for (int i = 0; i < n; i++) { Process* p = Vector_get(this->processes, i); p->tree_depth = 0; p->indent = 0; }
      Vector* roots = Vector_new(NULL);
      for (int i = 0; i < n; i++) {
         Process* p = Vector_get(this->processes, i);
         pid_t parent = p->isUserlandThread ? p->tgid : p->ppid;
         if (parent == p->pid || parent <= 0 || !hash_get(this->pidTable, parent)) Vector_add(roots, p);
      }
      Vector_sort(roots, cmpProcessPtr);
      /* a faster build: index children lists */
      int rs = Vector_size(roots);
      for (int i = 0; i < rs; i++) {
         Process* p = Vector_get(roots, i);
         p->tree_depth = 0; p->indent = 0;
         if (p->show && ProcessTable_matchesFilter(this, p)) Vector_add(this->displayList, p);
         Vector* kids = Vector_new(NULL);
         for (int k = 0; k < n; k++) {
            Process* c = Vector_get(this->processes, k);
            pid_t parent = c->isUserlandThread ? c->tgid : c->ppid;
            if (c != p && parent == p->pid) Vector_add(kids, c);
         }
         Vector_sort(kids, cmpProcessPtr);
         buildTreeBranch(this, kids, 0, 0, p->showChildren);
         Vector_delete(kids);
      }
      Vector_delete(roots);
   } else {
      Vector_sort(this->processes, cmpProcessPtr);
      for (int i = 0; i < Vector_size(this->processes); i++) {
         Process* p = Vector_get(this->processes, i);
         p->tree_depth = 0; p->indent = 0;
         if (p->show && ProcessTable_matchesFilter(this, p)) Vector_add(this->displayList, p);
      }
   }
   this->needsSort = false;
}

void ProcessTable_sort(ProcessTable* this) { ProcessTable_updateDisplayList(this); }

void ProcessTable_expandTree(ProcessTable* this) {
   for (int i = 0; i < Vector_size(this->processes); i++) ((Process*)Vector_get(this->processes, i))->showChildren = true;
}

void ProcessTable_collapseAllBranches(ProcessTable* this) {
   for (int i = 0; i < Vector_size(this->processes); i++) {
      Process* p = Vector_get(this->processes, i);
      /* collapse everything except roots */
      pid_t parent = p->isUserlandThread ? p->tgid : p->ppid;
      if (parent != p->pid && parent > 0 && hash_get(this->pidTable, parent)) p->showChildren = false;
      else p->showChildren = true;
   }
}
EOF
echo ok

