   this->type = type;
   this->param = param;
   this->host = host;
   this->curItems = type->maxItems;
   this->curAttributes = NULL;
   this->values = type->maxItems ? xcalloc(type->maxItems + 2, sizeof(double)) : NULL;
   this->total = type->total;
   this->caption = xstrdup(type->caption);
   if (type->init) type->init(this);
   Meter_setMode(this, type->defaultMode);
   return this;
}

void Meter_delete(Meter* this) {
   if (!this) return;
   if (this->type->done) this->type->done(this);
   free(this->drawData.values);
   free(this->caption);
   free(this->values);
   free(this);
}

void Meter_setCaption(Meter* this, const char* caption) { free(this->caption); this->caption = xstrdup(caption); }
const char* Meter_getCaption(const Meter* this) { return this->type->getCaption ? this->type->getCaption(this) : this->caption; }
const char* Meter_getUiName(const Meter* this, char* buf, size_t len) {
   if (this->type->getUiName) return this->type->getUiName(this, buf, len);
   xsnprintf(buf, len, "%s", this->type->uiName);
   return buf;
}

bool Meter_supportsMode(const Meter* this, MeterModeId mode) { return (this->type->supportedModes & (1u << mode)) != 0; }

void Meter_setMode(Meter* this, MeterModeId mode) {
   if (mode <= 0 || mode >= LAST_METERMODE) mode = this->type->defaultMode;
   if (!Meter_supportsMode(this, mode)) mode = this->type->defaultMode;
   this->mode = mode;
   switch (mode) {
      case GRAPH_METERMODE: this->h = GRAPH_HEIGHT; break;
      case LED_METERMODE: this->h = 3; break;
      default: this->h = 1; break;
   }
   if (this->type->updateMode) this->type->updateMode(this, mode);
}

MeterModeId Meter_nextSupportedMode(const Meter* this) {
   MeterModeId m = this->mode;
   for (int i = 0; i < LAST_METERMODE; i++) {
      m = (m % (LAST_METERMODE - 1)) + 1;
      if (Meter_supportsMode(this, m)) return m;
   }
   return this->mode;
}

void Meter_updateValues(Meter* this) {
   if (this->type->updateValues) this->type->updateValues(this);
}

void Meter_displayBuffer(const Meter* this, RichString* out) {
   if (this->type->display) this->type->display(this, out);
   else RichString_writeAscii(out, CRT_colors[this->type->attributes ? this->type->attributes[0] : RESET_COLOR], this->txtBuffer);
}

/* ---- draw modes ---- */

static void BarMeterMode_draw(Meter* this, int x, int y, int w) {
   const char* caption = Meter_getCaption(this);
   attrset(CRT_colors[METER_TEXT]);
   int captionLen = 3;
   mvaddnstr(y, x, caption, captionLen);
   x += captionLen;
   w -= captionLen;
   attrset(CRT_colors[BAR_BORDER]);
   mvaddch(y, x, '[');
   mvaddch(y, x + MAXIMUM(w, 0) - 1, ']');
   attrset(CRT_colors[RESET_COLOR]);
   w -= 2;
   x++;
   if (w < 1) return;
   RichString bar; RichString_begin(&bar);
   RichString_appendChr(&bar, 0, ' ', w);
   RichString_appendAscii(&bar, 0, this->txtBuffer);
   int startPos = RichString_sizeVal(bar) - w;
   if (startPos > w) {
      for (int pos = 2 * w; pos > w; pos--) {
         if (RichString_getCharVal(&bar, pos) == ' ') {
            while (pos > w && RichString_getCharVal(&bar, pos - 1) == ' ') pos--;
            startPos = pos - w;
            break;
         }
      }
      startPos = MINIMUM(startPos, w);
   }
   int blockSizes[16] = {0};
   int items = MINIMUM(this->curItems, 16);
   int offset = 0;
   for (int i = 0; i < items; i++) {
      double value = this->values[i];
      value = CLAMP(value, 0.0, this->total);
      if (value > 0 && this->total > 0) blockSizes[i] = (int)ceil((value / this->total) * w);
      else blockSizes[i] = 0;
      int nextOffset = offset + blockSizes[i];
      nextOffset = CLAMP(nextOffset, 0, w);
      for (int j = offset; j < nextOffset; j++) {
         if (RichString_getCharVal(&bar, startPos + j) == ' ') {
            char c = (CRT_colorScheme == COLORSCHEME_MONOCHROME) ? BarMeterMode_characters[i] : '|';
            bar.chptr[startPos + j] = (chtype)(unsigned char)c;
         }
      }
      offset = nextOffset;
   }
   offset = 0;
   const int* attrs = this->curAttributes ? this->curAttributes : this->type->attributes;
   for (int i = 0; i < items; i++) {
      int attr = attrs ? attrs[i] : RESET_COLOR;
      RichString_setAttrn(&bar, CRT_colors[attr], startPos + offset, blockSizes[i]);
      RichString_printoffnVal(&bar, y, x + offset, startPos + offset, MINIMUM(blockSizes[i], w - offset));
      offset += blockSizes[i];
      offset = CLAMP(offset, 0, w);
   }
   if (offset < w) {
      RichString_setAttrn(&bar, CRT_colors[BAR_SHADOW], startPos + offset, w - offset);
      RichString_printoffnVal(&bar, y, x + offset, startPos + offset, w - offset);
   }
   RichString_delete(&bar);
   move(y, x + w + 1);
   attrset(CRT_colors[RESET_COLOR]);
}

static void TextMeterMode_draw(Meter* this, int x, int y, int w) {
   const char* caption = Meter_getCaption(this);
   attrset(CRT_colors[METER_TEXT]);
   mvaddnstr(y, x, caption, w);
   attrset(CRT_colors[RESET_COLOR]);
   int captionLen = strlen(caption);
   x += captionLen;
   w -= captionLen;
   if (w <= 0) return;
   RichString out; RichString_begin(&out);
   Meter_displayBuffer(this, &out);
   RichString_printoffnVal(&out, y, x, 0, w);
   RichString_delete(&out);
}

static const char* const GraphMeterMode_dotsAscii[] = {
   /*00*/" ", /*01*/".", /*02*/":",
   /*10*/".", /*11*/".", /*12*/":",
   /*20*/":", /*21*/":", /*22*/":"
};

static void GraphMeterMode_draw(Meter* this, int x, int y, int w) {
   const char* caption = Meter_getCaption(this);
   attrset(CRT_colors[METER_TEXT]);
   int captionLen = 3;
   mvaddnstr(y, x, caption, captionLen);
   x += captionLen;
   w -= captionLen;
   GraphData* data = &this->drawData;
   size_t nValues = data->nValues;
   if (!data->values || nValues < (size_t)(2 * MAXIMUM(w, 1))) {
      size_t newN = 2 * MAXIMUM(w, COLS) + 2;
      double* nv = xcalloc(newN, sizeof(double));
      if (data->values) {
         size_t copy = MINIMUM(nValues, newN);
         memcpy(nv + (newN - copy), data->values + (nValues - copy), copy * sizeof(double));
         free(data->values);
      }
      data->values = nv;
      data->nValues = newN;
      nValues = newN;
   }
   const Machine* host = this->host;
   if (!(host->realtime.tv_sec < data->time.tv_sec || (host->realtime.tv_sec == data->time.tv_sec && host->realtime.tv_usec < data->time.tv_usec))) {
      int globalDelay = host->settings->delay;
      struct timeval delay = { .tv_sec = globalDelay / 10, .tv_usec = (globalDelay % 10) * 100000L };
      timeradd(&host->realtime, &delay, &data->time);
      for (size_t i = 0; i < nValues - 1; i++) data->values[i] = data->values[i + 1];
      double value = 0.0;
      for (int i = 0; i < this->curItems; i++) {
         if (!isnan(this->values[i])) value += this->values[i];
      }
      value = this->total > 0 ? value / this->total : 0;
      data->values[nValues - 1] = value;
   }
   int pixPerRow = 2;
   int i = (int)nValues - (w * 2), k = 0;
   if (i < 0) { k = -i / 2; i = 0; }
   for (; i < (int)nValues - 1; i += 2, k++) {
      int pix = pixPerRow * GRAPH_HEIGHT;
      int v1 = CLAMP((int)lround(data->values[i] * pix), 1, pix);
      int v2 = CLAMP((int)lround(data->values[i + 1] * pix), 1, pix);
      int colorIdx = GRAPH_1;
      for (int line = 0; line < GRAPH_HEIGHT; line++) {
         int line1 = CLAMP(v1 - (GRAPH_HEIGHT - 1 - line) * pixPerRow, 0, pixPerRow);
         int line2 = CLAMP(v2 - (GRAPH_HEIGHT - 1 - line) * pixPerRow, 0, pixPerRow);
         attrset(CRT_colors[colorIdx]);
         mvaddstr(y + line, x + k, GraphMeterMode_dotsAscii[line1 * (pixPerRow + 1) + line2]);
         colorIdx = GRAPH_2;
      }
   }
   attrset(CRT_colors[RESET_COLOR]);
}

static const char* const LEDMeterMode_digitsAscii[] = {
   " __ ", "    ", " __ ", " __ ", "    ", " __ ", " __ ", " __ ", " __ ", " __ ",
   "|  |", "   |", " __|", " __|", "|__|", "|__ ", "|__ ", "   |", "|__|", "|__|",
   "|__|", "   |", "|__ ", " __|", "   |", " __|", "|__|", "   |", "|__|", " __|"
};

static void LEDMeterMode_drawDigit(int x, int y, int n) {
   for (int i = 0; i < 3; i++) mvaddstr(y + i, x, LEDMeterMode_digitsAscii[i * 10 + n]);
}

static void LEDMeterMode_draw(Meter* this, int x, int y, int w) {
   RichString out; RichString_begin(&out);
   Meter_displayBuffer(this, &out);
   int yText = y + 2;
   attrset(CRT_colors[LED_COLOR]);
   const char* caption = Meter_getCaption(this);
   mvaddstr(yText, x, caption);
   int xx = x + strlen(caption);
   int len = RichString_sizeVal(out);
   for (int i = 0; i < len; i++) {
      char c = RichString_getCharVal(&out, i);
      if (c >= '0' && c <= '9') {
         if (xx - x + 4 > w) break;
         LEDMeterMode_drawDigit(xx, y, c - '0');
         xx += 4;
      } else {
         if (xx - x + 1 > w) break;
         mvaddch(yText, xx, (unsigned char)c);
         xx += 1;
      }
   }
   attrset(CRT_colors[RESET_COLOR]);
   RichString_delete(&out);
}

void Meter_draw(Meter* this, int x, int y, int w) {
   if (this->type->draw) { this->type->draw(this, x, y, w); return; }
   switch (this->mode) {
      case TEXT_METERMODE: TextMeterMode_draw(this, x, y, w); break;
      case GRAPH_METERMODE: GraphMeterMode_draw(this, x, y, w); break;
      case LED_METERMODE: LEDMeterMode_draw(this, x, y, w); break;
      default: BarMeterMode_draw(this, x, y, w); break;
   }
}

