/* ======================= CPU meters ======================= */

static const int CPUMeter_attributes[] = { CPU_NICE, CPU_NORMAL, CPU_SYSTEM, CPU_IRQ, CPU_SOFTIRQ, CPU_STEAL, CPU_GUEST, CPU_IOWAIT };

static void CPUMeter_init(Meter* this) {
   unsigned int cpu = this->param;
   if (cpu == 0) {
      Meter_setCaption(this, "Avg");
   } else {
      char caption[16];
      xsnprintf(caption, sizeof(caption), "%3u", this->host->settings->countCPUsFromOne ? cpu : cpu - 1);
      Meter_setCaption(this, caption);
   }
}

static void CPUMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
   unsigned int cpu = this->param;
   if (cpu > host->existingCPUs) {
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "absent");
      for (int i = 0; i < 8; i++) this->values[i] = 0;
      return;
   }
   if (cpu > 0 && !host->cpuData[cpu].online) {
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "offline");
      for (int i = 0; i < 8; i++) this->values[i] = 0;
      return;
   }
   /* caption may need refresh when countCPUsFromOne changes */
   if (cpu != 0) {
      char caption[16];
      xsnprintf(caption, sizeof(caption), "%3u", host->settings->countCPUsFromOne ? cpu : cpu - 1);
      if (strcmp(caption, this->caption) != 0) Meter_setCaption(this, caption);
   }
   int items = 4;
   double percent = Platform_setCPUValues(this->values, cpu, &items, host);
   this->curItems = items;
   char cpuUsageBuffer[8] = { 0 };
   char cpuFrequencyBuffer[16] = { 0 };
   if (host->settings->showCPUUsage) xsnprintf(cpuUsageBuffer, sizeof(cpuUsageBuffer), "%5.1f%%", percent);
   if (host->settings->showCPUFrequency) {
      double cpuFrequency = this->values[8];
      if (isnan(cpuFrequency)) xsnprintf(cpuFrequencyBuffer, sizeof(cpuFrequencyBuffer), "N/A");
      else xsnprintf(cpuFrequencyBuffer, sizeof(cpuFrequencyBuffer), "%4uMHz", (unsigned)lround(cpuFrequency));
   }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s%s%s", cpuUsageBuffer, (cpuUsageBuffer[0] && cpuFrequencyBuffer[0]) ? " " : "", cpuFrequencyBuffer);
}

static void CPUMeter_display(const Meter* this, RichString* out) {
   char buffer[50];
   int len;
   const Settings* settings = this->host->settings;
   if (this->param > this->host->existingCPUs) { RichString_appendAscii(out, CRT_colors[METER_TEXT], "absent"); return; }
   if (this->param > 0 && !this->host->cpuData[this->param].online) { RichString_appendAscii(out, CRT_colors[METER_TEXT], "offline"); return; }
   len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[1]);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], ":");
   RichString_appendnAscii(out, CRT_colors[CPU_NORMAL], buffer, len);
   if (settings->detailedCPUTime) {
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[2]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "sy:");
      RichString_appendnAscii(out, CRT_colors[CPU_SYSTEM], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[0]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "ni:");
      RichString_appendnAscii(out, CRT_colors[CPU_NICE_TEXT], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[3]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "hi:");
      RichString_appendnAscii(out, CRT_colors[CPU_IRQ], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[4]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "si:");
      RichString_appendnAscii(out, CRT_colors[CPU_SOFTIRQ], buffer, len);
      if (!isnan(this->values[5])) {
         len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[5]);
         RichString_appendAscii(out, CRT_colors[METER_TEXT], "st:");
         RichString_appendnAscii(out, CRT_colors[CPU_STEAL], buffer, len);
      }
      if (!isnan(this->values[6])) {
         len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[6]);
         RichString_appendAscii(out, CRT_colors[METER_TEXT], "gu:");
         RichString_appendnAscii(out, CRT_colors[CPU_GUEST], buffer, len);
      }
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[7]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "wa:");
      RichString_appendnAscii(out, CRT_colors[CPU_IOWAIT], buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[2]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "sys:");
      RichString_appendnAscii(out, CRT_colors[CPU_SYSTEM], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[0]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "low:");
      RichString_appendnAscii(out, CRT_colors[CPU_NICE_TEXT], buffer, len);
      if (!isnan(this->values[3])) {
         len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[3]);
         RichString_appendAscii(out, CRT_colors[METER_TEXT], "vir:");
         RichString_appendnAscii(out, CRT_colors[CPU_GUEST], buffer, len);
      }
   }
   if (settings->showCPUFrequency) {
      char cpuFrequencyBuffer[10];
      double cpuFrequency = this->values[8];
      if (isnan(cpuFrequency)) len = xsnprintf(cpuFrequencyBuffer, sizeof(cpuFrequencyBuffer), "N/A ");
      else len = xsnprintf(cpuFrequencyBuffer, sizeof(cpuFrequencyBuffer), "%4uMHz ", (unsigned)lround(cpuFrequency));
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "freq: ");
      RichString_appendnAscii(out, CRT_colors[METER_VALUE], cpuFrequencyBuffer, len);
   }
}

static const char* CPUMeter_getUiName(const Meter* this, char* buf, size_t len) {
   if (this->param == 0) { xsnprintf(buf, len, "CPU average"); return buf; }
   xsnprintf(buf, len, "CPU %u", this->host->settings->countCPUsFromOne ? this->param : this->param - 1);
   return buf;
}

/* multi-cpu meters */
typedef struct AllCPUsData_ { int start; int count; int ncol; } AllCPUsData;

static void AllCPUsMeter_getRange(const Meter* this, int* start, int* count) {
   const Machine* host = this->host;
   int cpus = host->existingCPUs;
   const char* name = this->type->name;
   if (string_startsWith(name, "LeftCPUs")) { *start = 0; *count = cpus / 2; }
   else if (string_startsWith(name, "RightCPUs")) { *start = cpus / 2; *count = cpus - cpus / 2; }
   else { *start = 0; *count = cpus; }
}

static int AllCPUsMeter_columns(const Meter* this) {
   const char* name = this->type->name;
   size_t l = strlen(name);
   if (l && name[l-1] == '8') return 8;
   if (l && name[l-1] == '4') return 4;
   if (l && name[l-1] == '2') return 2;
   return 1;
}

static void AllCPUsMeter_updateMode(Meter* this, MeterModeId mode);

static void AllCPUsMeter_init(Meter* this) {
   int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   this->nSubMeters = count;
   this->subMeters = xcalloc(count + 1, sizeof(Meter*));
   extern const MeterClass CPUMeter_class;
   for (int i = 0; i < count; i++) this->subMeters[i] = Meter_new(this->host, start + i + 1, &CPUMeter_class);
   this->mode = this->type->defaultMode;
   AllCPUsMeter_updateMode(this, this->mode);
}

static void AllCPUsMeter_done(Meter* this) {
   for (int i = 0; i < this->nSubMeters; i++) Meter_delete(this->subMeters[i]);
   free(this->subMeters);
}

static void AllCPUsMeter_updateMode(Meter* this, MeterModeId mode) {
   int ncol = AllCPUsMeter_columns(this);
   int count = this->nSubMeters;
   int h = 1;
   for (int i = 0; i < count; i++) { Meter_setMode(this->subMeters[i], mode); h = this->subMeters[i]->h; }
   int nrows = (count + ncol - 1) / ncol;
   this->h = h * nrows;
   if (this->h == 0) this->h = 1;
}

static void AllCPUsMeter_updateValues(Meter* this) {
   for (int i = 0; i < this->nSubMeters; i++) Meter_updateValues(this->subMeters[i]);
}

static void AllCPUsMeter_draw(Meter* this, int x, int y, int w) {
   int ncol = AllCPUsMeter_columns(this);
   int count = this->nSubMeters;
   if (count == 0) return;
   int colwidth = w / ncol;
   int diff = w - colwidth * ncol;
   int nrows = (count + ncol - 1) / ncol;
   for (int i = 0; i < count; i++) {
      int col = i / nrows;
      int d = col > diff ? diff : col;
      int xpos = x + col * colwidth + d;
      int ypos = y + (i % nrows) * this->subMeters[0]->h;
      Meter_draw(this->subMeters[i], xpos, ypos, colwidth);
   }
}

