static const int MemoryMeter_attributes[] = { MEMORY_USED, MEMORY_SHARED, MEMORY_COMPRESSED, MEMORY_BUFFERS, MEMORY_CACHE };

static void MemoryMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
   this->total = host->totalMem;
   this->values[0] = host->usedMem;
   this->values[1] = host->sharedMem;
   this->values[2] = host->zswap; /* compressed */
   this->values[3] = host->buffersMem;
   this->values[4] = host->cachedMem;
   this->curItems = host->settings->showCachedMemory ? 5 : 2;
   if (!host->settings->showCachedMemory) { /* keep used & shared, hide compressed/buffers/cache */ this->curItems = 2; }
   char used[16], total[16];
   Meter_humanUnit(used, this->values[0], sizeof(used));
   Meter_humanUnit(total, this->total, sizeof(total));
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s/%s", used, total);
}

