typedef struct NetIOData_ { unsigned long long rxb, txb, rxp, txp; uint64_t lastMs; double rxBps, txBps, rxPps, txPps; bool init; } NetIOData;
static NetIOData netIO;
static void NetIO_scan(Machine* host) {
   if (netIO.lastMs == host->realtimeMs) return;
   FILE* f = fopen("/proc/net/dev", "r");
   unsigned long long rxb = 0, txb = 0, rxp = 0, txp = 0;
   if (f) {
      char line[512];
      while (fgets(line, sizeof(line), f)) {
         char* colon = strchr(line, ':'); if (!colon) continue;
         char* name = line; while (*name == ' ') name++;
         if (strncmp(name, "lo:", 3) == 0) continue;
         unsigned long long b, p, a3, a4, a5, a6, a7, a8, tb, tp;
         if (sscanf(colon + 1, "%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu", &b, &p, &a3, &a4, &a5, &a6, &a7, &a8, &tb, &tp) < 10) continue;
         rxb += b; rxp += p; txb += tb; txp += tp;
      }
      fclose(f);
   }
   if (netIO.init && host->realtimeMs > netIO.lastMs) {
      double dt = (host->realtimeMs - netIO.lastMs) / 1000.0;
      netIO.rxBps = (rxb >= netIO.rxb ? rxb - netIO.rxb : 0) / dt; netIO.txBps = (txb >= netIO.txb ? txb - netIO.txb : 0) / dt;
      netIO.rxPps = (rxp >= netIO.rxp ? rxp - netIO.rxp : 0) / dt; netIO.txPps = (txp >= netIO.txp ? txp - netIO.txp : 0) / dt;
   }
   netIO.rxb = rxb; netIO.txb = txb; netIO.rxp = rxp; netIO.txp = txp; netIO.lastMs = host->realtimeMs; netIO.init = true;
}
static const int NetworkIOMeter_attributes[] = { METER_VALUE_IOREAD, METER_VALUE_IOWRITE };
static void NetworkIOMeter_updateValues(Meter* this) {
   NetIO_scan(this->host);
   this->values[0] = netIO.rxBps / 1024.0; this->values[1] = netIO.txBps / 1024.0;
   if (this->values[0] + this->values[1] > this->total) this->total = this->values[0] + this->values[1];
   char r[32], t[32]; humanRate(r, sizeof(r), netIO.rxBps); humanRate(t, sizeof(t), netIO.txBps);
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "rx:%s tx:%s", r, t);
}
static void NetworkIOMeter_display(const Meter* this, RichString* out) {
   (void)this;
   char buffer[32];
   RichString_appendAscii(out, CRT_colors[METER_TEXT], "rx: ");
   humanRate(buffer, sizeof(buffer), netIO.rxBps);
   RichString_appendAscii(out, CRT_colors[METER_VALUE_IOREAD], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " tx: ");
   humanRate(buffer, sizeof(buffer), netIO.txBps);
   RichString_appendAscii(out, CRT_colors[METER_VALUE_IOWRITE], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " (");
   xsnprintf(buffer, sizeof(buffer), "%.0f", netIO.rxPps);
   RichString_appendAscii(out, CRT_colors[METER_VALUE_IOREAD], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], "/");
   xsnprintf(buffer, sizeof(buffer), "%.0f", netIO.txPps);
   RichString_appendAscii(out, CRT_colors[METER_VALUE_IOWRITE], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " pps)");
}

/* ======================= SELinux / Systemd / OpenRC / FDs ======================= */
static void SELinuxMeter_updateValues(Meter* this) {
   struct stat st;
   bool enabled = stat("/sys/fs/selinux", &st) == 0 && S_ISDIR(st.st_mode);
   bool enforcing = false;
   if (enabled) {
      FILE* f = fopen("/sys/fs/selinux/enforce", "r");
      if (f) { int e = 0; if (fscanf(f, "%d", &e) == 1) enforcing = e != 0; fclose(f); } else enabled = false;
   }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s%s", enabled ? "enabled" : "disabled", enabled ? (enforcing ? "; mode: enforcing" : "; mode: permissive") : "");
}
