static const int FileDescriptorMeter_attributes[] = { FILE_DESCRIPTOR_USED, FILE_DESCRIPTOR_MAX };
static void FileDescriptorMeter_updateValues(Meter* this) {
   FILE* f = fopen("/proc/sys/fs/file-nr", "r");
   unsigned long long used = 0, unused = 0, max = 0;
   if (f) { if (fscanf(f, "%llu %llu %llu", &used, &unused, &max) != 3) {} fclose(f); }
   this->values[0] = used; this->values[1] = 0;
   this->total = max;
   if (max >= 65536ULL * 65536ULL) xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%llu/unlimited", used);
   else xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%llu/%llu", used, max);
}
static void FileDescriptorMeter_display(const Meter* this, RichString* out) {
   char buffer[50];
   RichString_appendAscii(out, CRT_colors[METER_TEXT], "used: ");
   xsnprintf(buffer, sizeof(buffer), "%.0f", this->values[0]);
   RichString_appendAscii(out, CRT_colors[FILE_DESCRIPTOR_USED], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " max: ");
   if (this->total >= 65536.0 * 65536.0) xsnprintf(buffer, sizeof(buffer), "unlimited");
   else xsnprintf(buffer, sizeof(buffer), "%.0f", this->total);
   RichString_appendAscii(out, CRT_colors[FILE_DESCRIPTOR_MAX], buffer);
}

