#define ONE_K 1024.0

void Meter_humanUnit(char* buffer, double value, size_t size) {
   static const char unitPrefixes[] = "KMGTPEZY";
   size_t i = 0;
   if (value < 0) value = 0;
   while (value >= ONE_K) {
      if (i >= sizeof(unitPrefixes) - 2) { if (value > 9999.0) { xsnprintf(buffer, size, "inf"); return; } break; }
      value /= ONE_K;
      ++i;
   }
   int precision = 0;
   if (i > 0) {
      precision = value <= 99.9 ? (value <= 9.99 ? 2 : 1) : 0;
      if (precision < 2) {
         double limit = precision == 1 ? 10.0 : 100.0;
         if (value < limit) value = limit;
      }
   }
   xsnprintf(buffer, size, "%.*f%c", precision, value, unitPrefixes[i]);
}

