void Meter_setMode(Meter* this, MeterModeId mode) {
   if (mode <= 0 || mode >= LAST_METERMODE) mode = this->type->defaultMode;
   if (!Meter_supportsMode(this, mode)) mode = this->type->defaultMode;
   this->mode = mode;
   switch (mode) {
