};

static void GraphMeterMode_draw(Meter* this, int x, int y, int w) {
   const char* caption = Meter_getCaption(this);
   attrset(CRT_colors[METER_TEXT]);
   int captionLen = 3;
   mvaddnstr(y, x, caption, captionLen);
   x += captionLen;
   w -= captionLen;
   GraphData* data = &this->drawData;
   size_t nValues = data->nValues;
   if (!data->values || nValues < (size_t)(2 * MAXIMUM(w, 1))) {
      size_t newN = 2 * MAXIMUM(w, COLS) + 2;
      double* nv = xcalloc(newN, sizeof(double));
      if (data->values) {
         size_t copy = MINIMUM(nValues, newN);
         memcpy(nv + (newN - copy), data->values + (nValues - copy), copy * sizeof(double));
         free(data->values);
      }
      data->values = nv;
      data->nValues = newN;
      nValues = newN;
   }
   const Machine* host = this->host;
   if (!(host->realtime.tv_sec < data->time.tv_sec || (host->realtime.tv_sec == data->time.tv_sec && host->realtime.tv_usec < data->time.tv_usec))) {
      int globalDelay = host->settings->delay;
      struct timeval delay = { .tv_sec = globalDelay / 10, .tv_usec = (globalDelay % 10) * 100000L };
      timeradd(&host->realtime, &delay, &data->time);
      for (size_t i = 0; i < nValues - 1; i++) data->values[i] = data->values[i + 1];
      double value = 0.0;
      for (int i = 0; i < this->curItems; i++) {
         if (!isnan(this->values[i])) value += this->values[i];
      }
      value = this->total > 0 ? value / this->total : 0;
      data->values[nValues - 1] = value;
   }
   int pixPerRow = 2;
   int i = (int)nValues - (w * 2), k = 0;
   if (i < 0) { k = -i / 2; i = 0; }
   for (; i < (int)nValues - 1; i += 2, k++) {
      int pix = pixPerRow * GRAPH_HEIGHT;
      int v1 = CLAMP((int)lround(data->values[i] * pix), 1, pix);
      int v2 = CLAMP((int)lround(data->values[i + 1] * pix), 1, pix);
      int colorIdx = GRAPH_1;
      for (int line = 0; line < GRAPH_HEIGHT; line++) {
         int line1 = CLAMP(v1 - (GRAPH_HEIGHT - 1 - line) * pixPerRow, 0, pixPerRow);
         int line2 = CLAMP(v2 - (GRAPH_HEIGHT - 1 - line) * pixPerRow, 0, pixPerRow);
         attrset(CRT_colors[colorIdx]);
         mvaddstr(y + line, x + k, GraphMeterMode_dotsAscii[line1 * (pixPerRow + 1) + line2]);
         colorIdx = GRAPH_2;
      }
   }
   attrset(CRT_colors[RESET_COLOR]);
}

