/* ======================= CPU meters ======================= */

static const int CPUMeter_attributes[] = { CPU_NICE, CPU_NORMAL, CPU_SYSTEM, CPU_IRQ, CPU_SOFTIRQ, CPU_STEAL, CPU_GUEST, CPU_IOWAIT };

static void CPUMeter_init(Meter* this) {
   unsigned int cpu = this->param;
   if (cpu == 0) {
      Meter_setCaption(this, "Avg");
   } else {
      char caption[16];
      xsnprintf(caption, sizeof(caption), "%3u", this->host->settings->countCPUsFromOne ? cpu : cpu - 1);
      Meter_setCaption(this, caption);
   }
}

static void CPUMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
   unsigned int cpu = this->param;
   if (cpu > host->existingCPUs) {
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "absent");
      for (int i = 0; i < 8; i++) this->values[i] = 0;
      return;
   }
   if (cpu > 0 && !host->cpuData[cpu].online) {
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "offline");
      for (int i = 0; i < 8; i++) this->values[i] = 0;
      return;
   }
   /* caption may need refresh when countCPUsFromOne changes */
   if (cpu != 0) {
      char caption[16];
      xsnprintf(caption, sizeof(caption), "%3u", host->settings->countCPUsFromOne ? cpu : cpu - 1);
      if (strcmp(caption, this->caption) != 0) Meter_setCaption(this, caption);
   }
   int items = 4;
   double percent = Platform_setCPUValues(this->values, cpu, &items, host);
   this->curItems = items;
   char cpuUsageBuffer[8] = { 0 };
   char cpuFrequencyBuffer[16] = { 0 };
   if (host->settings->showCPUUsage) xsnprintf(cpuUsageBuffer, sizeof(cpuUsageBuffer), "%5.1f%%", percent);
   if (host->settings->showCPUFrequency) {
      double cpuFrequency = this->values[8];
      if (isnan(cpuFrequency)) xsnprintf(cpuFrequencyBuffer, sizeof(cpuFrequencyBuffer), "N/A");
      else xsnprintf(cpuFrequencyBuffer, sizeof(cpuFrequencyBuffer), "%4uMHz", (unsigned)lround(cpuFrequency));
   }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s%s%s", cpuUsageBuffer, (cpuUsageBuffer[0] && cpuFrequencyBuffer[0]) ? " " : "", cpuFrequencyBuffer);
}

