   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[2]);
      RichString_appendAscii(out, CRT_colors[METER_TEXT], "sys:");
      RichString_appendnAscii(out, CRT_colors[CPU_SYSTEM], buffer, len);
