/* multi-cpu meters */
typedef struct AllCPUsData_ { int start; int count; int ncol; } AllCPUsData;

static void AllCPUsMeter_getRange(const Meter* this, int* start, int* count) {
   const Machine* host = this->host;
   int cpus = host->existingCPUs;
   const char* name = this->type->name;
   if (string_startsWith(name, "LeftCPUs")) { *start = 0; *count = cpus / 2; }
   else if (string_startsWith(name, "RightCPUs")) { *start = cpus / 2; *count = cpus - cpus / 2; }
   else { *start = 0; *count = cpus; }
}

static int AllCPUsMeter_columns(const Meter* this) {
   const char* name = this->type->name;
   size_t l = strlen(name);
   if (l && name[l-1] == '8') return 8;
   if (l && name[l-1] == '4') return 4;
   if (l && name[l-1] == '2') return 2;
   return 1;
}

static void AllCPUsMeter_updateMode(Meter* this, MeterModeId mode);

static void AllCPUsMeter_init(Meter* this) {
   int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   this->nSubMeters = count;
   this->subMeters = xcalloc(count + 1, sizeof(Meter*));
   extern const MeterClass CPUMeter_class;
   for (int i = 0; i < count; i++) this->subMeters[i] = Meter_new(this->host, start + i + 1, &CPUMeter_class);
   this->mode = this->type->defaultMode;
   AllCPUsMeter_updateMode(this, this->mode);
}

static void AllCPUsMeter_done(Meter* this) {
   for (int i = 0; i < this->nSubMeters; i++) Meter_delete(this->subMeters[i]);
   free(this->subMeters);
}

static void AllCPUsMeter_updateMode(Meter* this, MeterModeId mode) {
   int ncol = AllCPUsMeter_columns(this);
   int count = this->nSubMeters;
   int h = 1;
   for (int i = 0; i < count; i++) { Meter_setMode(this->subMeters[i], mode); h = this->subMeters[i]->h; }
   int nrows = (count + ncol - 1) / ncol;
   this->h = h * nrows;
   if (this->h == 0) this->h = 1;
}

static void AllCPUsMeter_updateValues(Meter* this) {
   for (int i = 0; i < this->nSubMeters; i++) Meter_updateValues(this->subMeters[i]);
}

static void AllCPUsMeter_draw(Meter* this, int x, int y, int w) {
   int ncol = AllCPUsMeter_columns(this);
   int count = this->nSubMeters;
   if (count == 0) return;
   int colwidth = w / ncol;
   int diff = w - colwidth * ncol;
   int nrows = (count + ncol - 1) / ncol;
   for (int i = 0; i < count; i++) {
      int col = i / nrows;
      int d = col > diff ? diff : col;
      int xpos = x + col * colwidth + d;
      int ypos = y + (i % nrows) * this->subMeters[0]->h;
      Meter_draw(this->subMeters[i], xpos, ypos, colwidth);
   }
}

