static const int MemoryMeter_attributes[] = { MEMORY_USED, MEMORY_SHARED, MEMORY_COMPRESSED, MEMORY_BUFFERS, MEMORY_CACHE };

static void MemoryMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
   this->total = host->totalMem;
   this->values[0] = host->usedMem;
   this->values[1] = host->sharedMem;
   this->values[2] = host->zswap; /* compressed */
