   char used[16], total[16];
   Meter_humanUnit(used, this->values[0], sizeof(used));
   Meter_humanUnit(total, this->total, sizeof(total));
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s/%s", used, total);
}

