static char* osRelease = NULL;
static void SysArchMeter_updateValues(Meter* this) {
   struct utsname u;
   if (uname(&u) != 0) { xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "(unknown)"); return; }
   if (!osRelease) {
      FILE* f = fopen("/etc/os-release", "r");
      if (f) {
         char line[256];
         while (fgets(line, sizeof(line), f)) {
            if (string_startsWith(line, "PRETTY_NAME=")) {
               char* v = line + 12; size_t l = strlen(v);
               while (l && (v[l-1] == '\n' || v[l-1] == '"')) v[--l] = 0;
               if (*v == '"') v++;
               osRelease = xstrdup(v); break;
            }
         }
         fclose(f);
      }
      if (!osRelease) osRelease = xstrdup("");
   }
   if (osRelease[0]) xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s %s [%s] @ %s", u.sysname, u.release, u.machine, osRelease);
   else xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s %s [%s]", u.sysname, u.release, u.machine);
}

/* ======================= Battery ======================= */
static const int BatteryMeter_attributes[] = { BATTERY };
static void BatteryMeter_updateValues(Meter* this) {
   /* look for a battery in /sys/class/power_supply */
   DIR* d = opendir("/sys/class/power_supply");
   double percent = NAN; int acState = -1; /* 0 = battery, 1 = AC, -1 = unknown */
   if (d) {
      struct dirent* e;
      double totalFull = 0, totalNow = 0;
      while ((e = readdir(d))) {
         if (e->d_name[0] == '.') continue;
         char path[PATH_MAX]; char buf[64];
         xsnprintf(path, sizeof(path), "/sys/class/power_supply/%s/type", e->d_name);
         FILE* f = fopen(path, "r"); if (!f) continue;
         if (!fgets(buf, sizeof(buf), f)) buf[0] = 0; fclose(f);
         if (string_startsWith(buf, "Battery")) {
            unsigned long full = 0, now = 0;
            xsnprintf(path, sizeof(path), "/sys/class/power_supply/%s/energy_full", e->d_name);
            f = fopen(path, "r"); if (f) { if (fscanf(f, "%lu", &full) != 1) full = 0; fclose(f); }
            if (!full) { xsnprintf(path, sizeof(path), "/sys/class/power_supply/%s/charge_full", e->d_name); f = fopen(path, "r"); if (f) { if (fscanf(f, "%lu", &full) != 1) full = 0; fclose(f); } }
            xsnprintf(path, sizeof(path), "/sys/class/power_supply/%s/energy_now", e->d_name);
            f = fopen(path, "r"); if (f) { if (fscanf(f, "%lu", &now) != 1) now = 0; fclose(f); }
            if (!now) { xsnprintf(path, sizeof(path), "/sys/class/power_supply/%s/charge_now", e->d_name); f = fopen(path, "r"); if (f) { if (fscanf(f, "%lu", &now) != 1) now = 0; fclose(f); } }
            totalFull += full; totalNow += now;
         } else if (string_startsWith(buf, "Mains")) {
            xsnprintf(path, sizeof(path), "/sys/class/power_supply/%s/online", e->d_name);
            f = fopen(path, "r"); if (f) { int on = 0; if (fscanf(f, "%d", &on) == 1) acState = on ? 1 : 0; fclose(f); }
         }
      }
      closedir(d);
      if (totalFull > 0) percent = totalNow / totalFull * 100.0;
   }
   this->values[0] = isnan(percent) ? 0 : percent;
   if (isnan(percent)) { xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "N/A"); return; }
   const char* acText = acState == 1 ? "Running on A/C" : acState == 0 ? "Running on battery" : "A/C state unknown";
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%.1f%% %s", percent, acText);
}

/* ======================= Pressure ======================= */
static const int PressureStallMeter_attributes[] = { PRESSURE_STALL_TEN, PRESSURE_STALL_SIXTY, PRESSURE_STALL_THREEHUNDRED };
static void PressureStall_read(Meter* this, const char* file, bool full) {
   char path[64]; xsnprintf(path, sizeof(path), "/proc/pressure/%s", file);
   FILE* f = fopen(path, "r");
   this->values[0] = this->values[1] = this->values[2] = 0; 
   if (!f) { xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "N/A"); return; }
   char line[256];
   while (fgets(line, sizeof(line), f)) {
      double a, b, c;
      if (sscanf(line, full ? "full avg10=%lf avg60=%lf avg300=%lf" : "some avg10=%lf avg60=%lf avg300=%lf", &a, &b, &c) == 3) {
         this->values[0] = a; this->values[1] = b; this->values[2] = c;
      }
   }
   fclose(f);
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s %.2lf%% %.2lf%% %.2lf%%", full ? "full" : "some", this->values[0], this->values[1], this->values[2]);
}
static void PressureStallCPUSome_updateValues(Meter* this) { PressureStall_read(this, "cpu", false); }
static void PressureStallIOSome_updateValues(Meter* this) { PressureStall_read(this, "io", false); }
