   len = xsnprintf(buffer, sizeof(buffer), "%5.2lf%% ", this->values[1]);
   RichString_appendnAscii(out, CRT_colors[PRESSURE_STALL_SIXTY], buffer, len);
   len = xsnprintf(buffer, sizeof(buffer), "%5.2lf%% ", this->values[2]);
   RichString_appendnAscii(out, CRT_colors[PRESSURE_STALL_THREEHUNDRED], buffer, len);
}

/* ======================= ZFS ======================= */
static const int ZfsArcMeter_attributes[] = { ZFS_MFU, ZFS_MRU, ZFS_ANON, ZFS_HEADER, ZFS_OTHER };
static const int ZfsCompressedArcMeter_attributes[] = { ZFS_COMPRESSED };
static void ZfsArcMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
   if (!host->zfsEnabled) { xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "Unavailable"); this->total = 0; for (int i = 0; i < 5; i++) this->values[i] = 0; return; }
   this->total = host->zfsMax / 1024;
   this->values[0] = host->zfsMFU / 1024; this->values[1] = host->zfsMRU / 1024; this->values[2] = host->zfsAnon / 1024;
   this->values[3] = host->zfsHeader / 1024; this->values[4] = host->zfsOther / 1024;
   char used[16], total[16];
   Meter_humanUnit(used, host->zfsSize / 1024, sizeof(used)); Meter_humanUnit(total, this->total, sizeof(total));
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s/%s", used, total);
}
static void ZfsArcMeter_display(const Meter* this, RichString* out) {
   const Machine* host = this->host;
   if (!host->zfsEnabled) { RichString_appendAscii(out, CRT_colors[METER_VALUE_ERROR], "Unavailable"); return; }
   char buffer[50];
   Meter_humanUnit(buffer, this->total, sizeof(buffer));
   RichString_appendAscii(out, CRT_colors[METER_VALUE], buffer);
   Meter_humanUnit(buffer, host->zfsSize / 1024, sizeof(buffer));
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " Used:");
   RichString_appendAscii(out, CRT_colors[METER_VALUE], buffer);
   const char* names[] = { " MFU:", " MRU:", " Anon:", " Hdr:", " Oth:" };
   for (int i = 0; i < 5; i++) {
      Meter_humanUnit(buffer, this->values[i], sizeof(buffer));
      RichString_appendAscii(out, CRT_colors[METER_TEXT], names[i]);
      RichString_appendAscii(out, CRT_colors[ZfsArcMeter_attributes[i]], buffer);
   }
}
static void ZfsCompressedArcMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
