/* ======================= Disk / Network ======================= */
typedef struct DiskIOData_ { unsigned long long lastRead, lastWrite, lastMsTimeSpent; uint64_t lastUpdateMs; double readRate, writeRate, utilisation; unsigned int numDisks; bool init; } DiskIOData;
static DiskIOData diskIO;

static void DiskIO_scan(Machine* host) {
   if (diskIO.lastUpdateMs == host->realtimeMs) return;
   FILE* f = fopen("/proc/diskstats", "r");
   unsigned long long read = 0, write = 0, timeSpent = 0; unsigned int numDisks = 0;
   if (f) {
      char line[512];
      while (fgets(line, sizeof(line), f)) {
         unsigned int maj, min; char name[64]; unsigned long long rd, rdm, rdsec, rdt, wr, wrm, wrsec, wrt, io, tms, wms;
         if (sscanf(line, "%u %u %63s %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu", &maj, &min, name, &rd, &rdm, &rdsec, &rdt, &wr, &wrm, &wrsec, &wrt, &io, &tms, &wms) < 14) continue;
         /* skip partitions: heuristics: name ends with digit and starts with sd/hd/vd/xvd  */
         size_t l = strlen(name);
         if ((string_startsWith(name, "sd") || string_startsWith(name, "hd") || string_startsWith(name, "vd") || string_startsWith(name, "xvd")) && isdigit((unsigned char)name[l-1])) continue;
         if (string_startsWith(name, "nvme") && strchr(name, 'p')) continue;
         if (string_startsWith(name, "mmcblk") && strchr(name, 'p')) continue;
         if (string_startsWith(name, "loop") || string_startsWith(name, "ram") || string_startsWith(name, "zram") || string_startsWith(name, "dm-") || string_startsWith(name, "md") || string_startsWith(name, "sr")) continue;
         read += rdsec * 512; write += wrsec * 512; timeSpent += tms; numDisks++;
      }
      fclose(f);
   }
   if (diskIO.init && host->realtimeMs > diskIO.lastUpdateMs) {
      double dt = (host->realtimeMs - diskIO.lastUpdateMs) / 1000.0;
      diskIO.readRate = (read >= diskIO.lastRead ? read - diskIO.lastRead : 0) / dt;
      diskIO.writeRate = (write >= diskIO.lastWrite ? write - diskIO.lastWrite : 0) / dt;
      unsigned long long dts = timeSpent >= diskIO.lastMsTimeSpent ? timeSpent - diskIO.lastMsTimeSpent : 0;
      diskIO.utilisation = numDisks ? (double)dts / (dt * 1000.0 * numDisks) * 100.0 : 0;
      if (diskIO.utilisation > 100) diskIO.utilisation = 100;
   } else { diskIO.readRate = diskIO.writeRate = diskIO.utilisation = 0; }
   diskIO.lastRead = read; diskIO.lastWrite = write; diskIO.lastMsTimeSpent = timeSpent; diskIO.numDisks = numDisks;
   diskIO.lastUpdateMs = host->realtimeMs; diskIO.init = true;
}

static void humanRate(char* buf, size_t len, double bytesPerSec) {
   const char* units[] = { "KiB/s", "MiB/s", "GiB/s", "TiB/s" };
   double v = bytesPerSec / 1024.0;
   int i = 0;
   while (v >= 1024.0 && i < 3) { v /= 1024.0; i++; }
   if (i == 0) xsnprintf(buf, len, "%.0f%s", v, units[i]);
   else xsnprintf(buf, len, "%.2f%s", v, units[i]);
}

static const int DiskIOMeter_attributes[] = { METER_VALUE_NOTICE, METER_VALUE_IOREAD, METER_VALUE_IOWRITE };
static void DiskIOMeter_updateValues(Meter* this) {
   DiskIO_scan(this->host);
   this->values[0] = diskIO.utilisation; this->values[1] = diskIO.readRate / 1024.0; this->values[2] = diskIO.writeRate / 1024.0;
   this->total = 100.0;
   this->curItems = 1;
   char r[32], w[32]; humanRate(r, sizeof(r), diskIO.readRate); humanRate(w, sizeof(w), diskIO.writeRate);
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%.1f%% %s %s", diskIO.utilisation, r, w);
}
static void DiskIORate_appendRates(RichString* out) {
   char buffer[32];
   RichString_appendAscii(out, CRT_colors[METER_TEXT], "read: ");
   humanRate(buffer, sizeof(buffer), diskIO.readRate);
   RichString_appendAscii(out, CRT_colors[METER_VALUE_IOREAD], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " write: ");
   humanRate(buffer, sizeof(buffer), diskIO.writeRate);
   RichString_appendAscii(out, CRT_colors[METER_VALUE_IOWRITE], buffer);
}
static void DiskIOTime_appendBusy(RichString* out) {
   char buffer[32];
   xsnprintf(buffer, sizeof(buffer), "%.1f%%", diskIO.utilisation);
   RichString_appendAscii(out, CRT_colors[METER_VALUE], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], " busy (");
   xsnprintf(buffer, sizeof(buffer), "%u", diskIO.numDisks);
   RichString_appendAscii(out, CRT_colors[METER_VALUE], buffer);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], diskIO.numDisks == 1 ? " disk)" : " disks)");
}
static void DiskIOMeter_display(const Meter* this, RichString* out) {
   (void)this;
   if (!diskIO.init) { RichString_appendAscii(out, CRT_colors[METER_VALUE_ERROR], "no data"); return; }
   DiskIORate_appendRates(out);
   RichString_appendAscii(out, CRT_colors[METER_TEXT], "; ");
   DiskIOTime_appendBusy(out);
}
