cat > header.c <<'EOF'
#include "header.h"
#include "crt.h"

static void Meter_free(void* m) { Meter_delete((Meter*)m); }

Header* Header_new(Machine* host, Settings* settings, HeaderLayout hLayout) {
   Header* this = xcalloc(1, sizeof(Header));
   this->host = host;
   this->settings = settings;
   this->headerLayout = hLayout;
   this->columns = xcalloc(4, sizeof(Vector*));
   for (int i = 0; i < 4; i++) this->columns[i] = Vector_new(Meter_free);
   return this;
}

void Header_delete(Header* this) {
   if (!this) return;
   for (int i = 0; i < 4; i++) Vector_delete(this->columns[i]);
   free(this->columns);
   free(this);
}

int Header_columns(const Header* this) { return HeaderLayout_layouts[this->headerLayout].columns; }

void Header_setLayout(Header* this, HeaderLayout hLayout) {
   int oldColumns = Header_columns(this);
   int newColumns = HeaderLayout_layouts[hLayout].columns;
   if (newColumns < oldColumns) {
      Vector* last = this->columns[newColumns - 1];
      for (int i = newColumns; i < oldColumns; i++) {
         while (Vector_size(this->columns[i]) > 0) Vector_add(last, Vector_remove(this->columns[i], 0));
      }
   }
   this->headerLayout = hLayout;
   Header_calculateHeight(this);
}

void Header_populateFromSettings(Header* this) {
   Header_setLayout(this, this->settings->hLayout);
   for (int col = 0; col < Header_columns(this); col++) {
      Vector_prune(this->columns[col]);
      const MeterColumnSettings* c = &this->settings->hColumns[col];
      for (size_t i = 0; i < c->len; i++) {
         Meter* m = Header_addMeterByName(this, c->names[i], col);
         if (m && c->modes && c->modes[i]) Meter_setMode(m, c->modes[i]);
      }
   }
   Header_calculateHeight(this);
}

void Header_writeBackToSettings(const Header* this) {
   Settings* settings = this->settings;
   settings->hLayout = this->headerLayout;
   for (int col = 0; col < 4; col++) {
      MeterColumnSettings* c = &settings->hColumns[col];
      string_freeArray(c->names); free(c->modes);
      int n = Vector_size(this->columns[col]);
      c->names = xcalloc(n + 1, sizeof(char*));
      c->modes = xcalloc(n + 1, sizeof(int));
      c->len = n;
      for (int i = 0; i < n; i++) {
         Meter* m = Vector_get(this->columns[col], i);
         char buf[64]; Meter_formatName(buf, sizeof(buf), m);
         c->names[i] = xstrdup(buf);
         c->modes[i] = m->mode;
      }
   }
}

Meter* Header_addMeterByClass(Header* this, const MeterClass* type, unsigned int param, unsigned int column) {
   Meter* m = Meter_new(this->host, param, type);
   Vector_add(this->columns[column], m);
   return m;
}

Meter* Header_addMeterByName(Header* this, const char* name, unsigned int column) {
   unsigned int param;
   const MeterClass* type = Meter_findType(name, &param);
   if (!type) return NULL;
   return Header_addMeterByClass(this, type, param, column);
}

void Header_setMeterMode(Header* this, int i, MeterModeId mode, unsigned int column) {
   Meter* m = Vector_get(this->columns[column], i);
   if (m) Meter_setMode(m, mode);
}

void Header_reinit(Header* this) {
   for (int col = 0; col < Header_columns(this); col++) {
      for (int i = 0; i < Vector_size(this->columns[col]); i++) {
         Meter* m = Vector_get(this->columns[col], i);
         if (m->type->init) m->type->init(m);
      }
   }
}

int Header_getColumnWidth(const Header* this, int column) {
   int ncols = Header_columns(this);
   int pad = this->settings->headerMargin ? 2 : 0;
   int available = COLS - 2 * pad - (ncols - 1);
   if (available < 0) available = 0;
   return available * HeaderLayout_layouts[this->headerLayout].widths[column] / 100;
}

int Header_getColumnX(const Header* this, int column) {
   int pad = this->settings->headerMargin ? 2 : 0;
   int x = pad;
   for (int i = 0; i < column; i++) x += Header_getColumnWidth(this, i) + 1;
   return x;
}

void Header_updateData(Header* this) {
   for (int col = 0; col < Header_columns(this); col++) {
      for (int i = 0; i < Vector_size(this->columns[col]); i++) Meter_updateValues(Vector_get(this->columns[col], i));
   }
}

void Header_draw(const Header* this) {
   int height = this->height;
   int pad = this->pad;
   attrset(CRT_colors[RESET_COLOR]);
   for (int y = 0; y < height; y++) mvhline(y, 0, ' ', COLS);
   for (int col = 0; col < Header_columns(this); col++) {
      int width = Header_getColumnWidth(this, col);
      int x = Header_getColumnX(this, col);
      int y = pad;
      for (int i = 0; i < Vector_size(this->columns[col]); i++) {
         Meter* m = Vector_get(this->columns[col], i);
         Meter_draw(m, x, y, width);
         y += m->h;
      }
   }
   attrset(CRT_colors[RESET_COLOR]);
}

int Header_calculateHeight(Header* this) {
   int pad = this->settings->headerMargin ? 1 : 0;
   int maxHeight = 0;
   for (int col = 0; col < Header_columns(this); col++) {
      int h = 0;
      for (int i = 0; i < Vector_size(this->columns[col]); i++) h += ((Meter*)Vector_get(this->columns[col], i))->h;
      if (h > maxHeight) maxHeight = h;
   }
   this->height = maxHeight + 2 * pad;
   if (maxHeight == 0) this->height = 0;
   this->pad = pad;
   return this->height;
}
