#include "panel.h"
#include "crt.h"
#include <math.h>
#include <sys/time.h>

/* ================= FunctionBar ================= */
static const char* const FunctionBar_FKeys[] = { "F1", "F2", "F3", "F4", "F5", "F6", "F7", "F8", "F9", "F10", NULL };
static const int FunctionBar_FEvents[] = { KEY_F(1), KEY_F(2), KEY_F(3), KEY_F(4), KEY_F(5), KEY_F(6), KEY_F(7), KEY_F(8), KEY_F(9), KEY_F(10) };
static const char* const FunctionBar_EnterEscKeys[] = { "Enter", "Esc", NULL };
static const int FunctionBar_EnterEscEvents[] = { 13, 27 };

FunctionBar* FunctionBar_newEnterEsc(const char* enter, const char* esc) {
   const char* functions[] = { enter, esc, NULL };
   return FunctionBar_new(functions, FunctionBar_EnterEscKeys, FunctionBar_EnterEscEvents);
}

FunctionBar* FunctionBar_new(const char* const* functions, const char* const* keys, const int* events) {
   FunctionBar* this = xcalloc(1, sizeof(FunctionBar));
   int n = 0;
   if (functions) while (functions[n]) n++;
   this->size = n;
   this->functions = xcalloc(n + 1, sizeof(char*));
   this->keys = xcalloc(n + 1, sizeof(char*));
   this->events = xcalloc(n + 1, sizeof(int));
   for (int i = 0; i < n; i++) {
      this->functions[i] = xstrdup(functions[i]);
      if (keys && events) { this->keys[i] = xstrdup(keys[i]); this->events[i] = events[i]; }
      else { this->keys[i] = xstrdup(i < 10 ? FunctionBar_FKeys[i] : ""); this->events[i] = i < 10 ? FunctionBar_FEvents[i] : ERR; }
   }
   return this;
}

void FunctionBar_delete(FunctionBar* this) {
   if (!this) return;
   for (int i = 0; i < this->size; i++) { free(this->functions[i]); free(this->keys[i]); }
   free(this->functions); free(this->keys); free(this->events); free(this);
}

void FunctionBar_setLabel(FunctionBar* this, int event, const char* text) {
   for (int i = 0; i < this->size; i++) {
      if (this->events[i] == event) { free(this->functions[i]); this->functions[i] = xstrdup(text); break; }
   }
}

void FunctionBar_append(FunctionBar* this, const char* text, int attr) {
   (void)attr;
   int n = this->size;
   this->functions = xrealloc(this->functions, (n + 2) * sizeof(char*));
   this->keys = xrealloc(this->keys, (n + 2) * sizeof(char*));
   this->events = xrealloc(this->events, (n + 2) * sizeof(int));
   this->functions[n] = xstrdup(text); this->keys[n] = xstrdup(""); this->events[n] = ERR;
   this->size++;
}

int FunctionBar_draw(const FunctionBar* this) { return FunctionBar_drawExtra(this, NULL, -1, false); }

int FunctionBar_drawExtra(const FunctionBar* this, const char* buffer, int attr, bool setCursor) {
   int cursorX = 0;
   attrset(CRT_colors[FUNCTION_BAR]);
   mvhline(LINES - 1, 0, ' ', COLS);
   int x = 0;
   for (int i = 0; i < this->size; i++) {
      attrset(CRT_colors[FUNCTION_KEY]);
      mvaddstr(LINES - 1, x, this->keys[i]);
      x += strlen(this->keys[i]);
      attrset(CRT_colors[FUNCTION_BAR]);
      mvaddstr(LINES - 1, x, this->functions[i]);
      x += strlen(this->functions[i]);
   }
   if (buffer) {
      attrset(attr);
      mvaddstr(LINES - 1, x, buffer);
      x += strlen(buffer);
      cursorX = x;
   }
   attrset(CRT_colors[RESET_COLOR]);
   if (setCursor) { curs_set(1); } else { curs_set(0); }
   return cursorX;
}

int FunctionBar_synthesizeEvent(const FunctionBar* this, int pos) {
   int x = 0;
   for (int i = 0; i < this->size; i++) {
      x += strlen(this->keys[i]);
      x += strlen(this->functions[i]);
      if (pos < x) return this->events[i];
   }
   return ERR;
}

/* ================= Items ================= */
ListItem* ListItem_new(const char* value, int key) { ListItem* this = xcalloc(1, sizeof(ListItem)); this->value = xstrdup(value); this->key = key; return this; }
void ListItem_delete(void* p) { ListItem* this = p; if (!this) return; free(this->value); free(this); }
void ListItem_append(ListItem* this, const char* text) { char* n = xasprintf("%s%s", this->value, text); free(this->value); this->value = n; }
void ListItem_display(const void* item, RichString* out) {
   const ListItem* this = item;
   if (this->moving) {
      RichString_writeAscii(out, CRT_colors[DEFAULT_COLOR], "+ ");
   } else {
      RichString_prune(out);
   }
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], this->value);
}
int ListItem_compare(const void* a, const void* b) {
   const ListItem* x = *(const ListItem* const*)a; const ListItem* y = *(const ListItem* const*)b;
   return strcmp(x->value, y->value);
}

CheckItem* CheckItem_newByRef(const char* text, bool* ref) { CheckItem* this = xcalloc(1, sizeof(CheckItem)); this->text = xstrdup(text); this->ref = ref; return this; }
CheckItem* CheckItem_newByVal(const char* text, bool value) { CheckItem* this = xcalloc(1, sizeof(CheckItem)); this->text = xstrdup(text); this->value = value; return this; }
void CheckItem_delete(void* p) { CheckItem* this = p; if (!this) return; free(this->text); free(this); }
bool CheckItem_get(const CheckItem* this) { return this->ref ? *this->ref : this->value; }
void CheckItem_set(CheckItem* this, bool v) { if (this->ref) *this->ref = v; else this->value = v; }
void CheckItem_display(const void* item, RichString* out) {
   const CheckItem* this = item;
   RichString_writeAscii(out, CRT_colors[CHECK_BOX], "[");
   RichString_appendAscii(out, CRT_colors[CHECK_MARK], CheckItem_get(this) ? "x" : " ");
   RichString_appendAscii(out, CRT_colors[CHECK_BOX], "]");
   RichString_appendAscii(out, CRT_colors[CHECK_TEXT], "    ");
   RichString_appendAscii(out, CRT_colors[CHECK_TEXT], this->text);
}

/* ================= Panel ================= */
Panel* Panel_new(int x, int y, int w, int h, Panel_DisplayFn displayFn, void (*freeFn)(void*), bool owner, FunctionBar* fuBar) {
   Panel* this = xcalloc(1, sizeof(Panel));
   this->x = x; this->y = y; this->w = w; this->h = h;
   this->items = Vector_new(owner ? freeFn : NULL);
   this->displayFn = displayFn;
   this->scrollV = 0; this->scrollH = 0;
   this->selected = 0; this->oldSelected = 0;
   this->needsRedraw = true;
   this->wasFocus = false;
   RichString_begin(&this->header);
   this->defaultBar = fuBar;
   this->currentBar = fuBar;
   this->selectionColorId = PANEL_SELECTION_FOCUS;
   return this;
}

void Panel_delete(Panel* this) {
   if (!this) return;
   Vector_delete(this->items);
   RichString_delete(&this->header);
   FunctionBar_delete(this->defaultBar);
   free(this);
}

void Panel_setHeader(Panel* this, const char* header) {
   RichString_writeAscii(&this->header, CRT_colors[PANEL_HEADER_FOCUS], header);
   this->needsRedraw = true;
}
void Panel_setNoHeader(Panel* this) { RichString_prune(&this->header); }
void Panel_setSelectionColor(Panel* this, int colorId) { this->selectionColorId = colorId; }
void Panel_move(Panel* this, int x, int y) { this->x = x; this->y = y; this->needsRedraw = true; }
void Panel_resize(Panel* this, int w, int h) { this->w = w; this->h = h; this->needsRedraw = true; }
void Panel_prune(Panel* this) { Vector_prune(this->items); this->scrollV = 0; this->selected = 0; this->oldSelected = 0; this->needsRedraw = true; }
void Panel_add(Panel* this, void* item) { Vector_add(this->items, item); this->needsRedraw = true; }
void Panel_insert(Panel* this, int i, void* item) { Vector_insert(this->items, i, item); this->needsRedraw = true; }
void Panel_set(Panel* this, int i, void* item) { Vector_set(this->items, i, item); }
void* Panel_get(Panel* this, int i) { return Vector_get(this->items, i); }
void* Panel_remove(Panel* this, int i) {
   this->needsRedraw = true;
   void* removed = Vector_remove(this->items, i);
   if (this->selected > 0 && this->selected >= Vector_size(this->items)) this->selected--;
   return removed;
}
void* Panel_getSelected(Panel* this) { return Vector_size(this->items) > 0 ? Vector_get(this->items, this->selected) : NULL; }
void Panel_moveSelectedUp(Panel* this) { if (this->selected > 0) { Vector_moveUp(this->items, this->selected); this->selected--; this->needsRedraw = true; } }
void Panel_moveSelectedDown(Panel* this) { if (this->selected + 1 < Vector_size(this->items)) { Vector_moveDown(this->items, this->selected); this->selected++; this->needsRedraw = true; } }
int Panel_getSelectedIndex(const Panel* this) { return this->selected; }
int Panel_size(const Panel* this) { return Vector_size(this->items); }
void Panel_setSelected(Panel* this, int selected) {
   int size = Vector_size(this->items);
   if (selected >= size) selected = size - 1;
   if (selected < 0) selected = 0;
   this->selected = selected;
}
void Panel_splice(Panel* this, Vector* from) {
   Vector_prune(this->items);
   for (int i = 0; i < Vector_size(from); i++) Vector_add(this->items, Vector_get(from, i));
   this->needsRedraw = true;
}

void Panel_draw(Panel* this, bool force_redraw, bool focus, bool highlightSelected, bool hideFunctionBar) {
   int size = Vector_size(this->items);
   int scrollH = this->scrollH;
   int y = this->y;
   int x = this->x;
   int h = this->h;
   if (hideFunctionBar) h++;
   int headerLen = RichString_sizeVal(this->header);
   if (headerLen > 0) {
      int attr = focus ? CRT_colors[PANEL_HEADER_FOCUS] : CRT_colors[PANEL_HEADER_UNFOCUS];
      attrset(attr);
      mvhline(y, x, ' ', this->w);
      if (scrollH < headerLen) {
         RichString_setAttr(&this->header, attr);
         RichString_printoffnVal(&this->header, y, x, scrollH, MINIMUM(headerLen - scrollH, this->w));
      }
      attrset(CRT_colors[RESET_COLOR]);
      y++;
   }
   // ensure scroll area is visible
   if (this->selected - this->scrollV < 0) this->scrollV = this->selected;
   else if (this->selected - this->scrollV >= h) this->scrollV = this->selected - h + 1;
   // ensure scrollV is not too far
   if (this->scrollV + h > size) { this->scrollV = MAXIMUM(0, size - h); this->needsRedraw = true; }
   int first = this->scrollV;
   int upTo = MINIMUM(first + h, size);
   int selectionColor = focus ? CRT_colors[this->selectionColorId] : CRT_colors[PANEL_SELECTION_UNFOCUS];
   RichString out; RichString_begin(&out);
   if (this->needsRedraw || force_redraw) {
      int line = 0;
      for (int i = first; line < h && i < upTo; i++, line++) {
         void* item = Vector_get(this->items, i);
         RichString_prune(&out);
         this->displayFn(item, &out);
         int itemLen = RichString_sizeVal(out);
         int amt = MINIMUM(itemLen - scrollH, this->w);
         bool selected = (i == this->selected);
         if (selected && highlightSelected) {
            attrset(selectionColor);
            RichString_setAttr(&out, selectionColor);
            this->selectedLen = itemLen;
         }
         mvhline(y + line, x, ' ', this->w);
         if (amt > 0) RichString_printoffnVal(&out, y + line, x, scrollH, amt);
         if (selected) attrset(CRT_colors[RESET_COLOR]);
      }
      for (; line < h; line++) mvhline(y + line, x, ' ', this->w);
   } else {
      void* oldItem = Vector_get(this->items, this->oldSelected);
      if (oldItem) {
         RichString_prune(&out);
         this->displayFn(oldItem, &out);
         int oldLen = RichString_sizeVal(out);
         int amt = MINIMUM(oldLen - scrollH, this->w);
         mvhline(y + this->oldSelected - first, x, ' ', this->w);
         if (amt > 0) RichString_printoffnVal(&out, y + this->oldSelected - first, x, scrollH, amt);
      }
      void* newItem = Vector_get(this->items, this->selected);
      if (newItem) {
         RichString_prune(&out);
         this->displayFn(newItem, &out);
         int newLen = RichString_sizeVal(out);
         this->selectedLen = newLen;
         int amt = MINIMUM(newLen - scrollH, this->w);
         if (highlightSelected) { attrset(selectionColor); RichString_setAttr(&out, selectionColor); }
         mvhline(y + this->selected - first, x, ' ', this->w);
         if (amt > 0) RichString_printoffnVal(&out, y + this->selected - first, x, scrollH, amt);
         attrset(CRT_colors[RESET_COLOR]);
      }
   }
   RichString_delete(&out);
   this->oldSelected = this->selected;
   this->wasFocus = focus;
   this->needsRedraw = false;
   move(0, 0);
}

bool Panel_onKey(Panel* this, int key) {
   int size = Vector_size(this->items);
   #define PANEL_SCROLL(amount) do { this->selected += (amount); this->scrollV = CLAMP(this->scrollV + (amount), 0, MAXIMUM(0, size - this->h)); this->needsRedraw = true; } while (0)
   switch (key) {
   case KEY_DOWN: case KEY_CTRL('N'): this->selected++; break;
   case KEY_UP: case KEY_CTRL('P'): this->selected--; break;
   case KEY_LEFT: case KEY_CTRL('B'):
      if (this->scrollH > 0) { this->scrollH -= MAXIMUM(CRT_scrollHAmount, 0); if (this->scrollH < 0) this->scrollH = 0; this->needsRedraw = true; }
      break;
   case KEY_RIGHT: case KEY_CTRL('F'):
      this->scrollH += CRT_scrollHAmount; this->needsRedraw = true;
      break;
   case KEY_PPAGE: PANEL_SCROLL(-(this->h - 1)); break;
   case KEY_NPAGE: PANEL_SCROLL(+(this->h - 1)); break;
   case KEY_WHEELUP: PANEL_SCROLL(-CRT_scrollWheelVAmount); break;
   case KEY_WHEELDOWN: PANEL_SCROLL(+CRT_scrollWheelVAmount); break;
   case KEY_HOME: this->selected = 0; break;
   case KEY_END: this->selected = size - 1; break;
   case KEY_CTRL('A'): case '^': this->scrollH = 0; this->needsRedraw = true; break;
   case KEY_CTRL('E'): case '$': this->scrollH = MAXIMUM(this->selectedLen - this->w, 0); this->needsRedraw = true; break;
   default: return false;
   }
   #undef PANEL_SCROLL
   if (this->selected < 0 || size == 0) this->selected = 0;
   else if (this->selected >= size) this->selected = size - 1;
   if (this->selected != this->oldSelected) { /* redraw selection only */ }
   return true;
}

HandlerResult Panel_selectByTyping(Panel* this, int ch) {
   int size = Vector_size(this->items);
   if (!this->eventHandlerState) this->eventHandlerState = xcalloc(100, sizeof(char));
   char* buffer = this->eventHandlerState;
   if (ch > 0 && ch < 255 && isprint(ch)) {
      int len = strlen(buffer);
      if (len < 99) { buffer[len] = ch; buffer[len + 1] = 0; }
      for (int try = 0; try < 2; try++) {
         len = strlen(buffer);
         for (int i = 0; i < size; i++) {
            RichString out; RichString_begin(&out);
            this->displayFn(Vector_get(this->items, i), &out);
            char text[256]; int n = MINIMUM(RichString_sizeVal(out), 255);
            for (int k = 0; k < n; k++) text[k] = RichString_getCharVal(&out, k);
            text[n] = 0;
            RichString_delete(&out);
            if (strncasecmp(text, buffer, len) == 0) { Panel_setSelected(this, i); return HANDLED; }
         }
         buffer[0] = ch; buffer[1] = 0;
      }
      return HANDLED;
   } else if (ch != ERR) {
      buffer[0] = 0;
   }
   if (ch == 13) return BREAK_LOOP;
   return IGNORED;
}

/* ================= IncSet ================= */
static const char* const searchFunctions[] = { "Next  ", "Prev   ", "Cancel ", " Search: ", NULL };
static const char* const searchKeys[] = { "F3", "S-F3", "Esc", "  " };
static const int searchEvents[] = { KEY_F(3), KEY_F(15), 27, ERR };
static const char* const filterFunctions[] = { "Done  ", "Clear ", " Filter: ", NULL };
static const char* const filterKeys[] = { "Enter", "Esc", "  " };
static const int filterEvents[] = { 13, 27, ERR };

IncSet* IncSet_new(FunctionBar* bar) {
   IncSet* this = xcalloc(1, sizeof(IncSet));
   this->modes[INC_SEARCH].bar = FunctionBar_new(searchFunctions, searchKeys, searchEvents);
   this->modes[INC_SEARCH].isFilter = false;
   this->modes[INC_FILTER].bar = FunctionBar_new(filterFunctions, filterKeys, filterEvents);
   this->modes[INC_FILTER].isFilter = true;
   this->active = NULL;
   this->filtering = false;
   this->found = true;
   this->defaultBar = bar;
   return this;
}
void IncSet_delete(IncSet* this) { if (!this) return; FunctionBar_delete(this->modes[0].bar); FunctionBar_delete(this->modes[1].bar); free(this); }
bool IncSet_isActive(const IncSet* this) { return this->active != NULL; }
bool IncSet_filterActive(const IncSet* this) { return this->filtering; }
const char* IncSet_getFilter(const IncSet* this) { return this->filtering ? this->modes[INC_FILTER].buffer : NULL; }
void IncSet_setFilter(IncSet* this, const char* filter) {
   IncMode* mode = &this->modes[INC_FILTER];
   size_t len = strlen(filter);
   if (len > INCMODE_MAX) len = INCMODE_MAX;
   memcpy(mode->buffer, filter, len); mode->buffer[len] = 0; mode->index = len;
   this->filtering = len > 0;
}
void IncSet_reset(IncSet* this, IncType type) { this->modes[type].index = 0; this->modes[type].buffer[0] = 0; if (type == INC_FILTER) this->filtering = false; }
void IncSet_activate(IncSet* this, IncType type, Panel* panel) {
   this->active = &this->modes[type];
   panel->currentBar = this->active->bar;
   this->panel = panel;
   this->found = true;
}
static void IncSet_deactivate(IncSet* this) {
   if (this->panel) this->panel->currentBar = this->defaultBar;
   this->active = NULL;
}

static bool search(IncSet* this, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   IncMode* mode = this->active;
   int size = Panel_size(panel);
   bool found = false;
   for (int i = 0; i < size; i++) {
      const char* v = getPanelValue(panel, i);
      if (v && string_containsI(v, mode->buffer, false)) { Panel_setSelected(panel, i); found = true; break; }
   }
   return found;
}

static bool searchNext(IncSet* this, Panel* panel, IncMode_GetPanelValue getPanelValue, bool forward) {
   IncMode* mode = this->active;
   int size = Panel_size(panel);
   if (size == 0) return false;
   int start = Panel_getSelectedIndex(panel);
   int i = start;
   for (int n = 0; n < size; n++) {
      i = forward ? (i + 1) % size : (i - 1 + size) % size;
      const char* v = getPanelValue(panel, i);
      if (v && string_containsI(v, mode->buffer, false)) { Panel_setSelected(panel, i); return true; }
   }
   return false;
}

bool IncSet_handleKey(IncSet* this, int ch, Panel* panel, IncMode_GetPanelValue getPanelValue, Vector* lines) {
   (void)lines;
   if (ch == ERR) return true;
   IncMode* mode = this->active;
   if (!mode) return false;
   int size = Panel_size(panel);
   bool filterChanged = false;
   bool doSearch = true;
   if (ch == KEY_F(3) || ch == KEY_F(15)) {
      if (mode->isFilter) return true;
      if (size == 0 || mode->index == 0) return true;
      this->found = searchNext(this, panel, getPanelValue, ch == KEY_F(3));
      doSearch = false;
   } else if (0 < ch && ch < 255 && isprint((char)ch)) {
      if (mode->index < INCMODE_MAX) {
         mode->buffer[mode->index] = (char)ch;
         mode->index++;
         mode->buffer[mode->index] = 0;
         if (mode->isFilter) { filterChanged = true; if (mode->index == 1) this->filtering = true; }
      }
   } else if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
      if (mode->index > 0) {
         mode->index--;
         mode->buffer[mode->index] = 0;
         if (mode->isFilter) { filterChanged = true; if (mode->index == 0) { this->filtering = false; IncSet_reset(this, INC_FILTER); } }
      } else {
         doSearch = false;
      }
   } else if (ch == KEY_RESIZE) {
      doSearch = (mode->index > 0);
   } else {
      if (mode->isFilter) {
         filterChanged = true;
         if (ch == 27) { this->filtering = false; IncSet_reset(this, INC_FILTER); }
      } else {
         if (ch == 27) { /* keep selection */ }
      }
      IncSet_deactivate(this);
      doSearch = false;
   }
   if (doSearch && !mode->isFilter) {
      if (mode->index > 0) this->found = search(this, panel, getPanelValue);
      else this->found = true;
   }
   if (filterChanged) {
      /* caller re-filters based on IncSet_getFilter */
   }
   return filterChanged ? true : true;
}

void IncSet_drawBar(const IncSet* this, int attr) {
   if (this->active) {
      int cursorX = FunctionBar_drawExtra(this->active->bar, this->active->buffer, this->found ? attr : CRT_colors[FAILED_SEARCH], true);
      (void)cursorX;
      move(LINES - 1, cursorX);
   } else {
      FunctionBar_draw(this->defaultBar);
   }
}

int IncSet_synthesizeEvent(IncSet* this, int x) {
   if (this->active) return FunctionBar_synthesizeEvent(this->active->bar, x);
   return FunctionBar_synthesizeEvent(this->defaultBar, x);
}

/* ================= ScreenManager ================= */
static void Panel_freeFn(void* p) { Panel_delete((Panel*)p); }

ScreenManager* ScreenManager_new(Header* header, Machine* host, State* state, bool owner) {
   ScreenManager* this = xcalloc(1, sizeof(ScreenManager));
   this->x1 = 0; this->y1 = 0; this->x2 = 0; this->y2 = -1;
   this->panels = Vector_new(owner ? Panel_freeFn : NULL);
   this->panelCount = 0;
   this->header = header;
   this->host = host;
   this->state = state;
   this->owner = owner;
   this->allowFocusChange = true;
   return this;
}

void ScreenManager_delete(ScreenManager* this) { if (!this) return; Vector_delete(this->panels); free(this); }

static int* panelSizes = NULL; static int panelSizesCap = 0;

void ScreenManager_add(ScreenManager* this, Panel* item, int size) {
   int n = this->panelCount;
   if (n + 1 > panelSizesCap) { panelSizesCap = n + 8; panelSizes = xrealloc(panelSizes, panelSizesCap * sizeof(int)); }
   panelSizes[n] = size;
   Vector_add(this->panels, item);
   this->panelCount++;
   item->needsRedraw = true;
}

Panel* ScreenManager_remove(ScreenManager* this, int idx) {
   Panel* p = Vector_remove(this->panels, idx);
   for (int i = idx; i < this->panelCount - 1; i++) panelSizes[i] = panelSizes[i + 1];
   this->panelCount--;
   return p;
}

static int ScreenManager_headerHeight(const ScreenManager* this) {
   if (!this->header || this->state->hideMeters) return 0;
   int h = this->header->height;
   if (this->state->settings->screenTabs) h += 1;
   return h;
}

void ScreenManager_resize(ScreenManager* this) {
   int y1 = ScreenManager_headerHeight(this);
   int y2 = LINES - 1 - (this->state->settings->hideFunctionBar == 2 ? 0 : 1) + 1;
   /* panel height (rows available) = y2 - y1 ; function bar at LINES-1 */
   int lastX = this->x1;
   int height = LINES - y1 - 1; /* excluding function bar line */
   if (this->state->settings->hideFunctionBar == 2) height = LINES - y1;
   for (int i = 0; i < this->panelCount; i++) {
      Panel* panel = Vector_get(this->panels, i);
      int size = panelSizes[i];
      int w = size > 0 ? size : COLS - lastX;
      if (w < 0) w = 0;
      Panel_resize(panel, w, height - (RichString_sizeVal(panel->header) > 0 ? 1 : 0));
      Panel_move(panel, lastX, y1);
      lastX += w + 1;
   }
   (void)y2;
}

static void ScreenManager_drawScreenTabs(ScreenManager* this) {
   Settings* settings = this->state->settings;
   int y = this->header ? this->header->height : 0;
   int x = 2;
   attrset(CRT_colors[RESET_COLOR]);
   mvhline(y, 0, ' ', COLS);
   for (unsigned int s = 0; s < settings->nScreens; s++) {
      bool current = (settings->ss == settings->screens[s]);
      const char* name = settings->screens[s]->heading;
      attrset(CRT_colors[current ? SCREENS_CUR_BORDER : SCREENS_OTH_BORDER]);
      mvaddch(y, x, '[');
      x++;
      attrset(CRT_colors[current ? SCREENS_CUR_TEXT : SCREENS_OTH_TEXT]);
      mvaddstr(y, x, name);
      x += strlen(name);
      attrset(CRT_colors[current ? SCREENS_CUR_BORDER : SCREENS_OTH_BORDER]);
      mvaddch(y, x, ']');
      x += 2;
   }
   attrset(CRT_colors[RESET_COLOR]);
}

void ScreenManager_drawPanels(ScreenManager* this, int focus, bool force_redraw) {
   const int nPanels = this->panelCount;
   if (this->header && !this->state->hideMeters && this->state->settings->screenTabs) ScreenManager_drawScreenTabs(this);
   for (int i = 0; i < nPanels; i++) {
      Panel* panel = Vector_get(this->panels, i);
      Panel_draw(panel, force_redraw, i == focus, !(panel->state && this->state->hideSelection && i == focus && false), this->state->settings->hideFunctionBar == 2);
      mvvline(panel->y, panel->x + panel->w, ' ', panel->h + 1);
   }
   Panel* focused = Vector_get(this->panels, focus);
   if (this->state->settings->hideFunctionBar != 2) {
      if (focused->drawFunctionBar) focused->drawFunctionBar(focused, false);
      else if (focused->currentBar) FunctionBar_draw(focused->currentBar);
   }
}

void ScreenManager_setFunctionBar(ScreenManager* this, const FunctionBar* bar) { (void)this; (void)bar; }

static void checkRecalculation(ScreenManager* this, double* oldTime, int* sortTimeout, bool* redraw, bool* rescan, bool* timedOut, bool* force_redraw) {
   Machine* host = this->host;
   Settings* settings = this->state->settings;
   struct timeval tv; gettimeofday(&tv, NULL);
   double newTime = ((double)tv.tv_sec * 10) + ((double)tv.tv_usec / 100000);
   *timedOut = (newTime - *oldTime > settings->delay);
   *rescan |= *timedOut;
   if (newTime < *oldTime) *rescan = true;
   if (*rescan) {
      *oldTime = newTime;
      int oldUidDigits = host->uidDigits;
      int oldPidDigits = host->pidDigits;
      if (!this->state->pauseUpdate && (*sortTimeout == 0 || settings->ss->treeView)) {
         this->state->pt->needsSort = true;
         *sortTimeout = 1;
      }
      if (!this->state->pauseUpdate) {
         Machine_scan(host);
         ProcessTable_scan(this->state->pt, false);
         if (host->iterationsRemaining != (unsigned int)-1 && host->iterationsRemaining > 0) host->iterationsRemaining--;
      }
      if (this->state->pt->needsSort || !this->state->pauseUpdate) {
         extern void MainPanel_rebuild(struct MainPanel_* mp);
         MainPanel_rebuild(this->state->mainPanel);
      }
      if (oldUidDigits != host->uidDigits || oldPidDigits != host->pidDigits) *force_redraw = true;
      Header_updateData(this->header);
      *redraw = true;
      *rescan = false;
   }
   if (*redraw && this->header && !this->state->hideMeters) Header_draw(this->header);
}

extern HandlerResult MainPanel_handleMouse(ScreenManager* this, MEVENT* mevent, int* ch, int focus);

void ScreenManager_run(ScreenManager* this, Panel** lastFocus, int* lastKey, const char* name) {
   (void)name;
   bool quit = false;
   int focus = 0;
   Panel* panelFocus = Vector_get(this->panels, focus);
   double oldTime = 0.0;
   int sortTimeout = 0;
   int resetSortTimeout = 5;
   bool redraw = true;
   bool force_redraw = true;
   bool rescan = false;
   bool timedOut = true;
   int ch = ERR;
   int closeTimeout = 0;
   ScreenManager_resize(this);
   while (!quit) {
      if (this->header) checkRecalculation(this, &oldTime, &sortTimeout, &redraw, &rescan, &timedOut, &force_redraw);
      if (this->host->iterationsRemaining == 0) { quit = true; break; }
      if (redraw || force_redraw) {
         ScreenManager_drawPanels(this, focus, force_redraw);
         force_redraw = false;
      }
      int prevCh = ch;
      set_escdelay(25);
      ch = getch();
      HandlerResult result = IGNORED;
      if (ch == KEY_MOUSE && this->state->settings->enableMouse) {
         MEVENT mevent;
         if (getmouse(&mevent) == OK) {
            if (mevent.bstate & BUTTON1_RELEASED) {
               if (mevent.y == LINES - 1 && this->state->settings->hideFunctionBar != 2) {
                  if (panelFocus->currentBar) ch = FunctionBar_synthesizeEvent(panelFocus->currentBar, mevent.x);
                  if (panelFocus->drawFunctionBar) { extern int MainPanel_synthesizeEvent(Panel*, int); ch = MainPanel_synthesizeEvent(panelFocus, mevent.x); }
               } else {
                  bool handled = false;
                  for (int i = 0; i < this->panelCount; i++) {
                     Panel* panel = Vector_get(this->panels, i);
                     int headerRows = RichString_sizeVal(panel->header) > 0 ? 1 : 0;
                     if (mevent.x >= panel->x && mevent.x <= panel->x + panel->w) {
                        if (mevent.y == panel->y && headerRows) {
                           ch = KEY_RECLICK; /* header click */
                           if (this->allowFocusChange) { focus = i; panelFocus = panel; }
                           break;
                        }
                        if (mevent.y >= panel->y + headerRows && mevent.y < panel->y + headerRows + panel->h) {
                           if (this->allowFocusChange) { focus = i; panelFocus = panel; }
                           int newSel = mevent.y - panel->y - headerRows + panel->scrollV;
                           if (newSel < Panel_size(panel)) {
                              if (panel->selected == newSel) ch = KEY_RECLICK;
                              else { Panel_setSelected(panel, newSel); ch = 0; }
                           } else ch = 0;
                           handled = true;
                           break;
                        }
                     }
                  }
                  if (!handled && ch == KEY_MOUSE) {
                     /* screen tabs */
                     int tabsY = this->header ? this->header->height : -1;
                     if (this->header && !this->state->hideMeters && this->state->settings->screenTabs && mevent.y == tabsY) {
                        Settings* settings = this->state->settings;
                        int x = 2;
                        for (unsigned int s = 0; s < settings->nScreens; s++) {
                           int len = strlen(settings->screens[s]->heading) + 2;
                           if (mevent.x >= x && mevent.x < x + len) {
                              settings->ssIndex = s; settings->ss = settings->screens[s];
                              extern void MainPanel_screenChanged(State*);
                              MainPanel_screenChanged(this->state);
                              force_redraw = true; rescan = true;
                              break;
                           }
                           x += len + 1;
                        }
                        ch = 0;
                     } else ch = 0;
                  }
               }
            } else if (mevent.bstate & BUTTON4_PRESSED) {
               ch = KEY_WHEELUP;
            } else if (mevent.bstate & BUTTON5_PRESSED) {
               ch = KEY_WHEELDOWN;
            } else ch = 0;
         } else ch = 0;
      }
      if (ch == ERR) {
         if (!timedOut) sortTimeout--;
         if (prevCh == ch && !timedOut) {
            closeTimeout++;
            if (closeTimeout == 100) break;
         } else closeTimeout = 0;
         redraw = false;
         continue;
      }
      if (ch == 0) { redraw = true; continue; }
      redraw = true;
      switch (ch) {
         case KEY_ALT('H'): ch = KEY_LEFT; break;
         case KEY_ALT('J'): ch = KEY_DOWN; break;
         case KEY_ALT('K'): ch = KEY_UP; break;
         case KEY_ALT('L'): ch = KEY_RIGHT; break;
      }
      result = panelFocus->eventHandler ? panelFocus->eventHandler(panelFocus, ch) : IGNORED;
      if (result & SYNTH_KEY) ch = result >> 16;
      if (result & REFRESH) sortTimeout = 0;
      if (result & REDRAW) force_redraw = true;
      if (result & RESIZE) { ScreenManager_resize(this); force_redraw = true; }
      if (result & RESCAN) { rescan = true; sortTimeout = 0; }
      if (result & HANDLED) continue;
      else if (result & BREAK_LOOP) { quit = true; continue; }
      switch (ch) {
      case KEY_RESIZE:
         ScreenManager_resize(this);
         force_redraw = true;
         continue;
      case KEY_LEFT: case KEY_CTRL('B'):
         if (this->panelCount < 2) goto defaultHandler;
         if (!this->allowFocusChange) break;
tryLeft:
         if (focus > 0) focus--;
         panelFocus = Vector_get(this->panels, focus);
         if (Panel_size(panelFocus) == 0 && focus > 0) goto tryLeft;
         break;
      case KEY_RIGHT: case KEY_CTRL('F'): case 9:
         if (this->panelCount < 2) goto defaultHandler;
         if (!this->allowFocusChange) break;
tryRight:
         if (focus < this->panelCount - 1) focus++;
         panelFocus = Vector_get(this->panels, focus);
         if (Panel_size(panelFocus) == 0 && focus < this->panelCount - 1) goto tryRight;
         break;
      case KEY_F(10): case 'q': case 27:
         quit = true;
         continue;
      default:
defaultHandler:
         sortTimeout = resetSortTimeout;
         Panel_onKey(panelFocus, ch);
         break;
      }
   }
   if (lastFocus) *lastFocus = panelFocus;
   if (lastKey) *lastKey = ch;
}
