   char path[64]; xsnprintf(path, sizeof(path), "/proc/%d/autogroup", (int)p->pid);
   FILE* f = fopen(path, "r+");
   if (!f) return false;
   long id; int nice;
   if (fscanf(f, "/autogroup-%ld nice %d", &id, &nice) != 2) { fclose(f); return false; }
   nice = CLAMP(nice + delta, -20, 19);
   rewind(f);
   fprintf(f, "%d", nice);
   fclose(f);
