static HandlerResult actionStrace(State* st) { if (Settings_isReadonly()) return HANDLED; Process* p = MainPanel_getSelected(st->mainPanel); if (!p) return HANDLED; InfoScreen_run(st, p, 3); return HANDLED | REDRAW | RESCAN | RESIZE; }
