cat > mainpanel.c <<'EOF'
#include "mainpanel.h"
#include "crt.h"
#include "mainpanel.h"
#include <math.h>
#include <unistd.h>
#include <signal.h>
#include <sched.h>
#include <sys/syscall.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <errno.h>

extern void InfoScreen_run(State* st, Process* p, int kind);

static const char* const MainFunctions[] = { "Help  ", "Setup ", "Search", "Filter", "Tree  ", "SortBy", "Nice -", "Nice +", "Kill  ", "Quit  ", NULL };
static const char* const MainFunctions_ro[] = { "Help  ", "Setup ", "Search", "Filter", "Tree  ", "SortBy", "      ", "      ", "      ", "Quit  ", NULL };

static void Process_displayItem(const void* item, RichString* out) {
   Process_display((const Process*)item, out);
}

Process* MainPanel_getSelected(MainPanel* this) { return (Process*)Panel_getSelected(&this->super); }

static const char* MainPanel_getValue(Panel* panel, int i) {
   Process* p = Panel_get(panel, i);
   return p ? Process_getCommand(p) : "";
}

void MainPanel_setFilter(MainPanel* this, const char* filter) {
   IncSet_setFilter(this->inc, filter);
   this->state->pt->incFilter = IncSet_getFilter(this->inc);
}

static void MainPanel_printHeader(MainPanel* this) {
   Settings* settings = this->state->settings;
   const ScreenSettings* ss = settings->ss;
   RichString* header = &this->super.header;
   RichString_prune(header);
   ProcessField key = ScreenSettings_getActiveSortKey(ss);
   for (int i = 0; ss->fields[i]; i++) {
      ProcessField field = ss->fields[i];
      char buf[128];
      const char* title = Process_fieldTitle(field, buf, sizeof(buf));
      int color = (key == field) ? CRT_colors[PANEL_SELECTION_FOCUS] : CRT_colors[PANEL_HEADER_FOCUS];
      RichString_appendAscii(header, color, title);
      if (key == field && RichString_getCharVal(header, RichString_sizeVal(*header) - 1) == ' ') {
         bool ascending = ScreenSettings_getActiveDirection(ss) == 1;
         RichString_rewind(header, 1);
         RichString_appendnAscii(header, color, CRT_treeStr[ascending ? TREE_STR_ASC : TREE_STR_DESC], 1);
      }
      if (field == COMM && settings->showMergedCommand) RichString_appendAscii(header, color, "(merged)");
   }
   this->super.needsRedraw = true;
}

void MainPanel_updateLabels(MainPanel* this) {
   Settings* settings = this->state->settings;
   FunctionBar* bar = this->bar;
   FunctionBar_setLabel(bar, KEY_F(5), settings->ss->treeView ? "List  " : "Tree  ");
   FunctionBar_setLabel(bar, KEY_F(4), IncSet_filterActive(this->inc) ? "FILTER" : "Filter");
}

void MainPanel_rebuild(MainPanel* this) {
   if (!this) return;
   Panel* panel = &this->super;
   State* st = this->state;
   ProcessTable* pt = st->pt;
   pt->incFilter = IncSet_getFilter(this->inc);
   /* remember selected pid */
   Process* sel = Panel_getSelected(panel);
   pid_t selPid = sel ? sel->pid : -1;
   if (this->following && this->followPid > 0) selPid = this->followPid;
   ProcessTable_updateDisplayList(pt);
   int idx = panel->selected;
   Vector_prune(panel->items);
   int found = -1;
   for (int i = 0; i < Vector_size(pt->displayList); i++) {
      Process* p = Vector_get(pt->displayList, i);
      Vector_add(panel->items, p);
      if (p->pid == selPid) found = i;
   }
   if (found >= 0) panel->selected = found;
   else if (this->following) { this->following = false; this->followPid = 0; Panel_setSelected(panel, idx); }
   else Panel_setSelected(panel, idx);
   panel->selectionColorId = this->following ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
   panel->needsRedraw = true;
   MainPanel_printHeader(this);
   MainPanel_updateLabels(this);
}

void MainPanel_screenChanged(State* state) {
   MainPanel* mp = state->mainPanel;
   state->pt->needsSort = true;
   mp->super.scrollH = 0;
   MainPanel_rebuild(mp);
}

bool MainPanel_foreachProcess(MainPanel* this, bool (*fn)(Process*, int), int arg, bool* wasAnyTagged) {
   Panel* panel = &this->super;
   bool ok = true;
   bool anyTagged = false;
   for (int i = 0; i < Panel_size(panel); i++) {
      Process* p = Panel_get(panel, i);
      if (p->tag) { ok = fn(p, arg) && ok; anyTagged = true; }
   }
   if (!anyTagged) {
      Process* p = Panel_getSelected(panel);
      if (p) ok = fn(p, arg) && ok;
   }
   if (wasAnyTagged) *wasAnyTagged = anyTagged;
   return ok;
}

