/* Action_pickFromVector returns HANDLED|REDRAW|... and sets the selected item through the panel */
HandlerResult Action_pickFromVector(State* st, Panel* list, int x, bool followProcess) {
   MainPanel* mainPanel = st->mainPanel;
   Panel* panel = &mainPanel->super;
   Header* header = st->header;
   int y = panel->y;
   ScreenManager* scr = ScreenManager_new(header, st->host, st, false);
   scr->allowFocusChange = false;
   ScreenManager_add(scr, list, x);
   ScreenManager_add(scr, panel, -1);
   Panel* panelFocus;
   int ch;
   bool unfollow = false;
   int pid = followProcess ? (MainPanel_getSelected(mainPanel) ? MainPanel_getSelected(mainPanel)->pid : -1) : -1;
   if (followProcess && !mainPanel->following) { mainPanel->following = true; mainPanel->followPid = pid; unfollow = true; }
   ScreenManager_run(scr, &panelFocus, &ch, NULL);
   if (unfollow) { mainPanel->following = false; mainPanel->followPid = 0; }
   ScreenManager_delete(scr);
   Panel_move(panel, 0, y);
   Panel_resize(panel, COLS, LINES - y - 1);
   if (panelFocus == list && ch == 13) {
      /* selection made */
      return HANDLED | REDRAW | RESCAN | 0x100;
   }
   return HANDLED | REDRAW | RESCAN;
}

