static HandlerResult actionToggleAllBranches(State* st) {
   if (!st->settings->ss->treeView) return HANDLED;
   /* toggle: if any root has showChildren → collapse all; else expand */
   ProcessTable* pt = st->pt;
   bool anyExpanded = false;
   for (int i = 0; i < Vector_size(pt->processes); i++) {
      Process* p = Vector_get(pt->processes, i);
      pid_t parent = p->isUserlandThread ? p->tgid : p->ppid;
      bool isRoot = (parent == p->pid || parent <= 0 || !ProcessTable_findProcess(pt, parent));
      if (isRoot && p->showChildren) { anyExpanded = true; break; }
   }
   for (int i = 0; i < Vector_size(pt->processes); i++) {
      Process* p = Vector_get(pt->processes, i);
      pid_t parent = p->isUserlandThread ? p->tgid : p->ppid;
      bool isRoot = (parent == p->pid || parent <= 0 || !ProcessTable_findProcess(pt, parent));
      if (isRoot) p->showChildren = !anyExpanded;
   }
   pt->needsSort = true;
   return HANDLED | REDRAW | RESCAN;
}

