static HandlerResult actionKill(State* st) {
   if (Settings_isReadonly()) return HANDLED;
   static const struct { int number; const char* name; } signals[] = {
      {0, "Cancel"}, {1, "SIGHUP"}, {2, "SIGINT"}, {3, "SIGQUIT"}, {4, "SIGILL"}, {5, "SIGTRAP"}, {6, "SIGABRT"}, {6, "SIGIOT"}, {7, "SIGBUS"}, {8, "SIGFPE"},
      {9, "SIGKILL"}, {10, "SIGUSR1"}, {11, "SIGSEGV"}, {12, "SIGUSR2"}, {13, "SIGPIPE"}, {14, "SIGALRM"}, {15, "SIGTERM"}, {16, "SIGSTKFLT"}, {17, "SIGCHLD"},
      {18, "SIGCONT"}, {19, "SIGSTOP"}, {20, "SIGTSTP"}, {21, "SIGTTIN"}, {22, "SIGTTOU"}, {23, "SIGURG"}, {24, "SIGXCPU"}, {25, "SIGXFSZ"}, {26, "SIGVTALRM"},
      {27, "SIGPROF"}, {28, "SIGWINCH"}, {29, "SIGIO"}, {29, "SIGPOLL"}, {30, "SIGPWR"}, {31, "SIGSYS"},
   };
   Panel* signalsPanel = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_newEnterEsc("Send   ", "Cancel "));
   Panel_setHeader(signalsPanel, "Send signal:");
   int defaultIdx = 0;
   int idx = 0;
   for (size_t i = 0; i < ARRAYSIZE(signals); i++) {
      char buf[32]; xsnprintf(buf, sizeof(buf), "%2d %s", signals[i].number, signals[i].name);
      Panel_add(signalsPanel, ListItem_new(buf, signals[i].number));
      if (signals[i].number == 15) defaultIdx = idx;
      idx++;
   }
   for (int i = SIGRTMIN; i <= SIGRTMAX; i++) {
      char buf[32];
      if (i == SIGRTMIN) xsnprintf(buf, sizeof(buf), "%2d SIGRTMIN", i);
      else xsnprintf(buf, sizeof(buf), "%2d SIGRTMIN+%d", i, i - SIGRTMIN);
      Panel_add(signalsPanel, ListItem_new(buf, i));
   }
   Panel_setSelected(signalsPanel, defaultIdx);
   HandlerResult r = Action_pickFromVector(st, signalsPanel, 14, true);
   if (r & 0x100) {
      ListItem* sgn = Panel_getSelected(signalsPanel);
      if (sgn && sgn->key != 0) {
         Panel* panel = &((MainPanel*)st->mainPanel)->super;
         bool anyTagged = false;
         for (int i = 0; i < Panel_size(panel); i++) { Process* p = Panel_get(panel, i); if (p->tag) { Process_sendSignal(p, sgn->key); anyTagged = true; } }
         if (!anyTagged) { Process* p = Panel_getSelected(panel); if (p) Process_sendSignal(p, sgn->key); }
         napms(500);
      }
   }
   Panel_delete(signalsPanel);
   return HANDLED | REDRAW | RESCAN;
}

