/* affinity */
static HandlerResult actionSetAffinity(State* st) {
   if (Settings_isReadonly()) return HANDLED;
   Machine* host = st->host;
   if (host->existingCPUs == 1) return HANDLED;
   Process* p = MainPanel_getSelected(st->mainPanel);
   if (!p) return HANDLED;
   cpu_set_t set;
   CPU_ZERO(&set);
   bool haveSet = sched_getaffinity(p->pid, sizeof(set), &set) == 0;
   Panel* affinityPanel = Panel_new(0, 0, 0, 0, CheckItem_display, CheckItem_delete, true, FunctionBar_newEnterEsc("Set    ", "Cancel "));
   Panel_setHeader(affinityPanel, "Use CPUs:");
   int width = 14;
   for (unsigned int i = 0; i < host->existingCPUs; i++) {
      char buf[32]; xsnprintf(buf, sizeof(buf), "CPU %u", st->settings->countCPUsFromOne ? i + 1 : i);
      Panel_add(affinityPanel, CheckItem_newByVal(buf, haveSet ? CPU_ISSET(i, &set) : true));
   }
   /* custom key handler: space toggles */
   extern HandlerResult AffinityPanel_eventHandler(Panel*, int);
   affinityPanel->eventHandler = AffinityPanel_eventHandler;
   HandlerResult r = Action_pickFromVector(st, affinityPanel, width, true);
   if (r & 0x100) {
      cpu_set_t newset; CPU_ZERO(&newset);
      for (unsigned int i = 0; i < host->existingCPUs; i++) { CheckItem* c = Panel_get(affinityPanel, i); if (c && CheckItem_get(c)) CPU_SET(i, &newset); }
      Panel* panel = &((MainPanel*)st->mainPanel)->super;
      bool anyTagged = false;
      for (int i = 0; i < Panel_size(panel); i++) { Process* q = Panel_get(panel, i); if (q->tag) { sched_setaffinity(q->pid, sizeof(newset), &newset); anyTagged = true; } }
      if (!anyTagged) sched_setaffinity(p->pid, sizeof(newset), &newset);
   }
   Panel_delete(affinityPanel);
   return HANDLED | REDRAW | RESCAN;
}

HandlerResult AffinityPanel_eventHandler(Panel* this, int ch) {
   CheckItem* selected = Panel_getSelected(this);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER:
      return BREAK_LOOP | SYNTH_KEY | (13 << 16);
   case ' ':
      if (selected) CheckItem_set(selected, !CheckItem_get(selected));
      this->needsRedraw = true;
      return HANDLED;
   default:
      return IGNORED;
   }
}

/* io priority */
#define IOPRIO_CLASS_SHIFT 13
#define IOPRIO_PRIO_VALUE(c, d) (((c) << IOPRIO_CLASS_SHIFT) | (d))
static HandlerResult actionSetIOPriority(State* st) {
   if (Settings_isReadonly()) return HANDLED;
   Process* p = MainPanel_getSelected(st->mainPanel);
   if (!p) return HANDLED;
   int current = syscall(SYS_ioprio_get, 1, p->pid);
   Panel* ioprioPanel = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_newEnterEsc("Set    ", "Cancel "));
   Panel_setHeader(ioprioPanel, "IO Priority:");
   Panel_add(ioprioPanel, ListItem_new("None (based on nice)", IOPRIO_PRIO_VALUE(0, 0)));
   if (current == IOPRIO_PRIO_VALUE(0, 0)) Panel_setSelected(ioprioPanel, 0);
   static const struct { int klass; const char* name; } classes[] = { {1, "Realtime"}, {2, "Best-effort"} };
   for (int c = 0; c < 2; c++) {
      for (int i = 0; i < 8; i++) {
         char buf[64];
         const char* suffix = i == 0 ? " (High)" : (i == 7 ? " (Low)" : "");
         xsnprintf(buf, sizeof(buf), "%s %d%s", classes[c].name, i, suffix);
         int ioprio = IOPRIO_PRIO_VALUE(classes[c].klass, i);
         Panel_add(ioprioPanel, ListItem_new(buf, ioprio));
         if (current == ioprio) Panel_setSelected(ioprioPanel, Panel_size(ioprioPanel) - 1);
      }
   }
   Panel_add(ioprioPanel, ListItem_new("Idle", IOPRIO_PRIO_VALUE(3, 7)));
   if (current == IOPRIO_PRIO_VALUE(3, 7)) Panel_setSelected(ioprioPanel, Panel_size(ioprioPanel) - 1);
   HandlerResult r = Action_pickFromVector(st, ioprioPanel, 20, true);
   if (r & 0x100) {
      ListItem* item = Panel_getSelected(ioprioPanel);
      if (item) {
         Panel* panel = &((MainPanel*)st->mainPanel)->super;
         bool anyTagged = false;
         for (int i = 0; i < Panel_size(panel); i++) { Process* q = Panel_get(panel, i); if (q->tag) { syscall(SYS_ioprio_set, 1, q->pid, item->key); anyTagged = true; } }
         if (!anyTagged) syscall(SYS_ioprio_set, 1, p->pid, item->key);
      }
   }
   Panel_delete(ioprioPanel);
   return HANDLED | REDRAW | RESCAN;
}

/* scheduler policy */
static bool resetOnFork = false;
HandlerResult SchedPanel_eventHandler(Panel* this, int ch) {
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: {
      if (Panel_getSelectedIndex(this) == 0) {
         resetOnFork = !resetOnFork;
         ListItem* it = Panel_get(this, 0);
         free(it->value); it->value = xstrdup(resetOnFork ? "Reset on fork: on" : "Reset on fork: off");
         this->needsRedraw = true;
         return HANDLED;
      }
      return BREAK_LOOP | SYNTH_KEY | (13 << 16);
   }
   default: return IGNORED;
   }
}
static HandlerResult actionSetSchedPolicy(State* st) {
   if (Settings_isReadonly()) return HANDLED;
   Process* p = MainPanel_getSelected(st->mainPanel);
   if (!p) return HANDLED;
   Panel* schedPanel = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
   Panel_setHeader(schedPanel, "New policy:");
   Panel_add(schedPanel, ListItem_new(resetOnFork ? "Reset on fork: on" : "Reset on fork: off", -1));
   static const struct { const char* name; int policy; } policies[] = { {"Other", SCHED_OTHER}, {"FiFo", SCHED_FIFO}, {"RoundRobin", SCHED_RR}, {"Batch", SCHED_BATCH}, {"Idle", SCHED_IDLE} };
   int cur = sched_getscheduler(p->pid);
   if (cur >= 0) cur &= ~0x40000000;
   for (size_t i = 0; i < ARRAYSIZE(policies); i++) {
      Panel_add(schedPanel, ListItem_new(policies[i].name, policies[i].policy));
      if (policies[i].policy == cur) Panel_setSelected(schedPanel, i + 1);
   }
   schedPanel->eventHandler = SchedPanel_eventHandler;
   HandlerResult r = Action_pickFromVector(st, schedPanel, 18, true);
   if (r & 0x100) {
      ListItem* item = Panel_getSelected(schedPanel);
      if (item && item->key >= 0) {
         struct sched_param param; memset(&param, 0, sizeof(param));
         int policy = item->key | (resetOnFork ? 0x40000000 : 0);
         if (item->key == SCHED_FIFO || item->key == SCHED_RR) param.sched_priority = 1;
         Panel* panel = &((MainPanel*)st->mainPanel)->super;
         bool anyTagged = false;
         for (int i = 0; i < Panel_size(panel); i++) { Process* q = Panel_get(panel, i); if (q->tag) { sched_setscheduler(q->pid, policy, &param); anyTagged = true; } }
         if (!anyTagged) sched_setscheduler(p->pid, policy, &param);
      }
   }
   Panel_delete(schedPanel);
   return HANDLED | REDRAW | RESCAN;
}

