   if (done) return;
   done = true;
   keys['M'] = actionSortByMemory;
   keys['T'] = actionSortByTime;
   keys['P'] = actionSortByCPU;
   keys['H'] = actionToggleUserlandThreads;
   keys['K'] = actionToggleKernelThreads;
   keys['O'] = actionToggleRunningInContainer;
   keys['p'] = actionToggleProgramPath;
   keys['m'] = actionToggleMergedCommand;
   keys['Z'] = actionTogglePauseUpdate;
   keys['t'] = actionToggleTreeView;
   keys[KEY_F(5)] = actionToggleTreeView;
   keys[KEY_F(4)] = actionIncFilter;
   keys['\\'] = actionIncFilter;
   keys[KEY_F(3)] = actionIncSearch;
   keys['/'] = actionIncSearch;
   keys['n'] = actionIncSearch; /* placeholder, replaced below */
   keys['n'] = NULL;
   keys[']'] = actionHigherPriority;
   keys[KEY_F(7)] = actionHigherPriority;
   keys['['] = actionLowerPriority;
   keys[KEY_F(8)] = actionLowerPriority;
   keys['}'] = actionHigherAutogroupPriority;
   keys[KEY_F(19)] = actionHigherAutogroupPriority;
   keys['{'] = actionLowerAutogroupPriority;
   keys[KEY_F(20)] = actionLowerAutogroupPriority;
   keys['I'] = actionInvertSortOrder;
   keys[KEY_F(6)] = actionExpandCollapseOrSortColumn;
   keys['>'] = actionSetSortColumn;
   keys['<'] = actionSetSortColumn;
   keys['.'] = actionSetSortColumn;
   keys[','] = actionSetSortColumn;
   keys[KEY_F(10)] = actionQuit;
   keys['q'] = actionQuit;
   keys['a'] = actionSetAffinity;
   keys[KEY_F(9)] = actionKill;
   keys['k'] = actionKill;
   keys[KEY_RECLICK] = actionExpandOrCollapse;
   keys['+'] = actionExpandOrCollapse;
   keys['='] = actionExpandOrCollapse;
   keys['-'] = actionExpandOrCollapse;
   keys['*'] = actionToggleAllBranches;
   keys['\177'] = actionCollapseIntoParent;
   keys[KEY_F(1)] = actionHelp;
   keys['h'] = actionHelp;
   keys['?'] = actionHelp;
   keys['U'] = actionUntagAll;
   keys['c'] = actionTagAllChildren;
   keys['e'] = actionEnvScreen;
   keys['w'] = actionCommandScreen;
   keys['u'] = actionFilterByUser;
   keys['F'] = actionFollow;
   keys['S'] = actionSetup;
   keys['C'] = actionSetup;
   keys[KEY_F(2)] = actionSetup;
   keys['x'] = actionLocks;
   keys['l'] = actionLsof;
   keys['s'] = actionStrace;
   keys[' '] = actionTag;
   keys['\014'] = actionRedraw;
   keys[KEY_F(18)] = actionNextScreen; /* unused */
   keys['\t'] = actionNextScreen;
   keys[KEY_SHIFT_TAB] = actionPrevScreen;
   keys['#'] = actionToggleMeters;
   keys['i'] = actionSetIOPriority;
   keys['Y'] = actionSetSchedPolicy;
   keys[KEY_F(18)] = NULL;
