/* ---------------- MainPanel ---------------- */

static HandlerResult MainPanel_eventHandler(Panel* super, int ch) {
   MainPanel* this = (MainPanel*)super;
   State* st = this->state;
   HandlerResult result = IGNORED;
   Process* p = MainPanel_getSelected(this);
   if (IncSet_isActive(this->inc)) {
      if (ch == 27 || ch == 13 || ch == KEY_ENTER || ch == KEY_F(3) || ch == KEY_F(15) || ch == KEY_BACKSPACE || ch == 127 || (ch > 0 && ch < 255 && isprint(ch)) || ch == KEY_RESIZE) {
         bool wasFilter = this->inc->active && this->inc->active->isFilter;
         IncSet_handleKey(this->inc, ch, super, MainPanel_getValue, NULL);
         if (wasFilter) {
            st->pt->incFilter = IncSet_getFilter(this->inc);
            st->pt->needsSort = true;
            MainPanel_rebuild(this);
         }
         MainPanel_updateLabels(this);
         if (ch == KEY_RESIZE) return IGNORED;
         return HANDLED | REDRAW;
      }
      /* movement keys etc. fall through but keep inc active */
      if (ch == KEY_UP || ch == KEY_DOWN || ch == KEY_PPAGE || ch == KEY_NPAGE || ch == KEY_HOME || ch == KEY_END || ch == KEY_LEFT || ch == KEY_RIGHT || ch == KEY_WHEELUP || ch == KEY_WHEELDOWN) {
         Panel_onKey(super, ch);
         this->following = false; this->followPid = 0; super->selectionColorId = PANEL_SELECTION_FOCUS;
         return HANDLED | REDRAW;
      }
      /* other keys: deactivate inc then process normally */
      IncSet_handleKey(this->inc, 27, super, MainPanel_getValue, NULL);
      if (this->inc->filtering == false) { st->pt->incFilter = NULL; }
      MainPanel_updateLabels(this);
   }
   if (ch == 27) return HANDLED;
   if (ch == KEY_RESIZE) return IGNORED;
   /* movement keys: reset follow */
   if (ch == KEY_UP || ch == KEY_DOWN || ch == KEY_PPAGE || ch == KEY_NPAGE || ch == KEY_HOME || ch == KEY_END || ch == KEY_WHEELUP || ch == KEY_WHEELDOWN) {
      this->following = false; this->followPid = 0; super->selectionColorId = PANEL_SELECTION_FOCUS;
      Panel_onKey(super, ch);
      this->pidSearch[0] = 0;
      return HANDLED | REDRAW;
   }
   if (ch == KEY_LEFT || ch == KEY_RIGHT || ch == KEY_CTRL('A') || ch == KEY_CTRL('E') || ch == '^' || ch == '$') {
      Panel_onKey(super, ch);
      return HANDLED | REDRAW;
   }
   if (ch >= '0' && ch <= '9') {
      /* PID search */
      size_t len = strlen(this->pidSearch);
      if (len < sizeof(this->pidSearch) - 1) { this->pidSearch[len] = ch; this->pidSearch[len + 1] = 0; }
      pid_t pid = (pid_t)atol(this->pidSearch);
      for (int i = 0; i < Panel_size(super); i++) {
         Process* q = Panel_get(super, i);
         char buf[20]; xsnprintf(buf, sizeof(buf), "%d", (int)q->pid);
         if (strncmp(buf, this->pidSearch, strlen(this->pidSearch)) == 0) { Panel_setSelected(super, i); break; }
      }
      (void)pid;
      return HANDLED | REDRAW;
   }
   this->pidSearch[0] = 0;
   setBindings();
   if (ch >= 0 && ch <= KEY_MAX && keys[ch]) {
      if (Settings_isReadonly()) {
         if (keys[ch] == actionKill || keys[ch] == actionHigherPriority || keys[ch] == actionLowerPriority || keys[ch] == actionSetAffinity || keys[ch] == actionSetIOPriority || keys[ch] == actionSetSchedPolicy || keys[ch] == actionStrace || keys[ch] == actionHigherAutogroupPriority || keys[ch] == actionLowerAutogroupPriority)
            return HANDLED;
      }
      result = keys[ch](st);
      if (result & RESCAN) st->pt->needsSort = true;
      if (!(result & RESCAN) && (result & REDRAW)) {}
      if (result & (RESCAN | REDRAW)) MainPanel_rebuild(this);
      return result;
   }
   if (ch > 0 && ch < 255 && isprint(ch) && !isdigit(ch)) {
      /* start incremental search with this char */
      IncSet_reset(this->inc, INC_SEARCH);
      IncSet_activate(this->inc, INC_SEARCH, super);
      IncSet_handleKey(this->inc, ch, super, MainPanel_getValue, NULL);
      return HANDLED | REDRAW;
   }
   (void)p;
   return IGNORED;
}

static void MainPanel_drawFunctionBar(Panel* super, bool hideFunctionBar) {
   MainPanel* this = (MainPanel*)super;
   (void)hideFunctionBar;
   IncSet_drawBar(this->inc, CRT_colors[FUNCTION_BAR]);
   if (this->state->pauseUpdate && !IncSet_isActive(this->inc)) {
      /* append PAUSED */
      int x = 0;
      for (int i = 0; i < this->bar->size; i++) x += strlen(this->bar->keys[i]) + strlen(this->bar->functions[i]);
      attrset(CRT_colors[PAUSED]);
      mvaddstr(LINES - 1, x + 1, "PAUSED");
      attrset(CRT_colors[RESET_COLOR]);
   }
}

void MainPanel_setPaused(MainPanel* this, bool paused) { (void)this; (void)paused; }

int MainPanel_synthesizeEvent(Panel* super, int x) {
   MainPanel* this = (MainPanel*)super;
   return IncSet_synthesizeEvent(this->inc, x);
}

MainPanel* MainPanel_new(State* state) {
   MainPanel* this = xcalloc(1, sizeof(MainPanel));
   Panel* super = &this->super;
   FunctionBar* bar = FunctionBar_new(Settings_isReadonly() ? MainFunctions_ro : MainFunctions, NULL, NULL);
   Panel* tmp = Panel_new(0, 0, 0, 0, Process_displayItem, NULL, false, bar);
   memcpy(super, tmp, sizeof(Panel));
   free(tmp);
   this->bar = bar;
   this->state = state;
   this->inc = IncSet_new(bar);
   super->eventHandler = MainPanel_eventHandler;
   super->drawFunctionBar = MainPanel_drawFunctionBar;
   super->state = state;
   state->mainPanel = this;
   state->panel = super;
   return this;
}

void MainPanel_delete(MainPanel* this) {
   if (!this) return;
   IncSet_delete(this->inc);
   Vector_delete(this->super.items);
   RichString_delete(&this->super.header);
   FunctionBar_delete(this->bar);
   free(this);
}
EOF
