            xsnprintf(entry, sizeof(entry), "%5.5s %-7.7s %-4.4s %-10.10s %10.10s %10.10s %10.10s  %s", fd, type, mode, device, size, offset, node, line + 1);
            InfoScreen_addLine(this, entry);
            count++;
            break;
         }
         default: break;
      }
   }
   int rc = pclose(f);
   if (!any || (WIFEXITED(rc) && WEXITSTATUS(rc) == 127)) {
      Panel_prune(this->display); Vector_prune(this->lines);
      InfoScreen_addLine(this, "Could not execute 'lsof'. Please make sure it is available in your $PATH.");
   } else if (count == 0) {
      InfoScreen_addLine(this, "No open files.");
   }
}

static void scanLocks(InfoScreen* this) {
   char path[64]; xsnprintf(path, sizeof(path), "/proc/%d/fdinfo", (int)this->process->pid);
   DIR* d = opendir(path);
   int count = 0;
   if (d) {
      struct dirent* e;
      while ((e = readdir(d))) {
         if (e->d_name[0] == '.') continue;
         char fp[128]; xsnprintf(fp, sizeof(fp), "%s/%s", path, e->d_name);
         FILE* f = fopen(fp, "r");
         if (!f) continue;
         char line[512];
         while (fgets(line, sizeof(line), f)) {
            if (strncmp(line, "lock:", 5) != 0) continue;
            int id; char locktype[16], exclusive[16], readwrite[16]; int pid; unsigned int devmaj, devmin; unsigned long long inode, start, end; char endstr[32];
            int n = sscanf(line + 5, "%d: %15s %15s %15s %d %x:%x:%llu %llu %31s", &id, locktype, exclusive, readwrite, &pid, &devmaj, &devmin, &inode, &start, endstr);
            if (n < 10) continue;
            bool eof = strcmp(endstr, "EOF") == 0;
            end = eof ? 0 : strtoull(endstr, NULL, 10);
            char target[PATH_MAX] = ""; char fdpath[128];
            xsnprintf(fdpath, sizeof(fdpath), "/proc/%d/fd/%s", (int)this->process->pid, e->d_name);
            ssize_t r = readlink(fdpath, target, sizeof(target) - 1); if (r > 0) target[r] = 0; else target[0] = 0;
            char entry[2048];
            if (eof) xsnprintf(entry, sizeof(entry), "%5s %-10s %-10s %-10s %02x:%02x:%20llu %20llu %20s  %s", e->d_name, locktype, exclusive, readwrite, devmaj, devmin, inode, start, "<END OF FILE>", target);
            else xsnprintf(entry, sizeof(entry), "%5s %-10s %-10s %-10s %02x:%02x:%20llu %20llu %20llu  %s", e->d_name, locktype, exclusive, readwrite, devmaj, devmin, inode, start, end, target);
            InfoScreen_addLine(this, entry);
            count++;
         }
         fclose(f);
      }
      closedir(d);
   }
   if (count == 0) InfoScreen_addLine(this, "No locks have been found for the selected process.");
}

static void startStrace(InfoScreen* this) {
   int fdpair[2];
   if (pipe(fdpair) < 0) { InfoScreen_addLine(this, "Could not create pipe."); return; }
   pid_t child = fork();
   if (child < 0) { close(fdpair[0]); close(fdpair[1]); InfoScreen_addLine(this, "Could not fork."); return; }
   if (child == 0) {
      close(fdpair[0]);
      dup2(fdpair[1], STDOUT_FILENO); dup2(fdpair[1], STDERR_FILENO); close(fdpair[1]);
      int ok = fcntl(STDOUT_FILENO, F_SETFL, O_NONBLOCK); (void)ok;
      char buffer[32]; xsnprintf(buffer, sizeof(buffer), "%d", (int)this->process->pid);
      execlp("strace", "strace", "-T", "-tt", "-s", "512", "-p", buffer, NULL);
      const char* message = "Could not execute 'strace'. Please make sure it is available in your $PATH.";
      ssize_t written = write(STDERR_FILENO, message, strlen(message)); (void)written;
      _exit(127);
   }
   close(fdpair[1]);
   this->fd = fdpair[0];
   fcntl(this->fd, F_SETFL, O_NONBLOCK);
   this->childPid = child;
   this->tracing = true;
}

static void readStrace(InfoScreen* this) {
   if (this->fd < 0) return;
   char buffer[1025];
   for (int tries = 0; tries < 50; tries++) {
      struct pollfd pfd = { .fd = this->fd, .events = POLLIN };
      if (poll(&pfd, 1, 0) <= 0) break;
      ssize_t nread = read(this->fd, buffer, sizeof(buffer) - 1);
      if (nread <= 0) { if (nread == 0) { close(this->fd); this->fd = -1; } break; }
      buffer[nread] = 0;
      char* line = buffer;
      for (;;) {
         char* nl = strchr(line, '\n');
         if (nl) *nl = 0;
         if (line[0]) {
            if (this->contLine) InfoScreen_appendLine(this, line); else InfoScreen_addLine(this, line);
         }
         this->contLine = (nl == NULL) && line[0];
         if (!nl) break;
         line = nl + 1;
         this->contLine = false;
      }
      if (this->follow) Panel_setSelected(this->display, Panel_size(this->display) - 1);
   }
}

static void InfoScreen_scan(InfoScreen* this) {
   Panel_prune(this->display);
   Vector_prune(this->lines);
   switch (this->kind) {
      case 0: scanEnv(this); break;
      case 1: scanCommand(this); break;
      case 2: scanLsof(this); break;
      case 3: if (!this->tracing) startStrace(this); break;
      case 4: scanLocks(this); break;
   }
}

static void InfoScreen_refilter(InfoScreen* this) {
   Panel_prune(this->display);
   const char* filter = IncSet_getFilter(this->inc);
   for (int i = 0; i < Vector_size(this->lines); i++) {
      ListItem* l = Vector_get(this->lines, i);
      if (!filter || string_containsI(l->value, filter, true)) Panel_add(this->display, l);
   }
}

static void InfoScreen_draw(InfoScreen* this) {
   attrset(CRT_colors[METER_TEXT]);
   mvhline(0, 0, ' ', COLS);
   mvaddnstr(0, 0, this->title, COLS);
   attrset(CRT_colors[DEFAULT_COLOR]);
   Panel_draw(this->display, true, true, true, false);
   IncSet_drawBar(this->inc, CRT_colors[FUNCTION_BAR]);
}

void InfoScreen_run(State* st, Process* p, int kind) {
   InfoScreen* this = xcalloc(1, sizeof(InfoScreen));
   this->process = p;
   this->kind = kind;
   this->fd = -1;
   this->follow = true;
   this->bar = FunctionBar_new(kind == 3 ? TraceFunctions : InfoScreenFunctions, kind == 3 ? TraceKeys : InfoScreenKeys, kind == 3 ? TraceEvents : InfoScreenEvents);
   this->display = Panel_new(0, 1, COLS, LINES - 2, ListItem_display, NULL, false, this->bar);
   this->inc = IncSet_new(this->bar);
   this->lines = Vector_new(ListItem_delete);
   const char* cmd = Process_getCommand(p);
   switch (kind) {
      case 0: this->title = xasprintf("Environment of process %d - %s", (int)p->pid, cmd); Panel_setHeader(this->display, ""); break;
      case 1: this->title = xasprintf("Command of process %d - %s", (int)p->pid, cmd); Panel_setHeader(this->display, ""); break;
      case 2: this->title = xasprintf("Snapshot of files open in process %d - %s", (int)p->pid, cmd); Panel_setHeader(this->display, "   FD TYPE    MODE DEVICE           SIZE     OFFSET       NODE  NAME"); break;
      case 3: this->title = xasprintf("Trace of process %d - %s", (int)p->pid, cmd); Panel_setHeader(this->display, ""); break;
      case 4: this->title = xasprintf("Snapshot of file locks of process %d - %s", (int)p->pid, cmd); Panel_setHeader(this->display, "   FD TYPE       EXCLUSION  READ/WRITE DEVICE       NODE               START                 END  FILENAME"); break;
   }
   /* header line: keep a visible header row even if empty */
   if (RichString_sizeVal(this->display->header) == 0) { RichString_appendChr(&this->display->header, CRT_colors[PANEL_HEADER_FOCUS], ' ', 1); }
   Panel_resize(this->display, COLS, LINES - 3);
   InfoScreen_scan(this);
   clear();
   InfoScreen_draw(this);
   bool looping = true;
   while (looping) {
      if (kind == 3) readStrace(this);
      Panel_draw(this->display, true, true, true, false);
      IncSet_drawBar(this->inc, CRT_colors[FUNCTION_BAR]);
      if (IncSet_isActive(this->inc)) {
         /* cursor at end of bar text */
      }
      set_escdelay(25);
      int ch = getch();
      if (ch == ERR) continue;
      if (ch == KEY_MOUSE && st->settings->enableMouse) {
         MEVENT mevent;
         if (getmouse(&mevent) == OK) {
            if (mevent.bstate & BUTTON1_RELEASED) {
               if (mevent.y >= this->display->y + 1 && mevent.y < LINES - 1) Panel_setSelected(this->display, mevent.y - this->display->y - 1 + this->display->scrollV), ch = 0;
               else if (mevent.y == LINES - 1) ch = IncSet_synthesizeEvent(this->inc, mevent.x);
               else ch = 0;
            } else if (mevent.bstate & BUTTON4_PRESSED) ch = KEY_WHEELUP;
            else if (mevent.bstate & BUTTON5_PRESSED) ch = KEY_WHEELDOWN;
            else ch = 0;
         } else ch = 0;
      }
      if (ch == 0) continue;
      if (IncSet_isActive(this->inc)) {
         if (ch == KEY_UP || ch == KEY_DOWN || ch == KEY_PPAGE || ch == KEY_NPAGE || ch == KEY_HOME || ch == KEY_END || ch == KEY_WHEELUP || ch == KEY_WHEELDOWN || ch == KEY_LEFT || ch == KEY_RIGHT) {
            Panel_onKey(this->display, ch);
            continue;
         }
         bool wasFilter = this->inc->active->isFilter;
         IncSet_handleKey(this->inc, ch, this->display, InfoScreen_getValue, this->lines);
         if (wasFilter) InfoScreen_refilter(this);
         continue;
      }
      switch (ch) {
         case ERR: continue;
         case KEY_F(3): case '/': IncSet_activate(this->inc, INC_SEARCH, this->display); break;
         case KEY_F(4): case '\\': IncSet_activate(this->inc, INC_FILTER, this->display); break;
         case KEY_F(5): clear(); if (kind != 3) InfoScreen_scan(this); InfoScreen_draw(this); break;
         case KEY_F(8): if (kind == 3) this->follow = !this->follow; break;
         case KEY_F(9): if (kind == 3 && this->tracing && this->childPid > 0) { kill(this->childPid, SIGTERM); this->tracing = false; } break;
         case '\014': clear(); InfoScreen_draw(this); break;
         case KEY_RESIZE: Panel_resize(this->display, COLS, LINES - 3); clear(); InfoScreen_draw(this); break;
         case 27: case 'q': case KEY_F(10): looping = false; break;
         default: Panel_onKey(this->display, ch); break;
      }
   }
   if (this->childPid > 0) { kill(this->childPid, SIGTERM); waitpid(this->childPid, NULL, 0); }
   if (this->fd >= 0) close(this->fd);
   Panel_delete(this->display);
   IncSet_delete(this->inc);
   Vector_delete(this->lines);
   free(this->title);
   free(this);
   clear();
}
