typedef struct MetersPanelData_ { SetupState* ss; int column; bool moving; } MetersPanelData;

static void MetersPanel_fill(Panel* p, SetupState* ss, int column) {
   Panel_prune(p);
   Vector* meters = ss->header->columns[column];
   for (int i = 0; i < Vector_size(meters); i++) {
      MeterItem* mi = xcalloc(1, sizeof(MeterItem));
      mi->meter = Vector_get(meters, i);
      Panel_add(p, mi);
   }
}

static void MetersPanel_setMoving(Panel* p, bool moving) {
   MetersPanelData* d = p->state;
   d->moving = moving;
   MeterItem* mi = Panel_getSelected(p);
   if (mi) mi->moving = moving;
   p->currentBar = moving ? MetersMovingBar : p->defaultBar;
   p->selectionColorId = moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
   p->needsRedraw = true;
}

static HandlerResult MetersPanel_eventHandler(Panel* super, int ch) {
   MetersPanelData* d = super->state;
   SetupState* ss = d->ss;
   Header* header = ss->header;
   Vector* meters = header->columns[d->column];
   int selected = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   bool sideMove = false;
   MeterItem* mi = Panel_getSelected(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK:
      if (!mi) break;
      MetersPanel_setMoving(super, !d->moving);
      result = HANDLED | REDRAW;
      break;
   case ' ': case KEY_F(4): case 't':
      if (!mi) break;
      Meter_setMode(mi->meter, Meter_nextSupportedMode(mi->meter));
      Setup_rebuildHeaderAndRedraw(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_UP:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(7): case '[': case '-':
      if (selected > 0) { Vector_moveUp(meters, selected); Panel_moveSelectedUp(super); }
      result = HANDLED | REDRAW;
      break;
   case KEY_DOWN:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(8): case ']': case '+':
      if (selected + 1 < Vector_size(meters)) { Vector_moveDown(meters, selected); Panel_moveSelectedDown(super); }
      result = HANDLED | REDRAW;
      break;
   case KEY_RIGHT:
      sideMove = true;
      /* fallthrough */
   case KEY_LEFT: {
      if (!d->moving) break;
      int ncols = Header_columns(header);
      int target = d->column + (sideMove ? 1 : -1);
      if (target < 0 || target >= ncols) { result = HANDLED; break; }
      /* move the meter to the target column */
      Meter* m = Vector_remove(meters, selected);
      Vector_add(header->columns[target], m);
      MetersPanel_setMoving(super, false);
      MetersPanel_fill(super, ss, d->column);
      Panel_setSelected(super, selected);
      Panel* tp = ss->columnPanels[target];
      MetersPanel_fill(tp, ss, target);
      Panel_setSelected(tp, Vector_size(header->columns[target]) - 1);
      MetersPanel_setMoving(tp, true);
      Setup_rebuildHeaderAndRedraw(ss);
      /* request focus change */
      result = HANDLED | REDRAW | SYNTH_KEY | ((sideMove ? KEY_RIGHT : KEY_LEFT) << 16);
      /* let ScreenManager move focus: return IGNORED-like with key */
      ss->scr->allowFocusChange = true;
      return REDRAW | SYNTH_KEY | ((sideMove ? KEY_RIGHT : KEY_LEFT) << 16);
   }
   case KEY_DC: case KEY_BACKSPACE: case 127:
      if (!mi) break;
      if (selected < Vector_size(meters)) {
         MetersPanel_setMoving(super, false);
         Meter* m = Vector_remove(meters, selected);
         Meter_delete(m);
         MetersPanel_fill(super, ss, d->column);
         Panel_setSelected(super, selected);
         Setup_rebuildHeaderAndRedraw(ss);
      }
      result = HANDLED | REDRAW;
      break;
   case 27: case KEY_F(10): case 'q':
      if (d->moving) { MetersPanel_setMoving(super, false); return HANDLED | REDRAW; }
      break;
   }
   if (result & HANDLED) {
      Setup_rebuildHeaderAndRedraw(ss);
      super->needsRedraw = true;
   }
   return result;
}

static Panel* MetersPanel_new(SetupState* ss, int column) {
   char title[32]; xsnprintf(title, sizeof(title), "Column %d", column + 1);
   Panel* p = Panel_new(0, 0, 0, 0, MeterItem_display, MeterItem_delete, true, FunctionBar_new(MetersFunctions, MetersKeys, MetersEvents));
   MetersPanelData* d = xcalloc(1, sizeof(MetersPanelData));
   d->ss = ss; d->column = column;
   p->state = d;
   p->eventHandler = MetersPanel_eventHandler;
   Panel_setHeader(p, title);
   MetersPanel_fill(p, ss, column);
   return p;
}

typedef struct AvailableMeterItem_ { const MeterClass* type; unsigned int param; char* name; } AvailableMeterItem;
static void AvailableMeterItem_display(const void* item, RichString* out) {
   const AvailableMeterItem* a = item;
   RichString_writeAscii(out, CRT_colors[DEFAULT_COLOR], a->name);
}
static void AvailableMeterItem_delete(void* p) { AvailableMeterItem* a = p; if (!a) return; free(a->name); free(a); }

static HandlerResult AvailableMeters_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   AvailableMeterItem* sel = Panel_getSelected(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case 'l': case 'L': case KEY_F(5): {
      if (!sel) return IGNORED;
      int ncols = Header_columns(ss->header);
      int target = ncols - 1;
      Header_addMeterByClass(ss->header, sel->type, sel->param, target);
      Panel* tp = ss->columnPanels[target];
      MetersPanel_fill(tp, ss, target);
      Panel_setSelected(tp, Vector_size(ss->header->columns[target]) - 1);
      MetersPanel_setMoving(tp, true);
      Setup_rebuildHeaderAndRedraw(ss);
      ss->scr->allowFocusChange = true;
      return REDRAW | SYNTH_KEY | (KEY_LEFT << 16);
   }
   }
   return IGNORED;
}

static Panel* AvailableMeters_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, AvailableMeterItem_display, AvailableMeterItem_delete, true, FunctionBar_newEnterEsc("Add    ", "Done   "));
   p->state = ss;
   p->eventHandler = AvailableMeters_eventHandler;
   Panel_setHeader(p, "Available meters");
   extern const MeterClass CPUMeter_class;
   for (int i = 0; Platform_meterTypes[i]; i++) {
      const MeterClass* type = Platform_meterTypes[i];
      if (type == &CPUMeter_class) continue;
      AvailableMeterItem* a = xcalloc(1, sizeof(AvailableMeterItem));
      a->type = type; a->param = 0; a->name = xstrdup(type->uiName);
      Panel_add(p, a);
   }
   /* CPU meters */
   unsigned int cpus = ss->st->host->existingCPUs;
   AvailableMeterItem* avg = xcalloc(1, sizeof(AvailableMeterItem));
   avg->type = &CPUMeter_class; avg->param = 0; avg->name = xstrdup("CPU average");
   Panel_add(p, avg);
   for (unsigned int i = 1; i <= cpus; i++) {
      AvailableMeterItem* a = xcalloc(1, sizeof(AvailableMeterItem));
      a->type = &CPUMeter_class; a->param = i;
      a->name = xasprintf("CPU %u", ss->st->settings->countCPUsFromOne ? i : i - 1);
      Panel_add(p, a);
   }
   return p;
}

/* ================= Screens / Columns ================= */
static const char* const ScreensFunctions[] = { "      ", "Rename", "      ", "      ", "New   ", "      ", "MoveUp", "MoveDn", "Remove", "Done  ", NULL };
static const char* const ScreensRenamingFunctions[] = { "      ", "Cancel", "      ", "      ", "      ", "      ", "      ", "      ", "      ", "Done  ", NULL };
static const char* const ColumnsFunctions[] = { "      ", "      ", "      ", "      ", "      ", "      ", "MoveUp", "MoveDn", "Remove", "Done  ", NULL };
static const char* const AvailableColumnsFunctions[] = { "      ", "      ", "      ", "      ", "Add   ", "      ", "      ", "      ", "      ", "Done  ", NULL };
static FunctionBar* ScreensRenamingBar = NULL;

typedef struct ScreenItem_ { ScreenSettings* ss; bool moving; } ScreenItem;
static SetupState* screensSetup = NULL;
static void ScreenItem_display(const void* item, RichString* out) {
   const ScreenItem* si = item;
   RichString_prune(out);
   if (screensSetup && screensSetup->renaming && screensSetup->screens && Panel_getSelected(screensSetup->screens) == item) {
      RichString_appendAscii(out, CRT_colors[PANEL_EDIT], screensSetup->renameBuf);
      return;
   }
   if (si->moving) RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], "+ ");
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], si->ss->heading);
}
static void ScreenItem_delete(void* p) { free(p); }

static void Columns_fill(SetupState* ss) {
   Panel* p = ss->activeColumns;
   Panel_prune(p);
   ScreenItem* si = Panel_getSelected(ss->screens);
   if (!si) return;
   for (int i = 0; si->ss->fields[i]; i++) Panel_add(p, ListItem_new(Process_fields[si->ss->fields[i]].name, si->ss->fields[i]));
}

static void Columns_writeBack(SetupState* ss) {
   ScreenItem* si = Panel_getSelected(ss->screens);
   if (!si) return;
   Panel* p = ss->activeColumns;
   int n = Panel_size(p);
   int* fields = xcalloc(n + 1, sizeof(int));
   for (int i = 0; i < n; i++) fields[i] = ((ListItem*)Panel_get(p, i))->key;
   fields[n] = 0;
   free(si->ss->fields);
   si->ss->fields = fields;
   si->ss->flags = 0;
   for (int i = 0; i < n; i++) si->ss->flags |= Process_fields[fields[i]].flags;
   ss->st->settings->changed = true;
}

static void Screens_syncSettings(SetupState* ss) {
   Settings* settings = ss->st->settings;
   int n = Panel_size(ss->screens);
   ScreenSettings** screens = xcalloc(n + 1, sizeof(ScreenSettings*));
   for (int i = 0; i < n; i++) screens[i] = ((ScreenItem*)Panel_get(ss->screens, i))->ss;
   free(settings->screens);
   settings->screens = screens;
   settings->nScreens = n;
   /* keep current */
   bool found = false;
   for (int i = 0; i < n; i++) if (screens[i] == settings->ss) { settings->ssIndex = i; found = true; }
   if (!found) { settings->ssIndex = 0; settings->ss = screens[0]; }
   settings->changed = true;
}

static void Screens_startRenaming(SetupState* ss) {
   ScreenItem* si = Panel_getSelected(ss->screens);
   if (!si) return;
   ss->renaming = true;
   xsnprintf(ss->renameBuf, sizeof(ss->renameBuf), "%s", si->ss->heading);
   ss->renameLen = strlen(ss->renameBuf);
   ss->screens->currentBar = ScreensRenamingBar;
   ss->screens->needsRedraw = true;
}

static HandlerResult Screens_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   ScreenItem* sel = Panel_getSelected(super);
   int selected = Panel_getSelectedIndex(super);
   if (ss->renaming) {
      if (ch == 13 || ch == KEY_ENTER || ch == '\n') {
         if (sel) {
            char* t = string_trim(ss->renameBuf);
            if (t[0]) { free(sel->ss->heading); sel->ss->heading = t; } else free(t);
         }
         ss->renaming = false;
         super->currentBar = super->defaultBar;
         super->needsRedraw = true;
         DisplayOptions_updateScreenText(ss);
         ss->st->settings->changed = true;
         return HANDLED | REDRAW;
      } else if (ch == 27 || ch == KEY_F(2)) {
         ss->renaming = false;
         super->currentBar = super->defaultBar;
         super->needsRedraw = true;
         return HANDLED | REDRAW;
      } else if (ch == KEY_BACKSPACE || ch == 127) {
         if (ss->renameLen > 0) { ss->renameBuf[--ss->renameLen] = 0; }
         super->needsRedraw = true;
         return HANDLED | REDRAW;
      } else if (ch > 0 && ch < 255 && isprint(ch)) {
         if (ss->renameLen < (int)sizeof(ss->renameBuf) - 1) { ss->renameBuf[ss->renameLen++] = ch; ss->renameBuf[ss->renameLen] = 0; }
         super->needsRedraw = true;
         return HANDLED | REDRAW;
      }
      return HANDLED;
   }
   HandlerResult result = IGNORED;
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK:
      if (!sel) break;
      sel->moving = !sel->moving;
      super->selectionColorId = sel->moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
      result = HANDLED | REDRAW;
      break;
   case KEY_F(2): case KEY_CTRL('R'):
      Screens_startRenaming(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_F(5): case KEY_CTRL('N'): {
      ScreenSettings* news = Settings_newScreen(ss->st->settings, "New", "PID Command");
      /* move it to right after the selected one */
      Settings* settings = ss->st->settings;
      /* remove from end, insert after selected */
      settings->nScreens--;
      ScreenItem* si = xcalloc(1, sizeof(ScreenItem)); si->ss = news;
      Panel_insert(super, selected + 1, si);
      Panel_setSelected(super, selected + 1);
      Screens_syncSettings(ss);
      Columns_fill(ss);
      Screens_startRenaming(ss);
      result = HANDLED | REDRAW;
      break;
   }
   case KEY_UP:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(7): case '[': case '-':
      Panel_moveSelectedUp(super);
      Screens_syncSettings(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_DOWN:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(8): case ']': case '+':
      Panel_moveSelectedDown(super);
      Screens_syncSettings(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_F(9): case KEY_DC:
      if (Panel_size(super) > 1 && sel) {
         ScreenSettings* removed = sel->ss;
         Panel_remove(super, selected);
         Settings* settings = ss->st->settings;
         if (settings->ss == removed) { settings->ss = NULL; }
         Screens_syncSettings(ss);
         ScreenSettings_delete(removed);
         Columns_fill(ss);
         DisplayOptions_updateScreenText(ss);
         result = HANDLED | REDRAW;
      }
      break;
   case 27:
      if (sel && sel->moving) { sel->moving = false; super->selectionColorId = PANEL_SELECTION_FOCUS; return HANDLED | REDRAW; }
      break;
   default:
      break;
   }
   if (result == IGNORED && (ch == KEY_UP || ch == KEY_DOWN || ch == KEY_PPAGE || ch == KEY_NPAGE || ch == KEY_HOME || ch == KEY_END)) {
      Panel_onKey(super, ch);
      Columns_fill(ss);
      return HANDLED | REDRAW;
   }
   return result;
}

static Panel* Screens_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ScreenItem_display, ScreenItem_delete, true, FunctionBar_new(ScreensFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = Screens_eventHandler;
   Panel_setHeader(p, "Screens");
   Settings* settings = ss->st->settings;
   for (unsigned int i = 0; i < settings->nScreens; i++) {
      ScreenItem* si = xcalloc(1, sizeof(ScreenItem)); si->ss = settings->screens[i];
      Panel_add(p, si);
   }
   Panel_setSelected(p, settings->ssIndex);
   return p;
}

static HandlerResult Columns_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   ListItem* sel = Panel_getSelected(super);
   int selected = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK:
      if (!sel) break;
      sel->moving = !sel->moving;
      super->selectionColorId = sel->moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
      result = HANDLED | REDRAW;
      break;
   case KEY_UP:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(7): case '[': case '-':
      Panel_moveSelectedUp(super);
      Columns_writeBack(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_DOWN:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(8): case ']': case '+':
      Panel_moveSelectedDown(super);
      Columns_writeBack(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_F(9): case KEY_DC:
      if (Panel_size(super) > 1 && sel) {
         ListItem* it = Panel_remove(super, selected);
         ListItem_delete(it);
         Columns_writeBack(ss);
         result = HANDLED | REDRAW;
      }
      break;
   case 27:
      if (sel && sel->moving) { sel->moving = false; super->selectionColorId = PANEL_SELECTION_FOCUS; return HANDLED | REDRAW; }
      break;
   }
   return result;
}

static Panel* Columns_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_new(ColumnsFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = Columns_eventHandler;
   Panel_setHeader(p, "Active Columns");
   return p;
}

static HandlerResult AvailableColumns_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   ListItem* sel = Panel_getSelected(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case KEY_F(5): {
      if (!sel) break;
      Panel* cols = ss->activeColumns;
      int at = Panel_getSelectedIndex(cols);
      Panel_insert(cols, at + 1, ListItem_new(sel->value, sel->key));
      Panel_setSelected(cols, at + 1);
      Columns_writeBack(ss);
      return HANDLED | REDRAW;
   }
   }
   return IGNORED;
}

static Panel* AvailableColumns_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_new(AvailableColumnsFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = AvailableColumns_eventHandler;
   Panel_setHeader(p, "Available Columns");
   for (int i = 1; i < LAST_PROCESSFIELD; i++) {
      if (!Process_fields[i].name || !Process_fields[i].name[0]) continue;
      char* text = xasprintf("%s - %s", Process_fields[i].name, Process_fields[i].description);
      Panel_add(p, ListItem_new(text, i));
      free(text);
   }
   return p;
}

/* ================= Categories ================= */
static const char* const CategoryNames[] = { "Display options", "Header layout", "Meters", "Screens", "Colors", NULL };

void Setup_refreshHeaders(SetupState* ss) {
   Panel_setHeader(ss->displayOptions, "Display options");
   Panel_setHeader(ss->headerLayout, "Header Layout");
   Panel_setHeader(ss->colors, "Colors");
   for (int i = 0; i < 4; i++) if (ss->columnPanels[i]) { char t[32]; xsnprintf(t, sizeof(t), "Column %d", i + 1); Panel_setHeader(ss->columnPanels[i], t); }
   Panel_setHeader(ss->availableMeters, "Available meters");
   Panel_setHeader(ss->screens, "Screens");
   Panel_setHeader(ss->activeColumns, "Active Columns");
   Panel_setHeader(ss->availableColumns, "Available Columns");
   extern void MainPanel_rebuild(MainPanel*);
}

static void Setup_removeExtraPanels(SetupState* ss) {
   while (ss->scr->panelCount > 1) ScreenManager_remove(ss->scr, ss->scr->panelCount - 1);
}

static void Setup_showCategory(SetupState* ss, int cat) {
   Setup_removeExtraPanels(ss);
   ss->currentCategory = cat;
   switch (cat) {
   case 0: ScreenManager_add(ss->scr, ss->displayOptions, -1); break;
   case 1: ScreenManager_add(ss->scr, ss->headerLayout, -1); break;
   case 2: {
      int ncols = Header_columns(ss->header);
      for (int i = 0; i < ncols; i++) { MetersPanel_fill(ss->columnPanels[i], ss, i); ScreenManager_add(ss->scr, ss->columnPanels[i], 20); }
      ScreenManager_add(ss->scr, ss->availableMeters, -1);
      break;
   }
   case 3:
      Columns_fill(ss);
      ScreenManager_add(ss->scr, ss->screens, 20);
      ScreenManager_add(ss->scr, ss->activeColumns, 20);
      ScreenManager_add(ss->scr, ss->availableColumns, -1);
      break;
   case 4: ScreenManager_add(ss->scr, ss->colors, -1); break;
   }
   ScreenManager_resize(ss->scr);
}

void Setup_rebuildMeterPanels(SetupState* ss) {
   for (int i = 0; i < 4; i++) MetersPanel_fill(ss->columnPanels[i], ss, i);
}

static HandlerResult Categories_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   int previous = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   switch (ch) {
   case EVENT_SET_SELECTED: case KEY_UP: case KEY_DOWN: case KEY_NPAGE: case KEY_PPAGE: case KEY_HOME: case KEY_END: case KEY_MOUSE: case KEY_RECLICK: case KEY_WHEELUP: case KEY_WHEELDOWN:
      if (ch != KEY_MOUSE && ch != KEY_RECLICK) Panel_onKey(super, ch);
      result = HANDLED | REDRAW;
      break;
   }
   int selected = Panel_getSelectedIndex(super);
   if (previous != selected || ch == KEY_MOUSE || ch == KEY_RECLICK) {
      Setup_showCategory(ss, selected);
      result = HANDLED | REDRAW;
   }
   return result;
}

static Panel* Categories_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_new(SetupFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = Categories_eventHandler;
   Panel_setHeader(p, "Categories");
   for (int i = 0; CategoryNames[i]; i++) Panel_add(p, ListItem_new(CategoryNames[i], i));
   return p;
}

void Action_runSetup(State* st) {
   SetupState* ss = xcalloc(1, sizeof(SetupState));
   ss->st = st;
   ss->header = st->header;
   if (!MetersMovingBar) MetersMovingBar = FunctionBar_new(MetersMovingFunctions, MetersMovingKeys, MetersMovingEvents);
   if (!ScreensRenamingBar) ScreensRenamingBar = FunctionBar_new(ScreensRenamingFunctions, NULL, NULL);
   screensSetup = ss;
   ScreenManager* scr = ScreenManager_new(st->header, st->host, st, false);
   ss->scr = scr;
   ss->categories = Categories_new(ss);
   ss->displayOptions = DisplayOptions_new(ss);
   ss->headerLayout = HeaderLayout_new(ss);
   ss->colors = Colors_new(ss);
   for (int i = 0; i < 4; i++) ss->columnPanels[i] = MetersPanel_new(ss, i);
   ss->availableMeters = AvailableMeters_new(ss);
   ss->screens = Screens_new(ss);
   ss->activeColumns = Columns_new(ss);
   ss->availableColumns = AvailableColumns_new(ss);
   ScreenManager_add(scr, ss->categories, 16);
   Setup_showCategory(ss, 0);
   /* temporarily show "[Setup]" tab */
   Settings* settings = st->settings;
   ScreenSettings* savedSs = settings->ss;
   ScreenSettings** savedScreens = settings->screens;
   unsigned int savedN = settings->nScreens;
   ScreenSettings setupTab; memset(&setupTab, 0, sizeof(setupTab)); setupTab.heading = (char*)"Setup";
   ScreenSettings* tabs[2] = { &setupTab, NULL };
   settings->screens = tabs; settings->nScreens = 1; settings->ss = &setupTab;
   /* but panels need real settings->ss: restore pointer for ss-related items */
   settings->ss = savedSs;
   /* draw tabs manually: ScreenManager draws tabs from settings->screens; it checks settings->ss == screens[s] for current.
      Use a trick: mark setupTab current by comparing heading. */
   extern bool ScreenManager_setupTabHack;
   ScreenManager_setupTabHack = true;
   clear();
   Panel* panelFocus; int ch;
   ScreenManager_run(scr, &panelFocus, &ch, "Setup");
   ScreenManager_setupTabHack = false;
   settings->screens = savedScreens; settings->nScreens = savedN;
   /* sync screens from panel (they may have changed) */
   Screens_syncSettings(ss);
   if (!settings->ss) { settings->ss = settings->screens[0]; settings->ssIndex = 0; }
   /* write back header */
   Header_writeBackToSettings(ss->header);
   Header_calculateHeight(ss->header);
   CRT_setMouse(settings->enableMouse);
   /* cleanup */
   Setup_removeExtraPanels(ss);
   ScreenManager_remove(scr, 0);
   ScreenManager_delete(scr);
   Panel_delete(ss->categories);
   Panel_delete(ss->displayOptions);
   Panel_delete(ss->headerLayout);
   Panel_delete(ss->colors);
   for (int i = 0; i < 4; i++) { free(ss->columnPanels[i]->state); Panel_delete(ss->columnPanels[i]); }
   Panel_delete(ss->availableMeters);
   Panel_delete(ss->screens);
   Panel_delete(ss->activeColumns);
   Panel_delete(ss->availableColumns);
   screensSetup = NULL;
   currentScreenTextItem = NULL;
   free(ss);
   st->pt->needsSort = true;
   clear();
}
EOF
echo ok"}

actions.command:
cd /workspace/src; cat > setup.c <<'EOF'
#include "mainpanel.h"
#include "crt.h"
#include <math.h>

/* ================= option items ================= */
typedef enum OptionKind_ { OPT_CHECK, OPT_NUMBER, OPT_TEXT } OptionKind;
typedef struct OptionItem_ {
   OptionKind kind;
   char* text;
   bool* ref;
   int* numRef;
   int scale;   /* 10 → shown with 1 decimal */
   int min, max;
   bool bold;
} OptionItem;

static OptionItem* OptionItem_newCheck(const char* text, bool* ref) { OptionItem* o = xcalloc(1, sizeof(OptionItem)); o->kind = OPT_CHECK; o->text = xstrdup(text); o->ref = ref; return o; }
static OptionItem* OptionItem_newNumber(const char* text, int* ref, int scale, int min, int max) { OptionItem* o = xcalloc(1, sizeof(OptionItem)); o->kind = OPT_NUMBER; o->text = xstrdup(text); o->numRef = ref; o->scale = scale; o->min = min; o->max = max; return o; }
static OptionItem* OptionItem_newText(const char* text, bool bold) { OptionItem* o = xcalloc(1, sizeof(OptionItem)); o->kind = OPT_TEXT; o->text = xstrdup(text); o->bold = bold; return o; }
static void OptionItem_delete(void* p) { OptionItem* o = p; if (!o) return; free(o->text); free(o); }
static void OptionItem_display(const void* item, RichString* out) {
   const OptionItem* o = item;
   char buf[32];
   switch (o->kind) {
   case OPT_CHECK:
      RichString_writeAscii(out, CRT_colors[CHECK_BOX], "[");
      RichString_appendAscii(out, CRT_colors[CHECK_MARK], *o->ref ? "x" : " ");
      RichString_appendAscii(out, CRT_colors[CHECK_BOX], "]");
      RichString_appendAscii(out, CRT_colors[CHECK_TEXT], "    ");
      RichString_appendAscii(out, CRT_colors[CHECK_TEXT], o->text);
      break;
   case OPT_NUMBER: {
      if (o->scale > 1) {
         int v = *o->numRef;
         xsnprintf(buf, sizeof(buf), "%d.%d", v / o->scale, v % o->scale);
      } else xsnprintf(buf, sizeof(buf), "%d", *o->numRef);
      RichString_writeAscii(out, CRT_colors[CHECK_BOX], "[");
      RichString_appendAscii(out, CRT_colors[CHECK_MARK], buf);
      RichString_appendAscii(out, CRT_colors[CHECK_BOX], "]");
      int pad = 7 - (int)strlen(buf) - 2;
      if (pad < 1) pad = 1;
      RichString_appendChr(out, CRT_colors[CHECK_TEXT], ' ', pad);
      RichString_appendAscii(out, CRT_colors[CHECK_TEXT], o->text);
      break;
   }
   case OPT_TEXT:
      RichString_writeAscii(out, o->bold ? CRT_colors[HELP_BOLD] : CRT_colors[CHECK_TEXT], o->text);
      break;
   }
}

/* ================= shared setup state ================= */
typedef struct SetupState_ {
   State* st;
   ScreenManager* scr;
   Header* header;
   Panel* categories;
   Panel* columnPanels[4];
   Panel* availableMeters;
   Panel* screens;
   Panel* activeColumns;
   Panel* availableColumns;
   Panel* displayOptions;
   Panel* headerLayout;
   Panel* colors;
   int currentCategory;
   /* meters move state */
   int movingColumn;
   /* screens rename */
   bool renaming;
   char renameBuf[128];
   int renameLen;
} SetupState;

static const char* const SetupFunctions[] = { "      ", "      ", "      ", "      ", "      ", "      ", "      ", "      ", "      ", "Done  ", NULL };

static void Setup_rebuildHeaderAndRedraw(SetupState* ss) {
   Header* header = ss->header;
   Header_writeBackToSettings(header);
   Header_calculateHeight(header);
   ScreenManager_resize(ss->scr);
   ss->st->settings->changed = true;
}

/* ================= Display options ================= */
static OptionItem* currentScreenTextItem = NULL;

static void DisplayOptions_updateScreenText(SetupState* ss) {
   if (!currentScreenTextItem) return;
   free(currentScreenTextItem->text);
   currentScreenTextItem->text = xasprintf("For current screen tab: %s", ss->st->settings->ss->heading);
}

static HandlerResult DisplayOptions_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   HandlerResult result = IGNORED;
   OptionItem* selected = Panel_getSelected(super);
   if (!selected) return IGNORED;
   switch (ch) {
   case '\n': case '\r': case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case ' ':
      if (selected->kind == OPT_CHECK) { *selected->ref = !*selected->ref; result = HANDLED; }
      else if (selected->kind == OPT_NUMBER) {
         int v = *selected->numRef + (selected->scale > 1 ? selected->scale : 1);
         if (v > selected->max) v = selected->min;
         *selected->numRef = v;
         result = HANDLED;
      }
      break;
   case '-':
      if (selected->kind == OPT_NUMBER) { int v = *selected->numRef - (selected->scale > 1 ? selected->scale : 1); if (v < selected->min) v = selected->min; *selected->numRef = v; result = HANDLED; }
      break;
   case '+':
      if (selected->kind == OPT_NUMBER) { int v = *selected->numRef + (selected->scale > 1 ? selected->scale : 1); if (v > selected->max) v = selected->max; *selected->numRef = v; result = HANDLED; }
      break;
   }
   if (result == HANDLED) {
      Settings* settings = ss->st->settings;
      settings->changed = true;
      /* re-init header (cpu captions) and mouse */
      Header_reinit(ss->header);
      Header_calculateHeight(ss->header);
      CRT_setMouse(settings->enableMouse);
      ScreenManager_resize(ss->scr);
      result |= REDRAW;
      super->needsRedraw = true;
   }
   return result;
}

static Panel* DisplayOptions_new(SetupState* ss) {
   Settings* settings = ss->st->settings;
   Panel* p = Panel_new(0, 0, 0, 0, OptionItem_display, OptionItem_delete, true, FunctionBar_new(SetupFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = DisplayOptions_eventHandler;
   Panel_setHeader(p, "Display options");
   currentScreenTextItem = OptionItem_newText("", false);
   Panel_add(p, currentScreenTextItem);
   DisplayOptions_updateScreenText(ss);
   Panel_add(p, OptionItem_newCheck("Tree view", &settings->ss->treeView));
   Panel_add(p, OptionItem_newCheck("- Tree view is always sorted by PID (htop 2 behavior)", &settings->ss->treeViewAlwaysByPID));
   Panel_add(p, OptionItem_newCheck("- Tree view is collapsed by default", &settings->ss->allBranchesCollapsed));
   Panel_add(p, OptionItem_newText("Global options:", true));
   Panel_add(p, OptionItem_newCheck("Show tabs for screens", &settings->screenTabs));
   Panel_add(p, OptionItem_newCheck("Shadow other users' processes", &settings->shadowOtherUsers));
   Panel_add(p, OptionItem_newCheck("Hide kernel threads", &settings->hideKernelThreads));
   Panel_add(p, OptionItem_newCheck("Hide userland process threads", &settings->hideUserlandThreads));
   Panel_add(p, OptionItem_newCheck("Hide processes running in containers", &settings->hideRunningInContainer));
   Panel_add(p, OptionItem_newCheck("Display threads in a different color", &settings->highlightThreads));
   Panel_add(p, OptionItem_newCheck("Show custom thread names", &settings->showThreadNames));
   Panel_add(p, OptionItem_newCheck("Show program path", &settings->showProgramPath));
   Panel_add(p, OptionItem_newCheck("Highlight program \"basename\"", &settings->highlightBaseName));
   Panel_add(p, OptionItem_newCheck("Highlight out-dated/removed programs (red) / libraries (yellow)", &settings->highlightDeletedExe));
   Panel_add(p, OptionItem_newCheck("Shadow distribution path prefixes", &settings->shadowDistPathPrefix));
   Panel_add(p, OptionItem_newCheck("Merge exe, comm and cmdline in Command", &settings->showMergedCommand));
   Panel_add(p, OptionItem_newCheck("- Try to find comm in cmdline (when Command is merged)", &settings->findCommInCmdline));
   Panel_add(p, OptionItem_newCheck("- Try to strip exe from cmdline (when Command is merged)", &settings->stripExeFromCmdline));
   Panel_add(p, OptionItem_newCheck("Highlight large numbers in memory counters", &settings->highlightMegabytes));
   Panel_add(p, OptionItem_newCheck("Leave a margin around header", &settings->headerMargin));
   Panel_add(p, OptionItem_newCheck("Detailed CPU time (System/IO-Wait/Hard-IRQ/Soft-IRQ/Steal/Guest)", &settings->detailedCPUTime));
   Panel_add(p, OptionItem_newCheck("Count CPUs from 1 instead of 0", &settings->countCPUsFromOne));
   Panel_add(p, OptionItem_newCheck("Update process names on every refresh", &settings->updateProcessNames));
   Panel_add(p, OptionItem_newCheck("Add guest time in CPU meter percentage", &settings->accountGuestInCPUMeter));
   Panel_add(p, OptionItem_newCheck("Also show CPU percentage numerically", &settings->showCPUUsage));
   Panel_add(p, OptionItem_newCheck("Also show CPU frequency", &settings->showCPUFrequency));
   Panel_add(p, OptionItem_newCheck("Show cached memory in graph and bar modes", &settings->showCachedMemory));
   Panel_add(p, OptionItem_newCheck("Enable the mouse", &settings->enableMouse));
   Panel_add(p, OptionItem_newNumber("Update interval (in seconds)", &settings->delay, 10, 1, 255));
   Panel_add(p, OptionItem_newCheck("Highlight new and old processes", &settings->highlightChanges));
   Panel_add(p, OptionItem_newNumber("- Highlight time (in seconds)", &settings->highlightDelaySecs, 1, 1, 24 * 60 * 60));
   Panel_add(p, OptionItem_newNumber("Hide main function bar (0 - off, 1 - on ESC until next input, 2 - permanently)", &settings->hideFunctionBar, 1, 0, 2));
   return p;
}

/* ================= Header layout ================= */
static HandlerResult HeaderLayout_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   int mark = Panel_getSelectedIndex(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case ' ':
      for (int i = 0; i < Panel_size(super); i++) CheckItem_set(Panel_get(super, i), i == mark);
      Header_setLayout(ss->header, mark);
      Settings_setHeaderLayout(ss->st->settings, mark);
      Setup_rebuildHeaderAndRedraw(ss);
      /* rebuild meter column panels */
      extern void Setup_rebuildMeterPanels(SetupState* ss);
      Setup_rebuildMeterPanels(ss);
      super->needsRedraw = true;
      return HANDLED | REDRAW;
   }
   return IGNORED;
}

static Panel* HeaderLayout_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, CheckItem_display, CheckItem_delete, true, FunctionBar_new(SetupFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = HeaderLayout_eventHandler;
   Panel_setHeader(p, "Header Layout");
   for (int i = 0; i < LAST_HEADER_LAYOUT; i++) Panel_add(p, CheckItem_newByVal(HeaderLayout_layouts[i].description, i == (int)ss->st->settings->hLayout));
   return p;
}

/* ================= Colors ================= */
static const char* const ColorSchemeNames[] = { "Default", "Monochromatic", "Black on White", "Light Terminal", "MC", "Black Night", "Broken Gray", "Nord", NULL };

static HandlerResult Colors_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   int mark = Panel_getSelectedIndex(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case ' ':
      for (int i = 0; i < Panel_size(super); i++) CheckItem_set(Panel_get(super, i), i == mark);
      ss->st->settings->colorScheme = mark;
      ss->st->settings->changed = true;
      CRT_setColors(mark);
      clear();
      /* refresh panel headers */
      Panel_setHeader(ss->categories, "Categories");
      Panel_setHeader(super, "Colors");
      extern void Setup_refreshHeaders(SetupState*);
      Setup_refreshHeaders(ss);
      extern void MainPanel_rebuild(MainPanel*);
      MainPanel_rebuild(ss->st->mainPanel);
      return HANDLED | REDRAW;
   }
   return IGNORED;
}

static Panel* Colors_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, CheckItem_display, CheckItem_delete, true, FunctionBar_new(SetupFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = Colors_eventHandler;
   Panel_setHeader(p, "Colors");
   for (int i = 0; ColorSchemeNames[i]; i++) Panel_add(p, CheckItem_newByVal(ColorSchemeNames[i], i == ss->st->settings->colorScheme));
   return p;
}

/* ================= Meters ================= */
typedef struct MeterItem_ { Meter* meter; bool moving; } MeterItem;
static void MeterItem_display(const void* item, RichString* out) {
   const MeterItem* mi = item;
   char buf[128];
   const char* name = Meter_getUiName(mi->meter, buf, sizeof(buf));
   RichString_prune(out);
   if (mi->moving) RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], "+ ");
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], name);
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], " [");
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], Meter_modeNames[mi->meter->mode]);
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], "]");
}
static void MeterItem_delete(void* p) { free(p); }

static const char* const MetersFunctions[] = { "Style ", "Move  ", "                                       ", "Delete", "Done  ", NULL };
static const char* const MetersKeys[] = { "Space", "Enter", "  ", "Del", "F10" };
static const int MetersEvents[] = { ' ', 13, ERR, KEY_DC, KEY_F(10) };
static const char* const MetersMovingFunctions[] = { "Style ", "Lock  ", "Up    ", "Down  ", "Left  ", "Right ", "       ", "Delete", "Done  ", NULL };
static const char* const MetersMovingKeys[] = { "Space", "Enter", "Up", "Dn", "<-", "->", "  ", "Del", "F10" };
static const int MetersMovingEvents[] = { ' ', 13, KEY_UP, KEY_DOWN, KEY_LEFT, KEY_RIGHT, ERR, KEY_DC, KEY_F(10) };
static FunctionBar* MetersMovingBar = NULL;

typedef struct MetersPanelData_ { SetupState* ss; int column; bool moving; } MetersPanelData;

static void MetersPanel_fill(Panel* p, SetupState* ss, int column) {
   Panel_prune(p);
   Vector* meters = ss->header->columns[column];
   for (int i = 0; i < Vector_size(meters); i++) {
      MeterItem* mi = xcalloc(1, sizeof(MeterItem));
      mi->meter = Vector_get(meters, i);
      Panel_add(p, mi);
   }
}

static void MetersPanel_setMoving(Panel* p, bool moving) {
   MetersPanelData* d = p->state;
   d->moving = moving;
   MeterItem* mi = Panel_getSelected(p);
   if (mi) mi->moving = moving;
   p->currentBar = moving ? MetersMovingBar : p->defaultBar;
   p->selectionColorId = moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
   p->needsRedraw = true;
}

static HandlerResult MetersPanel_eventHandler(Panel* super, int ch) {
   MetersPanelData* d = super->state;
   SetupState* ss = d->ss;
   Header* header = ss->header;
   Vector* meters = header->columns[d->column];
   int selected = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   bool sideMove = false;
   MeterItem* mi = Panel_getSelected(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK:
      if (!mi) break;
      MetersPanel_setMoving(super, !d->moving);
      result = HANDLED | REDRAW;
      break;
   case ' ': case KEY_F(4): case 't':
      if (!mi) break;
      Meter_setMode(mi->meter, Meter_nextSupportedMode(mi->meter));
      Setup_rebuildHeaderAndRedraw(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_UP:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(7): case '[': case '-':
      if (selected > 0) { Vector_moveUp(meters, selected); Panel_moveSelectedUp(super); }
      result = HANDLED | REDRAW;
      break;
   case KEY_DOWN:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(8): case ']': case '+':
      if (selected + 1 < Vector_size(meters)) { Vector_moveDown(meters, selected); Panel_moveSelectedDown(super); }
      result = HANDLED | REDRAW;
      break;
   case KEY_RIGHT:
      sideMove = true;
      /* fallthrough */
   case KEY_LEFT: {
      if (!d->moving) break;
      int ncols = Header_columns(header);
      int target = d->column + (sideMove ? 1 : -1);
      if (target < 0 || target >= ncols) { result = HANDLED; break; }
      /* move the meter to the target column */
      Meter* m = Vector_remove(meters, selected);
      Vector_add(header->columns[target], m);
      MetersPanel_setMoving(super, false);
      MetersPanel_fill(super, ss, d->column);
      Panel_setSelected(super, selected);
      Panel* tp = ss->columnPanels[target];
      MetersPanel_fill(tp, ss, target);
      Panel_setSelected(tp, Vector_size(header->columns[target]) - 1);
      MetersPanel_setMoving(tp, true);
      Setup_rebuildHeaderAndRedraw(ss);
      /* request focus change */
      result = HANDLED | REDRAW | SYNTH_KEY | ((sideMove ? KEY_RIGHT : KEY_LEFT) << 16);
      /* let ScreenManager move focus: return IGNORED-like with key */
      ss->scr->allowFocusChange = true;
      return REDRAW | SYNTH_KEY | ((sideMove ? KEY_RIGHT : KEY_LEFT) << 16);
   }
   case KEY_DC: case KEY_BACKSPACE: case 127:
      if (!mi) break;
      if (selected < Vector_size(meters)) {
         MetersPanel_setMoving(super, false);
         Meter* m = Vector_remove(meters, selected);
         Meter_delete(m);
         MetersPanel_fill(super, ss, d->column);
         Panel_setSelected(super, selected);
         Setup_rebuildHeaderAndRedraw(ss);
      }
      result = HANDLED | REDRAW;
      break;
   case 27: case KEY_F(10): case 'q':
      if (d->moving) { MetersPanel_setMoving(super, false); return HANDLED | REDRAW; }
      break;
   }
   if (result & HANDLED) {
      Setup_rebuildHeaderAndRedraw(ss);
      super->needsRedraw = true;
   }
   return result;
}

static Panel* MetersPanel_new(SetupState* ss, int column) {
   char title[32]; xsnprintf(title, sizeof(title), "Column %d", column + 1);
   Panel* p = Panel_new(0, 0, 0, 0, MeterItem_display, MeterItem_delete, true, FunctionBar_new(MetersFunctions, MetersKeys, MetersEvents));
   MetersPanelData* d = xcalloc(1, sizeof(MetersPanelData));
   d->ss = ss; d->column = column;
   p->state = d;
   p->eventHandler = MetersPanel_eventHandler;
   Panel_setHeader(p, title);
   MetersPanel_fill(p, ss, column);
   return p;
}

typedef struct AvailableMeterItem_ { const MeterClass* type; unsigned int param; char* name; } AvailableMeterItem;
static void AvailableMeterItem_display(const void* item, RichString* out) {
   const AvailableMeterItem* a = item;
   RichString_writeAscii(out, CRT_colors[DEFAULT_COLOR], a->name);
}
static void AvailableMeterItem_delete(void* p) { AvailableMeterItem* a = p; if (!a) return; free(a->name); free(a); }

static HandlerResult AvailableMeters_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   AvailableMeterItem* sel = Panel_getSelected(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case 'l': case 'L': case KEY_F(5): {
      if (!sel) return IGNORED;
      int ncols = Header_columns(ss->header);
      int target = ncols - 1;
      Header_addMeterByClass(ss->header, sel->type, sel->param, target);
      Panel* tp = ss->columnPanels[target];
      MetersPanel_fill(tp, ss, target);
      Panel_setSelected(tp, Vector_size(ss->header->columns[target]) - 1);
      MetersPanel_setMoving(tp, true);
      Setup_rebuildHeaderAndRedraw(ss);
      ss->scr->allowFocusChange = true;
      return REDRAW | SYNTH_KEY | (KEY_LEFT << 16);
   }
   }
   return IGNORED;
}

static Panel* AvailableMeters_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, AvailableMeterItem_display, AvailableMeterItem_delete, true, FunctionBar_newEnterEsc("Add    ", "Done   "));
   p->state = ss;
   p->eventHandler = AvailableMeters_eventHandler;
   Panel_setHeader(p, "Available meters");
   extern const MeterClass CPUMeter_class;
   for (int i = 0; Platform_meterTypes[i]; i++) {
      const MeterClass* type = Platform_meterTypes[i];
      if (type == &CPUMeter_class) continue;
      AvailableMeterItem* a = xcalloc(1, sizeof(AvailableMeterItem));
      a->type = type; a->param = 0; a->name = xstrdup(type->uiName);
      Panel_add(p, a);
   }
   /* CPU meters */
   unsigned int cpus = ss->st->host->existingCPUs;
   AvailableMeterItem* avg = xcalloc(1, sizeof(AvailableMeterItem));
   avg->type = &CPUMeter_class; avg->param = 0; avg->name = xstrdup("CPU average");
   Panel_add(p, avg);
   for (unsigned int i = 1; i <= cpus; i++) {
      AvailableMeterItem* a = xcalloc(1, sizeof(AvailableMeterItem));
      a->type = &CPUMeter_class; a->param = i;
      a->name = xasprintf("CPU %u", ss->st->settings->countCPUsFromOne ? i : i - 1);
      Panel_add(p, a);
   }
   return p;
}

/* ================= Screens / Columns ================= */
static const char* const ScreensFunctions[] = { "      ", "Rename", "      ", "      ", "New   ", "      ", "MoveUp", "MoveDn", "Remove", "Done  ", NULL };
static const char* const ScreensRenamingFunctions[] = { "      ", "Cancel", "      ", "      ", "      ", "      ", "      ", "      ", "      ", "Done  ", NULL };
static const char* const ColumnsFunctions[] = { "      ", "      ", "      ", "      ", "      ", "      ", "MoveUp", "MoveDn", "Remove", "Done  ", NULL };
static const char* const AvailableColumnsFunctions[] = { "      ", "      ", "      ", "      ", "Add   ", "      ", "      ", "      ", "      ", "Done  ", NULL };
static FunctionBar* ScreensRenamingBar = NULL;

typedef struct ScreenItem_ { ScreenSettings* ss; bool moving; } ScreenItem;
static SetupState* screensSetup = NULL;
static void ScreenItem_display(const void* item, RichString* out) {
   const ScreenItem* si = item;
   RichString_prune(out);
   if (screensSetup && screensSetup->renaming && screensSetup->screens && Panel_getSelected(screensSetup->screens) == item) {
      RichString_appendAscii(out, CRT_colors[PANEL_EDIT], screensSetup->renameBuf);
      return;
   }
   if (si->moving) RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], "+ ");
   RichString_appendAscii(out, CRT_colors[DEFAULT_COLOR], si->ss->heading);
}
static void ScreenItem_delete(void* p) { free(p); }

static void Columns_fill(SetupState* ss) {
   Panel* p = ss->activeColumns;
   Panel_prune(p);
   ScreenItem* si = Panel_getSelected(ss->screens);
   if (!si) return;
   for (int i = 0; si->ss->fields[i]; i++) Panel_add(p, ListItem_new(Process_fields[si->ss->fields[i]].name, si->ss->fields[i]));
}

static void Columns_writeBack(SetupState* ss) {
   ScreenItem* si = Panel_getSelected(ss->screens);
   if (!si) return;
   Panel* p = ss->activeColumns;
   int n = Panel_size(p);
   int* fields = xcalloc(n + 1, sizeof(int));
   for (int i = 0; i < n; i++) fields[i] = ((ListItem*)Panel_get(p, i))->key;
   fields[n] = 0;
   free(si->ss->fields);
   si->ss->fields = fields;
   si->ss->flags = 0;
   for (int i = 0; i < n; i++) si->ss->flags |= Process_fields[fields[i]].flags;
   ss->st->settings->changed = true;
}

static void Screens_syncSettings(SetupState* ss) {
   Settings* settings = ss->st->settings;
   int n = Panel_size(ss->screens);
   ScreenSettings** screens = xcalloc(n + 1, sizeof(ScreenSettings*));
   for (int i = 0; i < n; i++) screens[i] = ((ScreenItem*)Panel_get(ss->screens, i))->ss;
   free(settings->screens);
   settings->screens = screens;
   settings->nScreens = n;
   /* keep current */
   bool found = false;
   for (int i = 0; i < n; i++) if (screens[i] == settings->ss) { settings->ssIndex = i; found = true; }
   if (!found) { settings->ssIndex = 0; settings->ss = screens[0]; }
   settings->changed = true;
}

static void Screens_startRenaming(SetupState* ss) {
   ScreenItem* si = Panel_getSelected(ss->screens);
   if (!si) return;
   ss->renaming = true;
   xsnprintf(ss->renameBuf, sizeof(ss->renameBuf), "%s", si->ss->heading);
   ss->renameLen = strlen(ss->renameBuf);
   ss->screens->currentBar = ScreensRenamingBar;
   ss->screens->needsRedraw = true;
}

static HandlerResult Screens_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   ScreenItem* sel = Panel_getSelected(super);
   int selected = Panel_getSelectedIndex(super);
   if (ss->renaming) {
      if (ch == 13 || ch == KEY_ENTER || ch == '\n') {
         if (sel) {
            char* t = string_trim(ss->renameBuf);
            if (t[0]) { free(sel->ss->heading); sel->ss->heading = t; } else free(t);
         }
         ss->renaming = false;
         super->currentBar = super->defaultBar;
         super->needsRedraw = true;
         DisplayOptions_updateScreenText(ss);
         ss->st->settings->changed = true;
         return HANDLED | REDRAW;
      } else if (ch == 27 || ch == KEY_F(2)) {
         ss->renaming = false;
         super->currentBar = super->defaultBar;
         super->needsRedraw = true;
         return HANDLED | REDRAW;
      } else if (ch == KEY_BACKSPACE || ch == 127) {
         if (ss->renameLen > 0) { ss->renameBuf[--ss->renameLen] = 0; }
         super->needsRedraw = true;
         return HANDLED | REDRAW;
      } else if (ch > 0 && ch < 255 && isprint(ch)) {
         if (ss->renameLen < (int)sizeof(ss->renameBuf) - 1) { ss->renameBuf[ss->renameLen++] = ch; ss->renameBuf[ss->renameLen] = 0; }
         super->needsRedraw = true;
         return HANDLED | REDRAW;
      }
      return HANDLED;
   }
   HandlerResult result = IGNORED;
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK:
      if (!sel) break;
      sel->moving = !sel->moving;
      super->selectionColorId = sel->moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
      result = HANDLED | REDRAW;
      break;
   case KEY_F(2): case KEY_CTRL('R'):
      Screens_startRenaming(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_F(5): case KEY_CTRL('N'): {
      ScreenSettings* news = Settings_newScreen(ss->st->settings, "New", "PID Command");
      /* move it to right after the selected one */
      Settings* settings = ss->st->settings;
      /* remove from end, insert after selected */
      settings->nScreens--;
      ScreenItem* si = xcalloc(1, sizeof(ScreenItem)); si->ss = news;
      Panel_insert(super, selected + 1, si);
      Panel_setSelected(super, selected + 1);
      Screens_syncSettings(ss);
      Columns_fill(ss);
      Screens_startRenaming(ss);
      result = HANDLED | REDRAW;
      break;
   }
   case KEY_UP:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(7): case '[': case '-':
      Panel_moveSelectedUp(super);
      Screens_syncSettings(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_DOWN:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(8): case ']': case '+':
      Panel_moveSelectedDown(super);
      Screens_syncSettings(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_F(9): case KEY_DC:
      if (Panel_size(super) > 1 && sel) {
         ScreenSettings* removed = sel->ss;
         Panel_remove(super, selected);
         Settings* settings = ss->st->settings;
         if (settings->ss == removed) { settings->ss = NULL; }
         Screens_syncSettings(ss);
         ScreenSettings_delete(removed);
         Columns_fill(ss);
         DisplayOptions_updateScreenText(ss);
         result = HANDLED | REDRAW;
      }
      break;
   case 27:
      if (sel && sel->moving) { sel->moving = false; super->selectionColorId = PANEL_SELECTION_FOCUS; return HANDLED | REDRAW; }
      break;
   default:
      break;
   }
   if (result == IGNORED && (ch == KEY_UP || ch == KEY_DOWN || ch == KEY_PPAGE || ch == KEY_NPAGE || ch == KEY_HOME || ch == KEY_END)) {
      Panel_onKey(super, ch);
      Columns_fill(ss);
      return HANDLED | REDRAW;
   }
   return result;
}

static Panel* Screens_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ScreenItem_display, ScreenItem_delete, true, FunctionBar_new(ScreensFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = Screens_eventHandler;
   Panel_setHeader(p, "Screens");
   Settings* settings = ss->st->settings;
   for (unsigned int i = 0; i < settings->nScreens; i++) {
      ScreenItem* si = xcalloc(1, sizeof(ScreenItem)); si->ss = settings->screens[i];
      Panel_add(p, si);
   }
   Panel_setSelected(p, settings->ssIndex);
   return p;
}

static HandlerResult Columns_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   ListItem* sel = Panel_getSelected(super);
   int selected = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK:
      if (!sel) break;
      sel->moving = !sel->moving;
      super->selectionColorId = sel->moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS;
      result = HANDLED | REDRAW;
      break;
   case KEY_UP:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(7): case '[': case '-':
      Panel_moveSelectedUp(super);
      Columns_writeBack(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_DOWN:
      if (!sel || !sel->moving) break;
      /* fallthrough */
   case KEY_F(8): case ']': case '+':
      Panel_moveSelectedDown(super);
      Columns_writeBack(ss);
      result = HANDLED | REDRAW;
      break;
   case KEY_F(9): case KEY_DC:
      if (Panel_size(super) > 1 && sel) {
         ListItem* it = Panel_remove(super, selected);
         ListItem_delete(it);
         Columns_writeBack(ss);
         result = HANDLED | REDRAW;
      }
      break;
   case 27:
      if (sel && sel->moving) { sel->moving = false; super->selectionColorId = PANEL_SELECTION_FOCUS; return HANDLED | REDRAW; }
      break;
   }
   return result;
}

static Panel* Columns_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_new(ColumnsFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = Columns_eventHandler;
   Panel_setHeader(p, "Active Columns");
   return p;
}

static HandlerResult AvailableColumns_eventHandler(Panel* super, int ch) {
   SetupState* ss = super->state;
   ListItem* sel = Panel_getSelected(super);
   switch (ch) {
   case 0x0a: case 0x0d: case KEY_ENTER: case KEY_MOUSE: case KEY_RECLICK: case KEY_F(5): {
      if (!sel) break;
      Panel* cols = ss->activeColumns;
      int at = Panel_getSelectedIndex(cols);
      Panel_insert(cols, at + 1, ListItem_new(sel->value, sel->key));
      Panel_setSelected(cols, at + 1);
      Columns_writeBack(ss);
      return HANDLED | REDRAW;
   }
   }
   return IGNORED;
}

static Panel* AvailableColumns_new(SetupState* ss) {
   Panel* p = Panel_new(0, 0, 0, 0, ListItem_display, ListItem_delete, true, FunctionBar_new(AvailableColumnsFunctions, NULL, NULL));
   p->state = ss;
   p->eventHandler = AvailableColumns_eventHandler;
   Panel_setHeader(p, "Available Columns");
   for (int i = 1; i < LAST_PROCESSFIELD; i++) {
      if (!Process_fields[i].name || !Process_fields[i].name[0]) continue;
      char* text = xasprintf("%s - %s", Process_fields[i].name, Process_fields[i].description);
      Panel_add(p, ListItem_new(text, i));
      free(text);
   }
   return p;
}

