typedef struct CommandLineSettings_ {
   int* pidMatchList;
   char* commFilter;
   uid_t userId;
   int sortKey;
   int delay;
   bool useColors;
   bool enableMouse;
   bool treeView;
   bool allowUnicode;
   bool highlightChanges;
   int highlightDelaySecs;
   bool readonly;
   bool hideMeters;
   bool hideFunctionBar;
   unsigned int iterationsRemaining;
} CommandLineSettings;

static void printColumnsHelp(void) {
   for (int j = 1; j < LAST_PROCESSFIELD; j++) {
      if (!Process_fields[j].name || !Process_fields[j].name[0]) continue;
      printf("%19s %s\n", Process_fields[j].name, Process_fields[j].description);
   }
}

static bool parseArgs(int argc, char** argv, CommandLineSettings* flags, int* exitCode) {
   *flags = (CommandLineSettings) {
      .pidMatchList = NULL, .commFilter = NULL, .userId = (uid_t)-1, .sortKey = 0, .delay = -1, .useColors = true, .enableMouse = true,
      .treeView = false, .allowUnicode = true, .highlightChanges = false, .highlightDelaySecs = -1, .readonly = false, .hideMeters = false,
      .hideFunctionBar = false, .iterationsRemaining = (unsigned int)-1,
   };
   static const struct option long_opts[] = {
      {"help", no_argument, 0, 'h'},
      {"version", no_argument, 0, 'V'},
      {"delay", required_argument, 0, 'd'},
      {"max-iterations", required_argument, 0, 'n'},
      {"sort-key", required_argument, 0, 's'},
      {"user", optional_argument, 0, 'u'},
      {"no-color", no_argument, 0, 'C'},
      {"no-colour", no_argument, 0, 'C'},
      {"no-mouse", no_argument, 0, 'M'},
      {"no-unicode", no_argument, 0, 'U'},
      {"no-meters", no_argument, 0, 130},
      {"no-function-bar", no_argument, 0, 131},
      {"tree", no_argument, 0, 't'},
      {"pid", required_argument, 0, 'p'},
      {"filter", required_argument, 0, 'F'},
      {"highlight-changes", optional_argument, 0, 'H'},
      {"readonly", no_argument, 0, 128},
      {0, 0, 0, 0}
   };
   int opt, opti = 0;
   while ((opt = getopt_long(argc, argv, "hVMCs:td:n:u::Up:F:H::", long_opts, &opti))) {
      if (opt == EOF) break;
      switch (opt) {
      case 'h': printHelpFlag(); *exitCode = 0; return false;
      case 'V': printVersionFlag(); *exitCode = 0; return false;
      case 's':
         if (strcmp(optarg, "help") == 0) { printColumnsHelp(); *exitCode = 0; return false; }
         flags->sortKey = Fields_fromName(optarg);
         if (flags->sortKey == 0) { fprintf(stderr, "Error: invalid column \"%s\".\n", optarg); *exitCode = 1; return false; }
         break;
      case 'd':
         if (sscanf(optarg, "%16d", &flags->delay) == 1) {
            if (flags->delay < 1) flags->delay = 1;
            if (flags->delay > 100) flags->delay = 100;
         } else {
            fprintf(stderr, "Error: invalid delay value \"%s\".\n", optarg); *exitCode = 1; return false;
         }
         break;
      case 'n': {
         int n;
         if (sscanf(optarg, "%16d", &n) == 1) {
            if (n <= 0) { fprintf(stderr, "Error: maximum iteration count must be positive.\n"); *exitCode = 1; return false; }
            flags->iterationsRemaining = n;
         } else {
            fprintf(stderr, "Error: invalid maximum iteration count \"%s\".\n", optarg); *exitCode = 1; return false;
         }
         break;
      }
      case 'u': {
         const char* username = optarg;
         if (!username && optind < argc && argv[optind] != NULL && (argv[optind][0] != '\0' && argv[optind][0] != '-')) {
            username = argv[optind++];
         }
         if (!username) {
            flags->userId = geteuid();
         } else {
            struct passwd* pw = getpwnam(username);
            if (pw) flags->userId = pw->pw_uid;
            else {
               char* end; unsigned long v = strtoul(username, &end, 10);
               bool numeric = username[0] && *end == '\0';
               if (numeric && (pw = getpwuid((uid_t)v)) != NULL) flags->userId = pw->pw_uid;
               else if (numeric) flags->userId = (uid_t)v;
               else { fprintf(stderr, "Error: invalid user \"%s\".\n", username); *exitCode = 1; return false; }
            }
         }
         break;
      }
      case 'C': flags->useColors = false; break;
      case 'M': flags->enableMouse = false; break;
      case 'U': flags->allowUnicode = false; break;
      case 't': flags->treeView = true; break;
      case 'p': {
         char* argCopy = xstrdup(optarg);
         char* saveptr;
         char* pid = strtok_r(argCopy, ",", &saveptr);
         int cap = 16, n = 0;
         if (!flags->pidMatchList) { flags->pidMatchList = xmalloc(cap * sizeof(int)); flags->pidMatchList[0] = -1; }
         else { while (flags->pidMatchList[n] >= 0) n++; cap = n + 16; flags->pidMatchList = xrealloc(flags->pidMatchList, cap * sizeof(int)); }
         while (pid) {
            unsigned int num = (unsigned int)atoi(pid);
            if (n + 2 > cap) { cap *= 2; flags->pidMatchList = xrealloc(flags->pidMatchList, cap * sizeof(int)); }
            flags->pidMatchList[n++] = (int)num;
            pid = strtok_r(NULL, ",", &saveptr);
         }
         flags->pidMatchList[n] = -1;
         free(argCopy);
         break;
      }
      case 'F': {
         bool ok = optarg[0] != '\0';
         for (const char* c = optarg; *c; c++) if (!isprint((unsigned char)*c)) ok = false;
         if (!ok) { fprintf(stderr, "Error: invalid filter value \"%s\".\n", optarg); *exitCode = 1; return false; }
         free(flags->commFilter);
         flags->commFilter = xstrdup(optarg);
         break;
      }
      case 'H': {
         const char* delay = optarg;
         if (!delay && optind < argc && argv[optind] != NULL && (argv[optind][0] != '\0' && argv[optind][0] != '-')) {
            delay = argv[optind++];
         }
         if (delay) {
            int d;
            if (sscanf(delay, "%16d", &d) == 1 && d >= 0) flags->highlightDelaySecs = d;
            else { fprintf(stderr, "Error: invalid highlight delay value \"%s\".\n", delay); *exitCode = 1; return false; }
         }
         flags->highlightChanges = true;
         break;
      }
      case 128: flags->readonly = true; break;
      case 130: flags->hideMeters = true; break;
      case 131: flags->hideFunctionBar = true; break;
      default: *exitCode = 1; return false;
      }
   }
   if (optind < argc) {
      fprintf(stderr, "Error: unsupported non-option ARGV-elements:");
      while (optind < argc) fprintf(stderr, " %s", argv[optind++]);
      fprintf(stderr, "\n");
      *exitCode = 1; return false;
   }
   return true;
}

static void millisleep(unsigned long millisec) {
   struct timespec req = { .tv_sec = millisec / 1000, .tv_nsec = (millisec % 1000) * 1000000L };
   while (nanosleep(&req, &req) == -1) continue;
}

int main(int argc, char** argv) {
   setlocale(LC_CTYPE, "");
   CommandLineSettings flags;
   int exitCode = 0;
   if (!parseArgs(argc, argv, &flags, &exitCode)) return exitCode;
   if (flags.readonly) Settings_enableReadonly();
