static void printVersionFlag(void) {
   printf("htop " PROGRAM_VERSION "\n");
}

static void printHelpFlag(void) {
   printf("htop " PROGRAM_VERSION "\n"
          COPYRIGHT_TEXT "\n"
          "Released under the GNU GPLv2+.\n\n"
          "-C --no-color                   Use a monochrome color scheme\n"
