   if (flags.highlightDelaySecs != -1) settings->highlightDelaySecs = flags.highlightDelaySecs;
   if (flags.sortKey > 0) {
      ScreenSettings* ss = settings->ss;
      ss->sortKey = flags.sortKey;
      ss->direction = Process_fields[flags.sortKey].defaultSortDesc ? -1 : 1;
      ss->treeView = false;
   }
   if (flags.treeView) settings->ss->treeView = true;
   CRT_init(settings, flags.allowUnicode);
   Header* header = Header_new(host, settings, settings->hLayout);
   Header_populateFromSettings(header);
   ProcessTable* pt = ProcessTable_new(host, settings, flags.pidMatchList, flags.userId);
   State state = { .settings = settings, .host = host, .pt = pt, .header = header, .pauseUpdate = false, .hideProcessSelection = false, .hideMeters = flags.hideMeters, .hideSelection = false, .mainPanel = NULL };
   MainPanel* panel = MainPanel_new(&state);
   if (flags.commFilter) MainPanel_setFilter(panel, flags.commFilter);
   ScreenManager* scr = ScreenManager_new(header, host, &state, false);
   ScreenManager_add(scr, &panel->super, -1);
   Machine_scan(host);
   ProcessTable_scan(pt, false);
   millisleep(75);
   Machine_scan(host);
   ProcessTable_scan(pt, false);
   if (host->iterationsRemaining != (unsigned int)-1 && host->iterationsRemaining > 0) host->iterationsRemaining--;
   MainPanel_rebuild(panel);
   Header_updateData(header);
   if (settings->ss->allBranchesCollapsed) ProcessTable_collapseAllBranches(pt);
   ScreenManager_run(scr, NULL, NULL, NULL);
   attron(CRT_colors[RESET_COLOR]);
   mvhline(LINES - 1, 0, ' ', COLS);
   attroff(CRT_colors[RESET_COLOR]);
   refresh();
   CRT_done();
   if (settings->changed) {
      int r = Settings_write(settings, false);
      if (r < 0) fprintf(stderr, "Can not save configuration to %s: %s\n", settings->filename, strerror(-r));
   }
   ScreenManager_delete(scr);
   MainPanel_delete(panel);
   Header_delete(header);
   ProcessTable_delete(pt);
   Machine_delete(host);
   Settings_delete(settings);
   free(flags.commFilter);
   free(flags.pidMatchList);
   return 0;
}
